/* View: ABC */
CREATE VIEW ABC(
    PRO_CODIGO,
    PRO_GRU,
    PRO_DESCRICAO,
    VEN_DATA,
    VE_VALOR,
    VE_QUANTIDADE,
    VE_LUCRO,
    VEN_DATAC)
AS
SELECT P.PRO_CODIGO, PRO_GRU, PRO_DESCRICAO, V.VEN_DATA, VE.VE_VALOR, VE.VE_QUANTIDADE, VE_LUCRO, VEN_DATAC
FROM VENDAS V, VEN_EST VE, PRODUTOS P
WHERE V.VEN_CODIGO = VE.VE_VEN AND VE.VE_PRO = P.PRO_CODIGO
;



/* View: CLIENTE_INATIVO */
CREATE VIEW CLIENTE_INATIVO(
    CLI_CODIGO)
AS
SELECT CLI_CODIGO FROM CLIENTES WHERE CLI_SITUACAO = 'Duvidoso'
;



/* View: CLIENTES_FORNECEDORES */
CREATE VIEW CLIENTES_FORNECEDORES(
    CF_CODIGO,
    CF_NOME,
    CF_ENDERECO,
    CF_BAIRRO,
    CF_CEP,
    CF_FONE,
    CF_EMAIL,
    CF_DATAC,
    CF_TIPO,
    CF_CELULAR,
    CF_CNPJ_CPF,
    CF_INSC_ESTADUAL,
    CF_INSC_MUNICIPAL,
    CF_COD_PAIS,
    CF_SUFRAMA,
    CF_NUMERO,
    CF_COMPLEMENTO,
    CF_INDIC_IE,
    CF_CID,
    CF_IDENTIFICADOR,
    CF_RAZAO_SOCIAL,
    CF_ESTADO)
AS
SELECT 1000000 + CAST(CLI_CODIGO AS INTEGER), CLI_NOME, CLI_ENDERECO, CLI_BAIRRO, CLI_CEP, CLI_FONE, CLI_EMAIL,
    CAST(CLI_DATAC AS DATE), CLI_TIPO, CLI_CELULAR, CLI_CNPJ_CPF, CLI_INSC_ESTADUAL, CLI_INSC_MUNICIPAL,
    CLI_COD_PAIS, CLI_SUFRAMA, CLI_NUMERO, CLI_COMPLEMENTO, CLI_INDIC_IE, CLI_CID, 'C' AS CF_IDENTIFICADOR,
    CLI_RAZAO_SOCIAL, COALESCE(CLI_ESTADO, 'ATIVO') CF_ESTADO
    FROM CLIENTES    
    UNION    
    SELECT 2000000 + CAST(FOR_CODIGO AS INTEGER), FOR_NOME, FOR_ENDERECO, FOR_BAIRRO, FOR_CEP, FOR_FONE, FOR_EMAIL,
    CAST(FOR_DATAC AS DATE), FOR_TIPO, FOR_CELULAR, FOR_CNPJ_CPF, FOR_INSC_ESTADUAL, FOR_INSC_MUNICIPAL,
    FOR_COD_PAIS, FOR_SUFRAMA, FOR_END_NUMERO, FOR_COMPLEMENTO, FOR_INDIC_IE, FOR_CID, 'F' AS CF_IDENTIFICADOR,
    FOR_NOME, COALESCE(FOR_ESTADO, 'ATIVO') CF_ESTADO
    FROM FORNECEDORES
;
;



/* View: CONTA_RECEBER_A */
CREATE VIEW CONTA_RECEBER_A(
    VALORPG,
    CLI_CODIGO,
    CLI_NOME,
    REC_VALOR,
    REC_JUROS,
    REC_DESCONTOS,
    FAT_CODIGO,
    REC_VENCIMENTO,
    VEN_DATA,
    VEN_FUN)
AS
SELECT SUM(RP.RP_DINHEIRO+RP.RP_CHEQUE), C.CLI_CODIGO, C.CLI_NOME, R.REC_VALOR, R.REC_JUROS, R.REC_DESCONTOS, F.FAT_CODIGO, R.REC_VENCIMENTO, V.VEN_DATA, V.VEN_FUN
FROM FATURAMENTOS F, CLIENTES C, RECEBIMENTOS R, VENDAS V, REC_PGM RP
WHERE V.VEN_CODIGO = F.FAT_DESCRICAO AND F.FAT_TIPO = 1 AND F.FAT_CLI = C.CLI_CODIGO AND F.FAT_CODIGO = R.REC_FAT AND R.REC_CODIGO = RP.RP_REC AND R.REC_ESTADO <> 3
GROUP BY C.CLI_CODIGO, C.CLI_NOME, R.REC_VALOR, R.REC_JUROS, R.REC_DESCONTOS, F.FAT_CODIGO, R.REC_VENCIMENTO, V.VEN_DATA, V.VEN_FUN
;



/* View: DEVOLVE_CUSTO */
CREATE VIEW DEVOLVE_CUSTO(
    CUST_CODIGO,
    CUST_DATA,
    CUST_HISTORICO,
    CUST_VALOR,
    FAT2_CODIGO,
    SUC_NOME,
    CUST_TIPO,
    CUST_DATAC)
AS
SELECT C.CUST_CODIGO, C.CUST_DATA, C.CUST_HISTORICO, C.CUST_VALOR, F.FAT2_CODIGO, S.SUC_NOME, C.CUST_TIPO, C.CUST_DATAC
    FROM CUSTOS C, FATURAMENTO2 F, SUB_CUS S
    WHERE F.FAT2_TIPO = 2 AND F.FAT2_DESCRICAO = C.CUST_CODIGO AND C.CUST_SUD = S.SUC_CODIGO
;



/* View: DEVOLVE_DESPESA */
CREATE VIEW DEVOLVE_DESPESA(
    CUST_CODIGO,
    CUST_DATA,
    CUST_HISTORICO,
    CUST_VALOR,
    FAT2_CODIGO,
    SUD_NOME,
    CUST_TIPO,
    CUST_DATAC)
AS
SELECT C.CUST_CODIGO, C.CUST_DATA, C.CUST_HISTORICO, C.CUST_VALOR, F.FAT2_CODIGO, S.SUD_NOME, C.CUST_TIPO, C.CUST_DATAC
    FROM CUSTOS C, FATURAMENTO2 F, SUB_DES S
    WHERE F.FAT2_TIPO = 2 AND F.FAT2_DESCRICAO = C.CUST_CODIGO AND C.CUST_SUD = S.SUD_CODIGO
;



/* View: DEVOLVE_FRETE */
CREATE VIEW DEVOLVE_FRETE(
    FRE_CODIGO,
    FAT2_DATA,
    FRE_HISTORICO,
    FRE_VALOR,
    FAT2_CODIGO,
    TRA_NOME,
    FRE_DATAC)
AS
SELECT FR.FRE_CODIGO, F.FAT2_DATA, FR.FRE_HISTORICO, FR.FRE_VALOR, F.FAT2_CODIGO, TRA.TRA_NOME, FR.FRE_DATAC
    FROM FRETES FR, FATURAMENTO2 F, TRANSPORTADORAS TRA
    WHERE F.FAT2_TIPO = 4 AND F.FAT2_DESCRICAO = FR.FRE_CODIGO AND FR.FRE_TRA = TRA.TRA_CODIGO
;



/* View: DEVOLVE_PAGAMENTO */
CREATE VIEW DEVOLVE_PAGAMENTO(
    PAG_CODIGO,
    PAG_FAT2,
    PAG_DUPLICATA,
    PAG_VENCIMENTO,
    PAG_JUROS,
    PAG_DESCONTOS,
    PAG_VALOR,
    PP_DINHEIRO,
    PP_CHEQUE,
    PP_DATAPGM,
    PP_MOV,
    PP_JUROS,
    PP_DESCONTOS,
    PAG_TIPO)
AS
SELECT P.PAG_CODIGO, P.PAG_FAT2, P.PAG_DUPLICATA, P.PAG_VENCIMENTO, P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VALOR, PP.PP_DINHEIRO, PP.PP_CHEQUE, 
PP.PP_DATAPGM, PP.PP_MOV, PP.PP_JUROS, PP.PP_DESCONTOS, P.PAG_TIPO
    FROM PAGAMENTOS P, PAG_PGM PP
    WHERE P.PAG_CODIGO = PP.PP_PAG
;



/* View: DEVOLVE_PRO_PED_COM */
CREATE VIEW DEVOLVE_PRO_PED_COM(
    COM_FAT2,
    PRO_CODIGO,
    EST_NOME,
    CE_QUANTIDADE,
    CE_VALOR,
    FOR_NOME,
    COM_DATA,
    COM_VALOR,
    CE_CODIGO,
    COM_CODIGO,
    COM_NF,
    CE_IPI,
    COM_FOR,
    COM_NATUREZA,
    COM_IPI,
    COM_FRETE,
    COM_ICMS,
    COM_OUTROS,
    PRO_VALORC,
    PRO_VALORL,
    PRO_VALORF,
    PRO_VALORCM,
    PRO_VALORV,
    CE_VALORC,
    CE_VALORCM,
    CE_VALORM,
    CE_VALOROP,
    CE_VALORV)
AS
SELECT C.COM_FAT2, P.PRO_CODIGO, E.EST_NOME, CE.CE_QUANTIDADE, CE.CE_VALOR, F.FOR_NOME, C.COM_DATA, C.COM_VALOR, CE.CE_CODIGO, F.FOR_CODIGO, C.COM_NF, CE.CE_IPI, C.COM_FOR, C.COM_NATUREZA, COM_IPI, C.COM_FRETE, C.COM_ICMS, C.COM_OUTROS, P.PRO_VALORC, P.PRO_VALORL, P.PRO_VALORF, P.PRO_VALORCM, P.PRO_VALORV,
    CE_VALORC, CE_VALORCM, CE_VALORM, CE_VALOROP, CE_VALORV
    FROM FORNECEDORES F, COMPRAS C, COM_EST CE, PRODUTOS P, ESTOQUE E
    WHERE C.COM_CODIGO = CE.CE_COM AND C.COM_FOR = F.FOR_CODIGO
    AND E.EST_CODIGO = P.PRO_EST AND CE.CE_PRO = P.PRO_CODIGO
;



/* View: DEVOLVE_PRO_PED_VEN */
CREATE VIEW DEVOLVE_PRO_PED_VEN(
    VEN_FAT,
    PRO_CODIGO,
    PRO_DESCRICAO,
    VE_QUANTIDADE,
    VE_VALOR,
    CLI_NOME,
    VEN_DATA,
    VEN_VALOR,
    VE_CODIGO,
    VE_LUCRO,
    CLI_CODIGO,
    EST_NOME,
    VE_VALORR,
    VE_VALORL,
    PRO_VALORF,
    PRO_VALORC,
    PRO_VALORCM,
    PRO_VALORL,
    VEN_CODIGO,
    VEN_FUN,
    VE_VALORF,
    VEN_DATAC,
    VEN_HORA,
    CLI_ENDERECO,
    VE_LIQUIDO,
    VE_VALOR2,
    VE_ALIQUOTA,
    VE_EMBALAGEM,
    VE_GTIN,
    VE_VALORB,
    VE_DESCONTO)
AS
SELECT V.VEN_FAT, P.PRO_CODIGO, P.PRO_DESCRICAO, VE.VE_QUANTIDADE, VE.VE_VALOR, C.CLI_NOME, V.VEN_DATA, V.VEN_VALOR, VE.VE_CODIGO, VE.VE_LUCRO, C.CLI_CODIGO, E.EST_NOME, VE.VE_VALOR, VE.VE_VALORL, PRO_VALORF, PRO_VALORC, PRO_VALORCM, PRO_VALORL, VEN_CODIGO, V.VEN_FUN, VE.VE_VALORF, V.VEN_DATAC, V.VEN_HORA, C.CLI_ENDERECO, VE.VE_LIQUIDO, VE.VE_VALOR2, VE.VE_ALIQUOTA, VE.VE_EMBALAGEM, VE.VE_GTIN, VE.VE_VALORB, VE.VE_DESCONTO
    FROM CLIENTES C, VENDAS V, VEN_EST VE, PRODUTOS P, ESTOQUE E
    WHERE E.EST_CODIGO = P.PRO_EST AND V.VEN_CODIGO = VE.VE_VEN AND V.VEN_CLI = C.CLI_CODIGO
    AND E.EST_CODIGO = P.PRO_EST AND VE.VE_PRO = P.PRO_CODIGO
;



/* View: DEVOLVE_PRODUTO */
CREATE VIEW DEVOLVE_PRODUTO(
    CLI_NOME,
    FAT_CODIGO,
    CLI_CODIGO,
    FAT_TIPOPGM,
    FAT_PARCELAS,
    CLI_ENDERECO,
    PF_TABELA,
    PF_CAMPO_DATAC,
    PF_CAMPO_PED,
    PF_VALOR,
    PF_VALORPG,
    PF_PARCELAS,
    PF_DATA,
    PF_FUN,
    PF_COD_PED,
    PF_DATAC,
    PF_CODIGO)
AS
SELECT CLI_NOME, FAT_CODIGO, CLI_CODIGO, FAT_TIPOPGM, FAT_PARCELAS, CLI_ENDERECO, PF_TABELA, PF_CAMPO_DATAC, PF_CAMPO_PED, PF_VALOR, 
PF_VALORPG, PF_PARCELAS, PF_DATA, PF_FUN, PF_COD_PED, PF_DATAC, PF_CODIGO
    FROM CLIENTES, FATURAMENTOS, PED_FAT
    WHERE PF_FAT = FAT_CODIGO AND FAT_CLI = CLI_CODIGO AND PF_TIPO = 1
;



/* View: DEVOLVE_PRODUTOC */
CREATE VIEW DEVOLVE_PRODUTOC(
    PRO_CODIGO,
    PRO_NOME,
    CE_QUANTIDADE,
    CE_VALOR,
    FOR_NOME,
    COM_DATA,
    COM_VALOR,
    CE_CODIGO,
    FAT2_CODIGO,
    COM_CODIGO,
    COM_NF,
    CE_IPI,
    COM_FOR,
    COM_NATUREZA,
    COM_IPI,
    COM_FRETE,
    COM_ICMS,
    COM_OUTROS,
    PRO_VALORC,
    PRO_VALORL,
    PRO_VALORF,
    PRO_VALORCM,
    PRO_VALORV,
    CE_VALORC,
    CE_VALORCM,
    CE_VALORM,
    CE_VALOROP,
    CE_VALORV,
    CE_NVALORCM,
    PRO_QUANTIDADE,
    CE_DATA_ULT_COMPRA)
AS
SELECT P.PRO_CODIGO, PRO_NOME, CE.CE_QUANTIDADE, CE.CE_VALOR, F.FOR_NOME, C.COM_DATA,
    C.COM_VALOR, CE.CE_CODIGO, F2.FAT2_CODIGO, F.FOR_CODIGO, C.COM_NF, CE.CE_IPI,
    C.COM_FOR, C.COM_NATUREZA, COM_IPI, C.COM_FRETE, C.COM_ICMS, C.COM_OUTROS,
    P.PRO_VALORC, P.PRO_VALORL, P.PRO_VALORF, P.PRO_VALORCM, P.PRO_VALORV, CE_VALORC,
    CE_VALORCM, CE_VALORM, CE_VALOROP, CE_VALORV, CE_NVALORCM, P.PRO_QUANTIDADE,
    CE_DATA_ULT_COMPRA
    FROM FORNECEDORES F, COMPRAS C, COM_EST CE, PRODUTOS P, FATURAMENTO2 F2
    WHERE C.COM_CODIGO = CE.CE_COM AND C.COM_FOR = F.FOR_CODIGO AND F2.FAT2_TIPO = 1
    AND F2.FAT2_DESCRICAO = C.COM_CODIGO AND CE.CE_PRO = P.PRO_CODIGO AND COM_DATAC = '01/01/1900'
;



/* View: DEVOLVE_RECEBIMENTO */
CREATE VIEW DEVOLVE_RECEBIMENTO(
    REC_CODIGO,
    REC_FAT,
    REC_DUPLICATA,
    REC_VENCIMENTO,
    REC_JUROS,
    REC_DESCONTOS,
    REC_VALOR,
    RP_DINHEIRO,
    RP_CHEQUE,
    RP_DATAPGM,
    RP_MOV,
    RP_JUROS,
    RP_DESCONTOS)
AS
SELECT R.REC_CODIGO, R.REC_FAT, R.REC_DUPLICATA, R.REC_VENCIMENTO, R.REC_JUROS, R.REC_DESCONTOS, R.REC_VALOR, RP.RP_DINHEIRO, RP.RP_CHEQUE, 
RP.RP_DATAPGM, RP.RP_MOV, RP.RP_JUROS, RP.RP_DESCONTOS
    FROM RECEBIMENTOS R, REC_PGM RP
    WHERE R.REC_CODIGO = RP.RP_REC AND (R.REC_SITUACAO >= 0 AND R.REC_SITUACAO <= 2)
;



/* View: DEVOLVE_TRIBUTACAO */
CREATE VIEW DEVOLVE_TRIBUTACAO(
    TRI_CODIGO,
    FAT2_DATA,
    TRI_HISTORICO,
    TRI_VALOR,
    FAT2_CODIGO,
    IMP_NOME,
    TRI_DATAC)
AS
SELECT T.TRI_CODIGO, F.FAT2_DATA, T.TRI_HISTORICO, T.TRI_VALOR, F.FAT2_CODIGO, I.IMP_NOME, T.TRI_DATAC
    FROM TRIBUTACOES T, FATURAMENTO2 F, IMPOSTOS I
    WHERE F.FAT2_TIPO = 3 AND F.FAT2_DESCRICAO = T.TRI_CODIGO AND T.TRI_IMP = I.IMP_CODIGO
;



/* View: FOLHA */
CREATE VIEW FOLHA(
    FUN_CODIGO,
    FUN_NOME,
    FUN_ADMISSAO,
    FUN_DATAPGM,
    FOL_INSALUB,
    FOL_ESTADO,
    FOL_VALORSAL,
    FOL_MES,
    FOL_CODIGO)
AS
SELECT F.FUN_CODIGO, F.FUN_NOME, F.FUN_ADMISSAO, F.FUN_DATAPGM, FO.FOL_INSALUB, FO.FOL_ESTADO, FO.FOL_VALORSAL, FO.FOL_MES, FO.FOL_CODIGO
FROM FUNCIONARIOS F, FOLHA_PAGAMENTOS FO
WHERE FO.FOL_FUN = F.FUN_CODIGO AND FO.FOL_ESTADO = 'ATIVO'
;



/* View: LISTA_PRODUTO */
CREATE VIEW LISTA_PRODUTO(
    VEN_CODIGO,
    FAT_TIPOPGM,
    VEN_FUN,
    FAT_CLI,
    PRO_CODIGO,
    VEN_DATA,
    FAT_CODIGO,
    VE_QUANTIDADE,
    VE_VALOR,
    PRO_NOME,
    PRO_DESCRICAO,
    REC_CON)
AS
SELECT DISTINCT(V.VEN_CODIGO), F.FAT_TIPOPGM, V.VEN_FUN, F.FAT_CLI, P.PRO_CODIGO,
    V.VEN_DATA, F.FAT_CODIGO, VE.VE_QUANTIDADE, VE.VE_VALOR, PRO_NOME,
    P.PRO_DESCRICAO, R.REC_CON
    FROM CLIENTES C, FATURAMENTOS F, PRODUTOS P, VENDAS V, VEN_EST VE, RECEBIMENTOS R
    WHERE F.FAT_CODIGO = V.VEN_FAT AND V.VEN_CODIGO = VE.VE_VEN AND P.PRO_CODIGO = VE.VE_PRO
    AND F.FAT_CLI = C.CLI_CODIGO AND F.FAT_CODIGO = R.REC_FAT AND R.REC_ESTADO < 3
    AND R.REC_FPG = 1 AND (R.REC_SITUACAO >= 0 AND R.REC_SITUACAO < 3)
;



/* View: LISTA_PRODUTO2 */
CREATE VIEW LISTA_PRODUTO2(
    FAT_CODIGO,
    FAT_TIPOPGM,
    VEN_FUN,
    FAT_CLI,
    PRO_CODIGO,
    VEN_DATA,
    VEN_CODIGO,
    VE_QUANTIDADE,
    VE_VALOR,
    PRO_NOME,
    PRO_DESCRICAO,
    REC_FPG)
AS
SELECT DISTINCT(F.FAT_CODIGO), F.FAT_TIPOPGM, V.VEN_FUN, F.FAT_CLI, P.PRO_CODIGO,
    V.VEN_DATA, V.VEN_CODIGO, VE.VE_QUANTIDADE, VE.VE_VALOR, PRO_NOME, P.PRO_DESCRICAO,
    R.REC_FPG
    FROM CLIENTES C, FATURAMENTOS F, PRODUTOS P, VENDAS V, VEN_EST VE, RECEBIMENTOS R
    WHERE F.FAT_CODIGO = V.VEN_FAT AND V.VEN_CODIGO = VE.VE_VEN AND P.PRO_CODIGO = VE.VE_PRO
    AND F.FAT_CLI = C.CLI_CODIGO AND F.FAT_CODIGO = R.REC_FAT AND R.REC_ESTADO < 3
    AND REC_FPG = 0 AND (R.REC_SITUACAO >= 0 AND R.REC_SITUACAO < 3)
;



/* View: PAGA_CLIENTE */
CREATE VIEW PAGA_CLIENTE(
    FAT2_CODIGO,
    CLI_CODIGO,
    CLI_NOME,
    CLI_ENDERECO,
    PAG_CODIGO,
    PAG_DUPLICATA,
    PAG_VENCIMENTO,
    PAG_JUROS,
    PAG_DESCONTOS,
    PAG_VALOR,
    PAG_TIPO,
    VALOR_PG,
    PAG_CON,
    PAG_OBS)
AS
SELECT F.FAT2_CODIGO, C.CLI_CODIGO, C.CLI_NOME, C.CLI_ENDERECO, P.PAG_CODIGO, P.PAG_DUPLICATA,
P.PAG_VENCIMENTO, P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VALOR, P.PAG_TIPO,
SUM(PP.PP_DINHEIRO + PP.PP_CHEQUE), P.PAG_CON, P.PAG_OBS
FROM CLIENTES C, FATURAMENTO2 F, PAGAMENTOS P, PAG_PGM PP, TIPO_PGM TP, CREDITO_CLIENTE CC
WHERE TP.TP_CODIGO = P.PAG_CON AND TP.TP_CON IS NULL AND CC.CC_FAT2 = F.FAT2_CODIGO AND CC.CC_CLI = C.CLI_CODIGO AND P.PAG_CODIGO = PP.PP_PAG AND
F.FAT2_CODIGO = P.PAG_FAT2 AND P.PAG_ESTADO < 3
AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
GROUP BY F.FAT2_CODIGO, C.CLI_CODIGO, C.CLI_NOME, C.CLI_ENDERECO, P.PAG_CODIGO, P.PAG_DUPLICATA,
P.PAG_VENCIMENTO, P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VALOR, P.PAG_TIPO, P.PAG_CON, P.PAG_OBS
;



/* View: PAGA_CUSTO */
CREATE VIEW PAGA_CUSTO(
    FAT2_CODIGO,
    SUC_CODIGO,
    SUC_NOME,
    PAG_CODIGO,
    PAG_DUPLICATA,
    PAG_VENCIMENTO,
    PAG_JUROS,
    PAG_DESCONTOS,
    PAG_VALOR,
    PAG_TIPO,
    PAG_OBS,
    VALOR_PG,
    PAG_CON)
AS
SELECT F.FAT2_CODIGO, S.SUC_CODIGO, S.SUC_NOME, P.PAG_CODIGO, P.PAG_DUPLICATA, P.PAG_VENCIMENTO,
P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VALOR, P.PAG_TIPO, P.PAG_OBS,
SUM(PP.PP_DINHEIRO + PP.PP_CHEQUE), P.PAG_CON
FROM SUB_CUS S, FATURAMENTO2 F, PAGAMENTOS P, PAG_PGM PP, TIPO_PGM TP, CUSTOS C
WHERE TP.TP_CODIGO = P.PAG_CON AND TP.TP_CON IS NULL AND F.FAT2_CODIGO = C.CUST_FAT2 AND C.CUST_SUD = S.SUC_CODIGO AND P.PAG_CODIGO = PP.PP_PAG 
AND
F.FAT2_CODIGO = P.PAG_FAT2 AND P.PAG_ESTADO < 3
AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
GROUP BY F.FAT2_CODIGO, S.SUC_CODIGO, S.SUC_NOME, P.PAG_CODIGO, P.PAG_DUPLICATA, P.PAG_VENCIMENTO,
P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VALOR, P.PAG_TIPO, P.PAG_OBS, P.PAG_CON
;



/* View: PAGA_DESPESA */
CREATE VIEW PAGA_DESPESA(
    FAT2_CODIGO,
    SUD_CODIGO,
    SUD_NOME,
    PAG_CODIGO,
    PAG_DUPLICATA,
    PAG_VENCIMENTO,
    PAG_JUROS,
    PAG_DESCONTOS,
    PAG_VALOR,
    PAG_TIPO,
    PAG_OBS,
    VALOR_PG,
    PAG_CON)
AS
SELECT F.FAT2_CODIGO, S.SUD_CODIGO, S.SUD_NOME, P.PAG_CODIGO, P.PAG_DUPLICATA, P.PAG_VENCIMENTO,
P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VALOR, P.PAG_TIPO, P.PAG_OBS,
SUM(PP.PP_DINHEIRO + PP.PP_CHEQUE), P.PAG_CON
FROM SUB_DES S, FATURAMENTO2 F, PAGAMENTOS P, PAG_PGM PP, TIPO_PGM TP, CUSTOS C
WHERE C.CUST_TIPO = 'D' AND TP.TP_CODIGO = P.PAG_CON AND TP.TP_CON IS NULL AND F.FAT2_CODIGO = C.CUST_FAT2 AND C.CUST_SUD = S.SUD_CODIGO AND 
P.PAG_CODIGO = PP.PP_PAG AND
F.FAT2_CODIGO = P.PAG_FAT2 AND P.PAG_ESTADO < 3
AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
GROUP BY F.FAT2_CODIGO, S.SUD_CODIGO, S.SUD_NOME, P.PAG_CODIGO, P.PAG_DUPLICATA, P.PAG_VENCIMENTO,
P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VALOR, P.PAG_TIPO, P.PAG_OBS, P.PAG_CON
;



/* View: PAGA_FINANCIAMENTO */
CREATE VIEW PAGA_FINANCIAMENTO(
    FAT2_CODIGO,
    FIN_CODIGO,
    FIN_NCONTRATO,
    FIN_DATA,
    FIN_VALOR,
    FIN_JUROSM,
    FIN_PARCELAS,
    CON_CONTAC,
    PAG_CODIGO,
    PAG_DUPLICATA,
    PAG_VENCIMENTO,
    PAG_JUROS,
    PAG_DESCONTOS,
    PAG_VALOR,
    PAG_TIPO,
    VALOR_PG,
    CON_CODIGO,
    CON_DESCRICAO,
    PAG_OBS)
AS
SELECT F.FAT2_CODIGO, FI.FIN_CODIGO, FI.FIN_NCONTRATO, FI.FIN_DATA, FI.FIN_VALOR, FI.FIN_JUROSM, FI.FIN_PARCELAS, C.CON_CONTAC, P.PAG_CODIGO, 
P.PAG_DUPLICATA, P.PAG_VENCIMENTO, P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VALOR, P.PAG_TIPO, SUM(PP.PP_DINHEIRO + PP.PP_CHEQUE), C.CON_CODIGO, 
C.CON_DESCRICAO, P.PAG_OBS
FROM FINANCIAMENTOS FI, FATURAMENTO2 F, PAGAMENTOS P, PAG_PGM PP, CONTAS C, TIPO_PGM TP
WHERE F.FAT2_CODIGO = FI.FIN_FAT2 AND P.PAG_CODIGO = PP.PP_PAG AND F.FAT2_CODIGO = P.PAG_FAT2 AND P.PAG_ESTADO < 3 AND
FI.FIN_TP = TP.TP_CODIGO AND TP.TP_CON = C.CON_CODIGO AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
GROUP BY F.FAT2_CODIGO, FI.FIN_CODIGO, FI.FIN_NCONTRATO, FI.FIN_DATA, FI.FIN_VALOR, FI.FIN_JUROSM, FI.FIN_PARCELAS, C.CON_CONTAC, P.PAG_CODIGO, 
P.PAG_DUPLICATA, P.PAG_VENCIMENTO, P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VALOR, P.PAG_TIPO, C.CON_CODIGO, C.CON_DESCRICAO, P.PAG_OBS
;



/* View: PAGA_FORNECEDOR */
CREATE VIEW PAGA_FORNECEDOR(
    FAT2_CODIGO,
    FOR_CODIGO,
    FOR_NOME,
    FOR_ENDERECO,
    PAG_CODIGO,
    PAG_DUPLICATA,
    PAG_VENCIMENTO,
    PAG_JUROS,
    PAG_DESCONTOS,
    PAG_VALOR,
    PAG_TIPO,
    PAG_OBS,
    VALOR_PG,
    PAG_CON)
AS
SELECT F.FAT2_CODIGO, FO.FOR_CODIGO, FO.FOR_NOME, FO.FOR_ENDERECO, P.PAG_CODIGO, P.PAG_DUPLICATA,
P.PAG_VENCIMENTO, P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VALOR, P.PAG_TIPO, P.PAG_OBS,
SUM(PP.PP_DINHEIRO + PP.PP_CHEQUE), P.PAG_CON
FROM FORNECEDORES FO, FATURAMENTO2 F, PAGAMENTOS P, PAG_PGM PP, TIPO_PGM TP, COMPRAS C
WHERE TP.TP_CODIGO = P.PAG_CON AND TP.TP_CON IS NULL AND F.FAT2_CODIGO = C.COM_FAT2 AND C.COM_FOR = FO.FOR_CODIGO AND P.PAG_CODIGO = PP.PP_PAG 
AND
F.FAT2_CODIGO = P.PAG_FAT2 AND P.PAG_ESTADO < 3
AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
GROUP BY F.FAT2_CODIGO, FO.FOR_CODIGO, FO.FOR_NOME, FO.FOR_ENDERECO, P.PAG_CODIGO, P.PAG_DUPLICATA, P.PAG_VENCIMENTO,
P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VALOR, P.PAG_TIPO, P.PAG_OBS, P.PAG_CON
;



/* View: PAGA_FORNECEDOR_CUST */
CREATE VIEW PAGA_FORNECEDOR_CUST(
    FAT2_CODIGO,
    FOR_CODIGO,
    FOR_NOME,
    FOR_ENDERECO,
    PAG_CODIGO,
    PAG_DUPLICATA,
    PAG_VENCIMENTO,
    PAG_JUROS,
    PAG_DESCONTOS,
    PAG_VALOR,
    PAG_TIPO,
    PAG_OBS,
    VALOR_PG,
    PAG_CON)
AS
SELECT F.FAT2_CODIGO, FO.FOR_CODIGO, FO.FOR_NOME, FO.FOR_ENDERECO, P.PAG_CODIGO, P.PAG_DUPLICATA,
P.PAG_VENCIMENTO, P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VALOR, P.PAG_TIPO, P.PAG_OBS,
SUM(PP.PP_DINHEIRO + PP.PP_CHEQUE), P.PAG_CON
FROM FORNECEDORES FO, FATURAMENTO2 F, PAGAMENTOS P, PAG_PGM PP, CUSTOS C, TIPO_PGM TP
WHERE TP.TP_CODIGO = P.PAG_CON AND TP.TP_CON IS NULL AND C.CUST_FAT2 = F.FAT2_CODIGO AND C.CUST_COD_FOR = FO.FOR_CODIGO AND F.FAT2_TIPO = 2
AND P.PAG_CODIGO = PP.PP_PAG AND F.FAT2_CODIGO = P.PAG_FAT2 AND P.PAG_ESTADO < 3
AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
GROUP BY F.FAT2_CODIGO, FO.FOR_CODIGO, FO.FOR_NOME, FO.FOR_ENDERECO, P.PAG_CODIGO, P.PAG_DUPLICATA, P.PAG_VENCIMENTO,
P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VALOR, P.PAG_TIPO, P.PAG_OBS, P.PAG_CON
;



/* View: PAGA_FORNECEDOR2 */
CREATE VIEW PAGA_FORNECEDOR2(
    FAT2_CODIGO,
    FOR_CODIGO,
    FOR_NOME,
    FOR_ENDERECO,
    PAG_CODIGO,
    PAG_DUPLICATA,
    PAG_VENCIMENTO,
    PAG_JUROS,
    PAG_DESCONTOS,
    PAG_VALOR,
    PAG_TIPO,
    PAG_OBS,
    VALOR_PG,
    PAG_CON)
AS
SELECT F.FAT2_CODIGO, FO.FOR_CODIGO, FO.FOR_NOME, FO.FOR_ENDERECO, P.PAG_CODIGO, P.PAG_DUPLICATA,
P.PAG_VENCIMENTO, P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VALOR, P.PAG_TIPO, P.PAG_OBS,
SUM(PP.PP_DINHEIRO + PP.PP_CHEQUE), P.PAG_CON
FROM FORNECEDORES FO, FATURAMENTO2 F, PAGAMENTOS P, PAG_PGM PP, TIPO_PGM TP, LANCAMENTO_REC_CUS L
WHERE TP.TP_CODIGO = P.PAG_CON AND TP.TP_CON IS NULL AND F.FAT2_CODIGO = L.LRC_FAT2 AND L.LRC_CLI_FOR = FO.FOR_CODIGO AND P.PAG_CODIGO = 
PP.PP_PAG AND
F.FAT2_CODIGO = P.PAG_FAT2 AND P.PAG_ESTADO < 3
AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
GROUP BY F.FAT2_CODIGO, FO.FOR_CODIGO, FO.FOR_NOME, FO.FOR_ENDERECO, P.PAG_CODIGO, P.PAG_DUPLICATA, P.PAG_VENCIMENTO,
P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VALOR, P.PAG_TIPO, P.PAG_OBS, P.PAG_CON
;



/* View: PAGA_FRETE */
CREATE VIEW PAGA_FRETE(
    FAT2_CODIGO,
    FAT2_DATA,
    TRA_CODIGO,
    TRA_NOME,
    PAG_CODIGO,
    PAG_DUPLICATA,
    PAG_VENCIMENTO,
    PAG_JUROS,
    PAG_DESCONTOS,
    PAG_VALOR,
    PAG_TIPO,
    PAG_OBS,
    VALOR_PG,
    PAG_CON)
AS
SELECT F.FAT2_CODIGO, FAT2_DATA, T.TRA_CODIGO, T.TRA_NOME, P.PAG_CODIGO, P.PAG_DUPLICATA,
P.PAG_VENCIMENTO, P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VALOR, P.PAG_TIPO, P.PAG_OBS,
SUM(PP.PP_DINHEIRO + PP.PP_CHEQUE), P.PAG_CON
FROM TRANSPORTADORAS T, FATURAMENTO2 F, PAGAMENTOS P, PAG_PGM PP, TIPO_PGM TP, FRETES FR
WHERE TP.TP_CODIGO = P.PAG_CON AND TP.TP_CON IS NULL AND F.FAT2_CODIGO = FR.FRE_FAT2 AND FR.FRE_TRA = T.TRA_CODIGO AND P.PAG_CODIGO = PP.PP_PAG 
AND
F.FAT2_CODIGO = P.PAG_FAT2 AND P.PAG_ESTADO < 3
AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
GROUP BY F.FAT2_CODIGO, FAT2_DATA, T.TRA_CODIGO, T.TRA_NOME, P.PAG_CODIGO, P.PAG_DUPLICATA,
P.PAG_VENCIMENTO, P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VALOR, P.PAG_TIPO, P.PAG_OBS, P.PAG_CON
;



/* View: PAGA_FUNCIONARIO */
CREATE VIEW PAGA_FUNCIONARIO(
    FAT2_CODIGO,
    FUN_CODIGO,
    FUN_NOME,
    FUN_ENDERECO,
    PAG_CODIGO,
    PAG_DUPLICATA,
    PAG_VENCIMENTO,
    PAG_JUROS,
    PAG_DESCONTOS,
    PAG_VALOR,
    PAG_TIPO,
    PAG_OBS,
    VALOR_PG,
    PAG_CON)
AS
SELECT F.FAT2_CODIGO, FU.FUN_CODIGO, FU.FUN_NOME, FU.FUN_ENDERECO, P.PAG_CODIGO, P.PAG_DUPLICATA,
P.PAG_VENCIMENTO, P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VALOR, P.PAG_TIPO, P.PAG_OBS,
SUM(PP.PP_DINHEIRO + PP.PP_CHEQUE), P.PAG_CON
FROM FUNCIONARIOS FU, FATURAMENTO2 F, PAGAMENTOS P, PAG_PGM PP, CUSTOS C, TIPO_PGM TP
WHERE TP.TP_CODIGO = P.PAG_CON AND TP.TP_CON IS NULL AND C.CUST_FAT2 = F.FAT2_CODIGO AND C.CUST_COD_FUN = FU.FUN_CODIGO AND
P.PAG_CODIGO = PP.PP_PAG AND F.FAT2_CODIGO = P.PAG_FAT2 AND P.PAG_ESTADO < 3
AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
GROUP BY F.FAT2_CODIGO, FU.FUN_CODIGO, FU.FUN_NOME, FU.FUN_ENDERECO, P.PAG_CODIGO, P.PAG_DUPLICATA,
P.PAG_VENCIMENTO, P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VALOR, P.PAG_TIPO, P.PAG_OBS, P.PAG_CON
;



/* View: PAGA_TRIBUTACAO */
CREATE VIEW PAGA_TRIBUTACAO(
    FAT2_CODIGO,
    FAT2_DATA,
    IMP_CODIGO,
    IMP_NOME,
    PAG_CODIGO,
    PAG_DUPLICATA,
    PAG_VENCIMENTO,
    PAG_JUROS,
    PAG_DESCONTOS,
    PAG_VALOR,
    PAG_TIPO,
    PAG_OBS,
    VALOR_PG,
    PAG_CON)
AS
SELECT F.FAT2_CODIGO, FAT2_DATA, I.IMP_CODIGO, I.IMP_NOME, P.PAG_CODIGO, P.PAG_DUPLICATA,
P.PAG_VENCIMENTO, P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VALOR, P.PAG_TIPO, P.PAG_OBS,
SUM(PP.PP_DINHEIRO + PP.PP_CHEQUE), P.PAG_CON
FROM IMPOSTOS I, FATURAMENTO2 F, PAGAMENTOS P, PAG_PGM PP, TIPO_PGM TP, TRIBUTACOES T
WHERE TP.TP_CODIGO = P.PAG_CON AND TP.TP_CON IS NULL AND F.FAT2_CODIGO = T.TRI_FAT2 AND T.TRI_IMP = I.IMP_CODIGO AND P.PAG_CODIGO = PP.PP_PAG AND
F.FAT2_CODIGO = P.PAG_FAT2 AND P.PAG_ESTADO < 3
AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
GROUP BY F.FAT2_CODIGO, FAT2_DATA, I.IMP_CODIGO, I.IMP_NOME, P.PAG_CODIGO, P.PAG_DUPLICATA,
P.PAG_VENCIMENTO, P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VALOR, P.PAG_TIPO, P.PAG_OBS, P.PAG_CON
;



/* View: RECEBE_CLIENTE */
CREATE VIEW RECEBE_CLIENTE(
    FAT_CODIGO,
    FAT_DATA,
    FAT_VALOR,
    CLI_CODIGO,
    CLI_NOME,
    CLI_ENDERECO,
    CLI_PLANO,
    CLI_LIMITE,
    CLI_SITUACAO,
    REC_CODIGO,
    REC_DUPLICATA,
    REC_VENCIMENTO,
    REC_JUROS,
    REC_DESCONTOS,
    REC_VALOR,
    REC_TIPO,
    REC_CON,
    REC_DATAR,
    REC_FPG,
    REC_DESCONTADO,
    REC_OBS,
    VALOR_PG)
AS
SELECT F.FAT_CODIGO, F.FAT_DATA, F.FAT_VALOR, C.CLI_CODIGO, C.CLI_NOME, C.CLI_ENDERECO,
    C.CLI_PLANO, C.CLI_LIMITE, C.CLI_SITUACAO, R.REC_CODIGO, R.REC_DUPLICATA, R.REC_VENCIMENTO,
    R.REC_JUROS, R.REC_DESCONTOS, R.REC_VALOR, R.REC_TIPO, R.REC_CON, R.REC_DATAR, R.REC_FPG,
    R.REC_DESCONTADO, R.REC_OBS, SUM(RP.RP_DINHEIRO + RP.RP_CHEQUE)
    FROM CLIENTES C, FATURAMENTOS F, RECEBIMENTOS R, REC_PGM RP
    WHERE R.REC_CODIGO = RP.RP_REC AND F.FAT_CLI = C.CLI_CODIGO AND F.FAT_CODIGO = R.REC_FAT
    AND (R.REC_SITUACAO >= 0 AND R.REC_SITUACAO < 3) AND R.REC_ESTADO < 3
    GROUP BY F.FAT_CODIGO, F.FAT_DATA, F.FAT_VALOR, C.CLI_CODIGO, C.CLI_NOME, C.CLI_ENDERECO,
    C.CLI_PLANO, C.CLI_LIMITE, C.CLI_SITUACAO, R.REC_CODIGO, R.REC_DUPLICATA, R.REC_VENCIMENTO,
    R.REC_JUROS, R.REC_DESCONTOS, R.REC_VALOR,  R.REC_TIPO, R.REC_CON, R.REC_DATAR,
    R.REC_FPG, R.REC_DESCONTADO, R.REC_OBS
;



/* View: RECEBE_CLIENTE_BC */
CREATE VIEW RECEBE_CLIENTE_BC(
    FAT_CODIGO,
    CLI_CODIGO,
    CLI_NOME,
    CLI_ENDERECO,
    CLI_PLANO,
    CLI_LIMITE,
    REC_CODIGO,
    REC_DUPLICATA,
    REC_VENCIMENTO,
    REC_JUROS,
    REC_DESCONTOS,
    REC_VALOR,
    REC_TIPO,
    REC_CON,
    VALOR_PG)
AS
SELECT F.FAT_CODIGO, C.CLI_CODIGO, C.CLI_NOME, C.CLI_ENDERECO, C.CLI_PLANO, C.CLI_LIMITE, R.REC_CODIGO, R.REC_DUPLICATA, R.REC_VENCIMENTO, R.REC_JUROS, R.REC_DESCONTOS, R.REC_VALOR, R.REC_TIPO, R.REC_CON, SUM(RP.RP_DINHEIRO + RP.RP_CHEQUE)
FROM CLIENTES C, FATURAMENTOS F, RECEBIMENTOS R, REC_PGM RP
WHERE R.REC_CODIGO = RP.RP_REC AND F.FAT_CLI = C.CLI_CODIGO AND F.FAT_CODIGO = R.REC_FAT AND R.REC_ESTADO < 3
AND (R.REC_SITUACAO >= 0 AND R.REC_SITUACAO < 3) AND R.REC_CON > 0
GROUP BY F.FAT_CODIGO, C.CLI_CODIGO, C.CLI_NOME, C.CLI_ENDERECO, C.CLI_PLANO, C.CLI_LIMITE, R.REC_CODIGO, R.REC_DUPLICATA, R.REC_VENCIMENTO, R.REC_JUROS, R.REC_DESCONTOS, R.REC_VALOR,  R.REC_TIPO, R.REC_CON
;



/* View: RECEBE_FORNECEDOR */
CREATE VIEW RECEBE_FORNECEDOR(
    FAT_CODIGO,
    FOR_CODIGO,
    FOR_NOME,
    FOR_ENDERECO,
    REC_CODIGO,
    REC_DUPLICATA,
    REC_VENCIMENTO,
    REC_JUROS,
    REC_DESCONTOS,
    REC_VALOR,
    REC_TIPO,
    REC_CON,
    REC_DATAR,
    REC_FPG,
    REC_DESCONTADO,
    REC_OBS,
    VALOR_PG)
AS
SELECT F.FAT_CODIGO, FO.FOR_CODIGO, FO.FOR_NOME, FO.FOR_ENDERECO, R.REC_CODIGO, R.REC_DUPLICATA, R.REC_VENCIMENTO, R.REC_JUROS, 
R.REC_DESCONTOS, R.REC_VALOR, R.REC_TIPO, R.REC_CON, R.REC_DATAR, R.REC_FPG, R.REC_DESCONTADO, R.REC_OBS, SUM(RP.RP_DINHEIRO + RP.RP_CHEQUE)
FROM FORNECEDORES FO, FATURAMENTOS F, RECEBIMENTOS R, REC_PGM RP
WHERE F.FAT_TIPO = 8 AND R.REC_CODIGO = RP.RP_REC AND F.FAT_CLI = FO.FOR_CODIGO AND F.FAT_CODIGO = R.REC_FAT AND (R.REC_SITUACAO >= 0 AND 
R.REC_SITUACAO < 3) AND R.REC_ESTADO < 3
GROUP BY F.FAT_CODIGO, FO.FOR_CODIGO, FO.FOR_NOME, FO.FOR_ENDERECO, R.REC_CODIGO, R.REC_DUPLICATA, R.REC_VENCIMENTO, R.REC_JUROS, 
R.REC_DESCONTOS, R.REC_VALOR,  R.REC_TIPO, R.REC_CON, R.REC_DATAR, R.REC_FPG, R.REC_DESCONTADO, R.REC_OBS
;



/* View: REL_CONTA_PAGA_CUSTO */
CREATE VIEW REL_CONTA_PAGA_CUSTO(
    PP_DATAPGM,
    SUC_NOME,
    PP_DINHEIRO,
    PP_CHEQUE,
    FAT2_CODIGO,
    CUST_HISTORICO,
    CUST_TIPO)
AS
SELECT PP.PP_DATAPGM, S.SUC_NOME, PP.PP_DINHEIRO, PP.PP_CHEQUE, F.FAT2_CODIGO, C.CUST_HISTORICO, C.CUST_TIPO
FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F, SUB_CUS S, CUSTOS C
WHERE C.CUST_FAT2 = F.FAT2_CODIGO AND S.SUC_CODIGO = F.FAT2_COD_FDTF AND P.PAG_CODIGO = PP.PP_PAG AND F.FAT2_CODIGO = P.PAG_FAT2
AND P.PAG_ESTADO = 3 AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3) AND PP.PP_DATAPGM IS NOT NULL
;



/* View: REL_CONTA_PAGA_CUSTO_A */
