    CUS1_CODIGO,
    CUS1_NOME,
    SUC_NOME,
    PP_DATAPGM,
    PP_DINHEIRO,
    PP_CHEQUE,
    SUC_VALORM)
AS
SELECT C1.CUS1_CODIGO, C1.CUS1_NOME, S.SUC_NOME, PP.PP_DATAPGM, PP.PP_DINHEIRO, PP.PP_CHEQUE, SUC_VALORM
FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F, SUB_CUS S, CUSTO_1 C1, CUSTOS C
WHERE C1.CUS1_CODIGO = S.SUC_DES AND S.SUC_CODIGO = C.CUST_SUD AND C.CUST_TIPO = 'C'
AND F.FAT2_CODIGO = C.CUST_FAT2 AND P.PAG_CODIGO = PP.PP_PAG AND F.FAT2_CODIGO = P.PAG_FAT2
AND P.PAG_ESTADO = 3 AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3) AND PP.PP_DATAPGM IS NOT NULL
;



