PP.PP_DINHEIRO, PP.PP_CHEQUE, S.SUC_NOME, S.SUC_CODIGO, F.FAT2_CODIGO, C.CUST_TIPO
FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F, CUSTOS C, SUB_CUS S
WHERE S.SUC_CODIGO = C.CUST_SUD AND P.PAG_CODIGO = PP.PP_PAG AND F.FAT2_CODIGO = P.PAG_FAT2
