PP.PP_DINHEIRO, PP.PP_CHEQUE, S.SUD_NOME, S.SUD_CODIGO, F.FAT2_CODIGO, C.CUST_TIPO
FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F, CUSTOS C, SUB_DES S
WHERE S.SUD_CODIGO = C.CUST_SUD AND P.PAG_CODIGO = PP.PP_PAG AND F.FAT2_CODIGO = P.PAG_FAT2
