FO.FOR_CODIGO, P.PAG_DUPLICATA
FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F, LANCAMENTO_REC_CUS L, FORNECEDORES FO
WHERE FO.FOR_CODIGO = L.LRC_CLI_FOR AND P.PAG_CODIGO = PP.PP_PAG AND F.FAT2_CODIGO = P.PAG_FAT2
