FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F, FINANCIAMENTOS FI
WHERE P.PAG_CODIGO = PP.PP_PAG AND F.FAT2_CODIGO = P.PAG_FAT2 AND F.FAT2_CODIGO = FI.FIN_FAT2 AND P.PAG_ESTADO = 3
