    SUD_VALORM)
AS
SELECT D.DES_CODIGO, D.DES_NOME, S.SUD_NOME, PP.PP_DATAPGM, PP.PP_DINHEIRO, PP.PP_CHEQUE, SUD_VALORM
FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F, SUB_DES S, DESPESAS D, CUSTOS C
WHERE D.DES_CODIGO = S.SUD_DES AND S.SUD_CODIGO = C.CUST_SUD AND C.CUST_TIPO = 'D'
AND F.FAT2_CODIGO = CUST_FAT2 AND P.PAG_CODIGO = PP.PP_PAG AND F.FAT2_CODIGO = P.PAG_FAT2
AND P.PAG_ESTADO = 3 AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3) AND PP.PP_DATAPGM IS NOT NULL
;



