WHERE T.TRA_CODIGO = FR.FRE_TRA AND FRE_FAT2 = FAT2_CODIGO AND P.PAG_CODIGO = PP.PP_PAG AND F.FAT2_CODIGO = P.PAG_FAT2
AND P.PAG_ESTADO = 3
