/* View: REL_CONTA_PAGAR_CUSTO */
CREATE VIEW REL_CONTA_PAGAR_CUSTO(
    VALORPG,
    PAG_CODIGO,
    PAG_VALOR,
    PAG_JUROS,
    PAG_DESCONTOS,
    PAG_VENCIMENTO,
    SUC_NOME,
    FAT2_CODIGO,
    CUST_COD_FUN,
    CUST_COD_FOR)
AS
SELECT SUM(PP.PP_DINHEIRO+PP.PP_CHEQUE), P.PAG_CODIGO, P.PAG_VALOR, P.PAG_JUROS, 
P.PAG_DESCONTOS, P.PAG_VENCIMENTO, SUC.SUC_NOME, 
F.FAT2_CODIGO, C.CUST_COD_FUN, C.CUST_COD_FOR
FROM SUB_CUS SUC, CUSTOS C, PAGAMENTOS P, FATURAMENTO2 F, PAG_PGM PP
WHERE C.CUST_TIPO = 'C' AND C.CUST_SUD = SUC.SUC_CODIGO AND C.CUST_FAT2 = F.FAT2_CODIGO AND F.FAT2_CODIGO = P.PAG_FAT2 AND
P.PAG_CODIGO = PP.PP_PAG AND P.PAG_ESTADO = 1 AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
GROUP BY P.PAG_CODIGO, P.PAG_VALOR, P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VENCIMENTO, 
SUC.SUC_NOME, F.FAT2_CODIGO, C.CUST_COD_FUN, C.CUST_COD_FOR
;



