F.FAT2_CODIGO, C.CUST_COD_FUN, C.CUST_COD_FOR
FROM SUB_DES SUD, CUSTOS C, PAGAMENTOS P, FATURAMENTO2 F, PAG_PGM PP
WHERE C.CUST_TIPO = 'D' AND C.CUST_SUD = SUD.SUD_CODIGO AND C.CUST_FAT2 = F.FAT2_CODIGO AND F.FAT2_CODIGO = P.PAG_FAT2
AND P.PAG_CODIGO = PP.PP_PAG AND P.PAG_ESTADO = 1 AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
