FROM IMPOSTOS I, PAGAMENTOS P, FATURAMENTO2 F, PAG_PGM PP, TRIBUTACOES
WHERE TRI_IMP = I.IMP_CODIGO AND TRI_FAT2 = F.FAT2_CODIGO AND F.FAT2_CODIGO = P.PAG_FAT2 AND P.PAG_CODIGO = PP.PP_PAG
AND P.PAG_ESTADO = 1 AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
GROUP BY P.PAG_CODIGO, P.PAG_VALOR, P.PAG_JUROS, P.PAG_DESCONTOS, P.PAG_VENCIMENTO, I.IMP_NOME, F.FAT2_CODIGO
