FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F, IMPOSTOS I, TRIBUTACOES
WHERE TRI_IMP = I.IMP_CODIGO AND TRI_FAT2 = F.FAT2_CODIGO AND P.PAG_CODIGO = PP.PP_PAG
AND F.FAT2_CODIGO = P.PAG_FAT2 AND P.PAG_ESTADO = 3
