/* View: REL_CONTA_RECEBER */
CREATE VIEW REL_CONTA_RECEBER(
    VALORPG,
    REC_CODIGO,
    REC_VALOR,
    REC_JUROS,
    REC_DESCONTOS,
    REC_VENCIMENTO,
    CLI_NOME,
    CLI_FONE,
    CLI_CELULAR,
    CLI_LIMITE,
    CLI_PLANO,
    REC_DATAR)
AS
SELECT SUM(RP.RP_DINHEIRO+RP.RP_CHEQUE), R.REC_CODIGO, R.REC_VALOR, R.REC_JUROS, 
R.REC_DESCONTOS, R.REC_VENCIMENTO, C.CLI_NOME, C.CLI_FONE, C.CLI_CELULAR,
CLI_LIMITE, C.CLI_PLANO, R.REC_DATAR
FROM RECEBIMENTOS R, FATURAMENTOS F, CLIENTES C, REC_PGM RP
WHERE C.CLI_CODIGO = F.FAT_CLI AND F.FAT_CODIGO = R.REC_FAT AND R.REC_CODIGO = RP.RP_REC 
AND R.REC_ESTADO = 1 AND (R.REC_SITUACAO >= 0 AND 
R.REC_SITUACAO < 2)
GROUP BY R.REC_CODIGO, R.REC_VALOR, R.REC_JUROS, R.REC_DESCONTOS, R.REC_VENCIMENTO, 
C.CLI_NOME, C.CLI_FONE, CLI_CELULAR, CLI_LIMITE, CLI_PLANO, R.REC_DATAR, CLI_CELULAR
;



/* View: REL_CONTA_RECEBER2 */
CREATE VIEW REL_CONTA_RECEBER2(
    VALORPG,
    REC_CODIGO,
    REC_VALOR,
    REC_JUROS,
    REC_DESCONTOS,
    REC_VENCIMENTO,
    CLI_NOME,
    CLI_FONE,
    CLI_LIMITE,
    REC_TIPO,
    REC_DESCONTADO)
AS
SELECT SUM(RP.RP_DINHEIRO+RP.RP_CHEQUE), R.REC_CODIGO, R.REC_VALOR, R.REC_JUROS, R.REC_DESCONTOS, R.REC_VENCIMENTO, C.CLI_NOME, C.CLI_FONE, 
CLI_LIMITE, R.REC_TIPO, R.REC_DESCONTADO
FROM RECEBIMENTOS R, FATURAMENTOS F, CLIENTES C, REC_PGM RP
WHERE C.CLI_CODIGO = F.FAT_CLI AND F.FAT_CODIGO = R.REC_FAT AND R.REC_CODIGO = RP.RP_REC AND R.REC_ESTADO = 1 AND (R.REC_SITUACAO = 2)
GROUP BY R.REC_CODIGO, R.REC_VALOR, R.REC_JUROS, R.REC_DESCONTOS, R.REC_VENCIMENTO, C.CLI_NOME, C.CLI_FONE, CLI_LIMITE, R.REC_TIPO, 
R.REC_DESCONTADO
;



/* View: REL_CONTA_RECEBIDA */
CREATE VIEW REL_CONTA_RECEBIDA(
    RP_DATAPGM,
    CLI_NOME,
    RP_DINHEIRO,
    RP_CHEQUE,
    RP_JUROS,
    RP_DESCONTOS,
    REC_TIPO)
AS
SELECT RP.RP_DATAPGM, C.CLI_NOME, RP.RP_DINHEIRO, RP.RP_CHEQUE, RP.RP_JUROS, RP.RP_DESCONTOS, REC_TIPO
FROM RECEBIMENTOS R, REC_PGM RP, FATURAMENTOS F, CLIENTES C
WHERE R.REC_CODIGO = RP.RP_REC AND F.FAT_CODIGO = R.REC_FAT AND F.FAT_CLI = C.CLI_CODIGO AND R.REC_ESTADO = 3 AND (R.REC_SITUACAO >= 0 AND 
R.REC_SITUACAO < 3)
AND RP.RP_DATAPGM IS NOT NULL
;



/* View: REL_CONTA_RECEBIDAC */
CREATE VIEW REL_CONTA_RECEBIDAC(
    DINHEIRO,
    CHEQUE,
    FAT_CODIGO,
    FAT_DATA,
    REC_JUROS,
    REC_DESCONTOS,
    REC_VALOR,
    RP_DATAPGM,
    CLI_CODIGO,
    CLI_NOME,
    REC_TIPO)
AS
SELECT SUM(RP.RP_DINHEIRO), SUM(RP.RP_CHEQUE), F.FAT_CODIGO, F.FAT_DATA, R.REC_JUROS, R.REC_DESCONTOS, R.REC_VALOR, RP.RP_DATAPGM, 
C.CLI_CODIGO, C.CLI_NOME, R.REC_TIPO
FROM RECEBIMENTOS R, REC_PGM RP, FATURAMENTOS F, CLIENTES C
WHERE R.REC_CODIGO = RP.RP_REC AND F.FAT_CODIGO = R.REC_FAT AND F.FAT_CLI = C.CLI_CODIGO AND R.REC_ESTADO = 3 AND (R.REC_SITUACAO >= 0 AND 
R.REC_SITUACAO < 3)
AND RP.RP_DATAPGM IS NOT NULL
GROUP BY F.FAT_CODIGO, F.FAT_DATA, R.REC_JUROS, R.REC_DESCONTOS, R.REC_VALOR, RP.RP_DATAPGM, C.CLI_CODIGO, C.CLI_NOME, R.REC_TIPO
;



/* View: REL_FOLHA_PAGA */
CREATE VIEW REL_FOLHA_PAGA(
    FOL_CODIGO,
    FUN_NOME,
    FOL_VALORSAL,
    FOL_VALORL,
    FOL_ESTADO,
    PP_DATAPGM,
    PP_DINHEIRO,
    PP_CHEQUE)
AS
SELECT FO.FOL_CODIGO, FU.FUN_NOME, FO.FOL_VALORSAL, FO.FOL_VALORL, FO.FOL_ESTADO, PP.PP_DATAPGM, PP.PP_DINHEIRO, PP.PP_CHEQUE
FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F, FOLHA_PAGAMENTOS FO, FUNCIONARIOS FU
WHERE FO.FOL_FUN = FU.FUN_CODIGO AND P.PAG_CODIGO = PP.PP_PAG AND F.FAT2_CODIGO = P.PAG_FAT2
AND F.FAT2_CODIGO = FO.FOL_FAT2 AND FO.FOL_DATAC = '01/01/1900' AND P.PAG_ESTADO = 3 AND PP.PP_DATAPGM IS NOT NULL
;



/* View: REL_FOLHA_PAGAR */
CREATE VIEW REL_FOLHA_PAGAR(
    FOL_CODIGO,
    FUN_NOME,
    FOL_VALORSAL,
    FOL_VALORL,
    FOL_DATA,
    PP_DATAPGM,
    PP_DINHEIRO,
    PP_CHEQUE)
AS
SELECT FO.FOL_CODIGO, FU.FUN_NOME, FO.FOL_VALORSAL, FO.FOL_VALORL, FO.FOL_DATA, PP.PP_DATAPGM, PP.PP_DINHEIRO, PP.PP_CHEQUE
FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F, FOLHA_PAGAMENTOS FO, FUNCIONARIOS FU
WHERE FO.FOL_FUN = FU.FUN_CODIGO AND P.PAG_CODIGO = PP.PP_PAG AND F.FAT2_CODIGO = P.PAG_FAT2
AND F.FAT2_CODIGO = FO.FOL_FAT2 AND FO.FOL_DATAC = '01/01/1900' AND FO.FOL_ESTADO = 'ATIVO' AND PP.PP_DATAPGM IS NOT NULL
;



/* View: SITUACAO_CLIENTE */
CREATE VIEW SITUACAO_CLIENTE(
    CLI_CODIGO,
    FAT_DATA,
    VALOR,
    VALORPG)
AS
SELECT C.CLI_CODIGO, FAT_DATA, SUM(DISTINCT(R.REC_VALOR+R.REC_JUROS-R.REC_DESCONTOS)), SUM(DISTINCT(RP.RP_DINHEIRO+RP.RP_CHEQUE))
FROM CLIENTES C, FATURAMENTOS F, RECEBIMENTOS R, REC_PGM RP
WHERE C.CLI_CODIGO = F.FAT_CLI AND F.FAT_CODIGO = R.REC_FAT AND R.REC_CODIGO = RP.RP_REC AND R.REC_ESTADO < 3
AND (R.REC_SITUACAO >= 0 AND R.REC_SITUACAO < 3)
GROUP BY C.CLI_CODIGO, FAT_DATA
;



/* View: VENDA_ANALITICO */
CREATE VIEW VENDA_ANALITICO(
    VEN_DATA,
    CLI_NOME,
    FAT_CODIGO,
    FUN_CODIGO,
    PRO_CODIGO,
    EST_NOME,
    VE_QUANTIDADE,
    VE_VALOR,
    VEN_VALOR,
    FAT_TIPOPGM,
    VE_CODIGO,
    VEN_CODIGO)
AS
SELECT V.VEN_DATA, C.CLI_NOME, F.FAT_CODIGO, FU.FUN_CODIGO, P.PRO_CODIGO, E.EST_NOME, VE.VE_QUANTIDADE, VE.VE_VALOR, V.VEN_VALOR, F.FAT_TIPOPGM, VE.VE_CODIGO, V.VEN_CODIGO
FROM VENDAS V, VEN_EST VE, CLIENTES C, FUNCIONARIOS FU, FATURAMENTOS F, PRODUTOS P, ESTOQUE E
WHERE V.VEN_CODIGO = VE.VE_VEN AND F.FAT_CODIGO = V.VEN_FAT AND F.FAT_CLI = C.CLI_CODIGO AND V.VEN_FUN = FU.FUN_CODIGO AND E.EST_CODIGO = P.PRO_EST AND VE.VE_PRO = P.PRO_CODIGO
;



/* View: VENDA_CLIENTE_E */
CREATE VIEW VENDA_CLIENTE_E(
    CLI_NOME,
    CLI_CODIGO,
    EST_NOME,
    VE_QUANTIDADE,
    VE_VALOR,
    VEN_DATA)
AS
SELECT C.CLI_NOME, C.CLI_CODIGO, E.EST_NOME, VE.VE_QUANTIDADE, VE.VE_VALOR, V.VEN_DATA
FROM VENDAS V, VEN_EST VE, FATURAMENTOS F, CLIENTES C, PRODUTOS P, ESTOQUE E
WHERE V.VEN_CODIGO = VE.VE_VEN AND F.FAT_CODIGO = V.VEN_FAT AND F.FAT_CLI = C.CLI_CODIGO AND VE.VE_PRO = P.PRO_CODIGO AND P.PRO_EST = E.EST_CODIGO
;



/* View: VENDA_CLIENTE_G */
CREATE VIEW VENDA_CLIENTE_G(
    CLI_NOME,
    VE_CODIGO,
    VE_VALOR,
    VEN_DATA)
AS
SELECT C.CLI_NOME, VE.VE_CODIGO, VE.VE_VALOR, V.VEN_DATA
FROM VENDAS V, VEN_EST VE, CLIENTES C, FATURAMENTOS F
WHERE V.VEN_CODIGO = VE.VE_VEN AND F.FAT_CODIGO = V.VEN_FAT AND F.FAT_CLI = C.CLI_CODIGO
;



/* View: VENDA_PRODUTO_E */
CREATE VIEW VENDA_PRODUTO_E(
    PRO_CODIGO,
    EST_NOME,
    CLI_NOME,
    VE_QUANTIDADE,
    VE_VALOR,
    VEN_DATA)
AS
SELECT P.PRO_CODIGO, E.EST_NOME, C.CLI_NOME, VE.VE_QUANTIDADE, VE.VE_VALOR, V.VEN_DATA
FROM VENDAS V, VEN_EST VE, FATURAMENTOS F, CLIENTES C, PRODUTOS P, ESTOQUE E
WHERE V.VEN_CODIGO = VE.VE_VEN AND F.FAT_CODIGO = V.VEN_FAT AND F.FAT_CLI = C.CLI_CODIGO AND E.EST_CODIGO = P.PRO_EST AND VE.VE_PRO = P.PRO_CODIGO
;



/* View: VENDA_PRODUTO_G */
CREATE VIEW VENDA_PRODUTO_G(
    PRO_CODIGO,
    EST_NOME,
    VE_QUANTIDADE,
    VE_VALOR,
    VEN_DATA)
AS
SELECT P.PRO_CODIGO, E.EST_NOME, VE.VE_QUANTIDADE, VE.VE_VALOR, V.VEN_DATA
FROM VENDAS V, VEN_EST VE, PRODUTOS P, ESTOQUE E
WHERE V.VEN_CODIGO = VE.VE_VEN AND VE.VE_PRO = P.PRO_CODIGO AND E.EST_CODIGO = P.PRO_EST
;



/* View: VENDA_SINTETICO */
CREATE VIEW VENDA_SINTETICO(
    VEN_DATA,
    VE_VALOR,
    VEN_VALOR,
    VEN_CODIGO)
AS
SELECT V.VEN_DATA, VE.VE_VALOR, V.VEN_VALOR, V.VEN_CODIGO
FROM VENDAS V, VEN_EST VE
WHERE V.VEN_CODIGO = VE.VE_VEN
;




