/* Trigger: MOVIMENTACOES_AI0 */
CREATE TRIGGER MOVIMENTACOES_AI0 FOR MOVIMENTACOES
ACTIVE AFTER INSERT POSITION 0
AS
BEGIN
  EXECUTE PROCEDURE AJUSTA_SALDO_ANT(NEW.MOV_CODIGO);
END
^

/* Trigger: PF_PARCELA_AI0 */
CREATE TRIGGER PF_PARCELA_AI0 FOR PF_PARCELA
ACTIVE AFTER INSERT OR UPDATE POSITION 0
AS
BEGIN
  /* TRIGGER TEXT */
  IF ((NEW.PP_VALORPG > 0) AND (NEW.PP_ESTADO = 1)) THEN
    POST_EVENT 'FATURA VISTA';
  IF (NEW.PP_ESTADO = 2) THEN
    POST_EVENT 'FATURA FINALIZADA';
END
^

SET TERM ; ^



