ALTER PROCEDURE ABAIXA_ESTOQUE (
    COD_VENDA INTEGER)
AS
DECLARE VARIABLE Quantidade FLOAT;
DECLARE VARIABLE Produto INTEGER;
BEGIN
    FOR SELECT VE_QUANTIDADE, VE_PRO FROM VEN_EST WHERE VE_VEN = :COD_VENDA
    INTO :Quantidade, :Produto DO
    BEGIN
     UPDATE PRODUTOS SET PRO_QUANTIDADE = PRO_QUANTIDADE - :Quantidade
     WHERE PRO_CODIGO = :Produto;
    END
END^


ALTER PROCEDURE ABAIXA_ESTOQUE3 (
    COD_COMPRA INTEGER)
AS
DECLARE VARIABLE Quantidade FLOAT;
DECLARE VARIABLE Produto INTEGER;
BEGIN
    FOR SELECT CE_QUANTIDADE, CE_PRO FROM COM_EST WHERE CE_COM = :COD_COMPRA
    INTO :Quantidade, :Produto DO
    BEGIN
     UPDATE PRODUTOS SET PRO_QUANTIDADE = PRO_QUANTIDADE - :Quantidade
     WHERE PRO_CODIGO = :Produto;
    END
END^


ALTER PROCEDURE ABAIXA_GRADE (
    COD_VENDA INTEGER)
AS
DECLARE VARIABLE QUANTIDADE FLOAT;
DECLARE VARIABLE PRODUTO INTEGER;
DECLARE VARIABLE COD_GRADE INTEGER;
DECLARE VARIABLE COD_TAM INTEGER;
BEGIN
    FOR SELECT VE_QUANTIDADE, VE_PRO, VE_GRADE, TAM_CODIGO FROM VEN_EST, GRADES, TAMANHOS
    WHERE VE_VEN = :COD_VENDA AND VE_GRADE = GRA_CODIGO AND GRA_TAM = TAM_CODIGO
    INTO :QUANTIDADE, :PRODUTO, :COD_GRADE, :COD_TAM DO
    BEGIN
     UPDATE GRADES SET GRA_QUANTIDADE = GRA_QUANTIDADE - :QUANTIDADE
     WHERE GRA_CODIGO = :COD_GRADE AND GRA_TAM = :COD_TAM AND GRA_PRO = :PRODUTO;
    END
END^


ALTER PROCEDURE AJUSTA_SALDO_ANT (
    CODIGO INTEGER)
AS
DECLARE VARIABLE DATA_MOV TIMESTAMP;
DECLARE VARIABLE CONTA INTEGER;
DECLARE VARIABLE CREDITO FLOAT;
DECLARE VARIABLE DEBITO FLOAT;
DECLARE VARIABLE MOV_COD INTEGER;
DECLARE VARIABLE PDV INTEGER;
DECLARE VARIABLE SALDOANTERIOR FLOAT;
BEGIN
  --RECUPERO ALGUNS DADOS DA MOVIMENTACAO
  SELECT MOV_DATAHORA, MOV_CON, MOV_CREDITO, MOV_DEBITO FROM MOVIMENTACOES
  WHERE MOV_CODIGO = :CODIGO
  INTO :DATA_MOV, :CONTA, :CREDITO, :DEBITO;
  IF (CAST(:DATA_MOV AS DATE) = CURRENT_DATE) THEN
    EXIT;
  IF(:CONTA = 0) THEN
  BEGIN
    --TRATAMENTO PARA CAIXA
    /*BUSCO PDV QUE ESTA MOVIMENTANDO*/
    SELECT CAI_PDV FROM CAIXA JOIN MOVIMENTACOES ON CAI_CODIGO = MOV_CAI
    WHERE MOV_CODIGO = :CODIGO
    INTO :PDV;
    /*BUSCO O SALDO ANTERIOR AO QUAL O NOVO REGISTRO SERA INSERIDO*/
    SELECT MOV_SALDOANT FROM MOVIMENTACOES
    WHERE MOV_CODIGO = (SELECT FIRST 1 MOV_CODIGO
                        FROM MOVIMENTACOES JOIN CAIXA ON MOV_CAI = CAI_CODIGO
                        WHERE MOV_CON = 0 AND CAI_PDV = :PDV AND MOV_DATA > :DATA_MOV
                        ORDER BY MOV_DATAHORA, MOV_CODIGO)
    INTO :SALDOANTERIOR;
    IF(:SALDOANTERIOR IS NULL) THEN
    BEGIN
      SELECT MOV_SALDOANT FROM MOVIMENTACOES
      WHERE MOV_CODIGO = (SELECT FIRST 1 MOV_CODIGO
                          FROM MOVIMENTACOES JOIN CAIXA ON MOV_CAI = CAI_CODIGO
                          WHERE MOV_CON = 0 AND CAI_PDV = :PDV AND MOV_DATA < :DATA_MOV
                          ORDER BY MOV_DATAHORA DESC, MOV_CODIGO DESC)
      INTO :SALDOANTERIOR;
    END
    IF(:SALDOANTERIOR IS NULL) THEN
      SALDOANTERIOR = 0;
    /*ATUALIZO O SALDO ANTERIOR EM TODOS OS REGISTROS COM DATA MAIOR DO QUE O NOVO REGISTRO INSERIDO*/
    FOR SELECT MOV_CODIGO FROM MOVIMENTACOES JOIN CAIXA ON MOV_CAI = CAI_CODIGO
    WHERE MOV_CON = 0 AND CAI_PDV = :PDV AND MOV_DATAHORA > :DATA_MOV ORDER BY MOV_DATAHORA, MOV_CODIGO
    INTO :MOV_COD DO
    BEGIN
      UPDATE MOVIMENTACOES SET MOV_SALDOANT = MOV_SALDOANT + :CREDITO - :DEBITO
      WHERE MOV_CODIGO = :MOV_COD;
    END
  END ELSE
  BEGIN
    --TRATAMENTO PARA CONTA
    /*BUSCO O SALDO ANTERIOR AO QUAL O NOVO REGISTRO SERA INSERIDO*/
    SELECT MOV_SALDOANT FROM MOVIMENTACOES
    WHERE MOV_CODIGO = (SELECT FIRST 1 MOV_CODIGO FROM MOVIMENTACOES
                        WHERE MOV_CON = :CONTA AND MOV_DATA > :DATA_MOV
                        ORDER BY MOV_DATAHORA, MOV_CODIGO)
    INTO :SALDOANTERIOR;
    IF(:SALDOANTERIOR IS NULL) THEN
    BEGIN
      SELECT MOV_SALDOANT FROM MOVIMENTACOES
      WHERE MOV_CODIGO = (SELECT FIRST 1 MOV_CODIGO FROM MOVIMENTACOES
                          WHERE MOV_CON = :CONTA AND MOV_DATA < :DATA_MOV
                          ORDER BY MOV_DATAHORA DESC, MOV_CODIGO DESC)
      INTO :SALDOANTERIOR;
    END
    IF(:SALDOANTERIOR IS NULL) THEN
      SALDOANTERIOR = 0;
    /*ATUALIZO O SALDO ANTERIOR EM TODOS OS REGISTROS COM DATA MAIOR DO QUE O NOVO REGISTRO INSERIDO*/
    FOR SELECT MOV_CODIGO FROM MOVIMENTACOES
    WHERE MOV_CON = :CONTA AND MOV_DATAHORA > :DATA_MOV
    ORDER BY MOV_DATAHORA, MOV_CODIGO
    INTO :MOV_COD DO
    BEGIN
      UPDATE MOVIMENTACOES SET MOV_SALDOANT = MOV_SALDOANT + :CREDITO - :DEBITO
      WHERE MOV_CODIGO = :MOV_COD;
    END
  END
  /*ATUALIZO O SALDO ANTERIOR PARA O MOVIMENTO INSERIDO*/
  UPDATE MOVIMENTACOES SET MOV_SALDOANT = :SALDOANTERIOR WHERE MOV_CODIGO = :CODIGO;
END^


ALTER PROCEDURE ALTERA_ESTOQUE_NF (
    CODIGO INTEGER)
AS
DECLARE VARIABLE PRODUTO INTEGER;
DECLARE VARIABLE QUANTIDADE FLOAT;
DECLARE VARIABLE QUANTIDADEA FLOAT;
DECLARE VARIABLE VALORC FLOAT;
DECLARE VARIABLE VALORCM FLOAT;
DECLARE VARIABLE VALORV FLOAT;
DECLARE VARIABLE OPERACAO CHAR(1);
DECLARE VARIABLE AJ_ESTOQUE CHAR(1);
DECLARE VARIABLE CLI_FOR VARCHAR(50);
DECLARE VARIABLE COD_NF INTEGER;
DECLARE VARIABLE CFOP VARCHAR(6);
DECLARE VARIABLE AJUSTOU_ESTOQUE CHAR(1);
DECLARE VARIABLE COD_NOT_ITENS INTEGER;
BEGIN
    SELECT CFO_AJUSTAR_ESTOQUE, CFO_OPERACAO FROM CFOP, NOTAS_FISCAIS
    WHERE NOT_CFOP = CFO_CFOP AND NOT_CODIGO = :CODIGO
    INTO :AJ_ESTOQUE, :OPERACAO;
    /*VERIFICA SE O CFOP DEVE AJUSTAR O ESTOQUE*/
    IF(:AJ_ESTOQUE = 'S') THEN
    BEGIN
      /*BUSCO CLIENTE/FORNECEDOR*/
      SELECT CF_NOME, NOT_NF, NOT_CFOP FROM NOTAS_FISCAIS INNER JOIN CLIENTES_FORNECEDORES ON NOT_CF = 
CF_CODIGO AND NOT_CODIGO = :CODIGO
      INTO :CLI_FOR, :COD_NF, :CFOP;
      IF(:OPERACAO = 'E') THEN
      BEGIN
        FOR SELECT NI_CODIGO, NI_PRO, NI_QUANTIDADE*COALESCE(NI_MULTIPLICADOR, 1), NI_AJ_ESTOQUE
        FROM NOT_ITENS WHERE NI_NOT = :CODIGO
        INTO :COD_NOT_ITENS, :PRODUTO, :QUANTIDADE, :AJUSTOU_ESTOQUE DO
        BEGIN
          IF (:AJUSTOU_ESTOQUE IS NULL) THEN
          BEGIN
            /*BUSCO A QUANTIDADE ANTERIOR*/
            SELECT PRO_QUANTIDADE, PRO_VALORC, PRO_VALORCM, PRO_VALORV FROM PRODUTOS WHERE PRO_CODIGO 
= :PRODUTO
            INTO :QUANTIDADEA, :VALORC, :VALORCM, :VALORV;
            /*INSERE HISTORICO*/
            INSERT INTO HIS_PRO (HP_CODIGO, HP_DATA, HP_PRO, HP_ORIGEM, HP_DOC, HP_QUANTIDADE, 
HP_VALORC, HP_VALORV,
            HP_VALORCM, HP_VALOROP, HP_VALORM, HP_TIPO, HP_TIPO2, HP_QUANTIDADEA)
            VALUES(GEN_ID(GEN_HP, 1), CURRENT_DATE, :PRODUTO, LEFT('NF - '||:COD_NF||' ['||:CFOP||'] 
'||:CLI_FOR, 30), :CODIGO, :QUANTIDADE, :VALORC*:QUANTIDADE,
            :VALORV*:QUANTIDADE, :VALORCM*:QUANTIDADE, 0, 0, :OPERACAO, 7, :QUANTIDADEA);
            /*ATUALIZA O ESTOQUE*/
            UPDATE PRODUTOS SET PRO_QUANTIDADE = PRO_QUANTIDADE + :QUANTIDADE
            WHERE PRO_CODIGO = :PRODUTO;
            /*ATUALIZA A FLAG NI_AJ_ESTOQUE PARA NAO ATUALIZAR O ESTOQUE DO PRODUTO MAIS DE UMA VEZ*/
            UPDATE NOT_ITENS SET NI_AJ_ESTOQUE = 'S' WHERE NI_CODIGO = :COD_NOT_ITENS;
          END
        END
      END ELSE
      BEGIN
        FOR SELECT NI_CODIGO, NI_PRO, NI_QUANTIDADE*COALESCE(NI_MULTIPLICADOR, 1), NI_AJ_ESTOQUE
        FROM NOT_ITENS WHERE NI_NOT = :CODIGO
        INTO :COD_NOT_ITENS, :PRODUTO, :QUANTIDADE, :AJUSTOU_ESTOQUE DO
        BEGIN
          IF (:AJUSTOU_ESTOQUE IS NULL) THEN
          BEGIN  
            /*BUSCO A QUANTIDADE ANTERIOR*/
            SELECT PRO_QUANTIDADE, PRO_VALORC, PRO_VALORCM, PRO_VALORV FROM PRODUTOS WHERE PRO_CODIGO 
= :PRODUTO
            INTO :QUANTIDADEA, :VALORC, :VALORCM, :VALORV;
            /*INSERE HISTORICO*/
            INSERT INTO HIS_PRO (HP_CODIGO, HP_DATA, HP_PRO, HP_ORIGEM, HP_DOC, HP_QUANTIDADE, 
HP_VALORC, HP_VALORV,
            HP_VALORCM, HP_VALOROP, HP_VALORM, HP_TIPO, HP_TIPO2, HP_QUANTIDADEA)
            VALUES(GEN_ID(GEN_HP, 1), CURRENT_DATE, :PRODUTO, LEFT('NF - '||:COD_NF||' ['||:CFOP||'] 
'||:CLI_FOR, 30), :CODIGO, :QUANTIDADE, :VALORC*:QUANTIDADE,
            :VALORV*:QUANTIDADE, :VALORCM*:QUANTIDADE, 0, 0, :OPERACAO, 7, :QUANTIDADEA);
            /*ATUALIZA O ESTOQUE*/
            UPDATE PRODUTOS SET PRO_QUANTIDADE = PRO_QUANTIDADE - :QUANTIDADE
            WHERE PRO_CODIGO = :PRODUTO;
            /*ATUALIZA A FLAG NI_AJ_ESTOQUE PARA NAO ATUALIZAR O ESTOQUE DO PRODUTO MAIS DE UMA VEZ*/
            UPDATE NOT_ITENS SET NI_AJ_ESTOQUE = 'S' WHERE NI_CODIGO = :COD_NOT_ITENS;
          END
        END
      END
    END
END^


ALTER PROCEDURE ANALISE_PLANEJ_COMPRA (
    DATA1 DATE,
    DATA2 DATE)
RETURNS (
    VENDA FLOAT,
    COMPRA FLOAT,
    DESPESA FLOAT,
    CONTA_RECEBER FLOAT,
    ESTOQUEF FLOAT)
AS
DECLARE VARIABLE VALOR1 FLOAT;
DECLARE VARIABLE VALOR FLOAT;
DECLARE VARIABLE VALOR_PG FLOAT;
BEGIN
     SELECT SUM(VE.VE_VALOR)
     FROM VENDAS V, VEN_EST VE
     WHERE V.VEN_CODIGO = VE.VE_VEN AND V.VEN_DATAC = '01/01/1900' AND V.VEN_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VALOR1;
     IF (VALOR1 IS NULL) THEN
      VALOR1 = 0;
     VENDA = VALOR1;
     SELECT SUM(CE.CE_VALOR)
     FROM COMPRAS C, COM_EST CE
     WHERE C.COM_CODIGO = CE.CE_COM AND C.COM_DATAC = '01/01/1900' AND C.COM_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VALOR1;
     IF (VALOR1 IS NULL) THEN
      VALOR1 = 0;
     COMPRA = VALOR1;
     SELECT SUM(CUST_VALOR)
     FROM CUSTOS
     WHERE CUST_DATAC = '01/01/1900' AND CUST_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VALOR1;
     IF (VALOR1 IS NULL) THEN
      VALOR1 = 0;
     SELECT SUM(FOL_VALORSAL)
     FROM FOLHA_PAGAMENTOS
     WHERE FOL_DATAC = '01/01/1900' AND FOL_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VALOR;
     IF (VALOR IS NULL) THEN
      VALOR = 0;
     DESPESA = VALOR1+VALOR;
     SELECT SUM(R.REC_VALOR+R.REC_JUROS-R.REC_DESCONTOS) FROM RECEBIMENTOS R
     WHERE R.REC_ESTADO < 3 AND (R.REC_SITUACAO >= 0 AND R.REC_SITUACAO < 3)
     INTO :VALOR;
     IF (VALOR IS NULL) THEN
      VALOR = 0;
     SELECT SUM(RP.RP_DINHEIRO-RP.RP_JUROS+RP.RP_DESCONTOS) FROM RECEBIMENTOS R, REC_PGM RP
     WHERE R.REC_CODIGO = RP.RP_REC AND R.REC_ESTADO = 2 AND (R.REC_SITUACAO >= 0 AND R.REC_SITUACAO < 3)
     INTO :VALOR_PG;
     IF (VALOR_PG IS NULL) THEN
      VALOR_PG = 0;
     CONTA_RECEBER = :VALOR - VALOR_PG;
     SELECT SUM(PRO_VALORF*PRO_QUANTIDADE)
     FROM PRODUTOS
     INTO :ESTOQUEF;
  SUSPEND;
END^


ALTER PROCEDURE ATUALIZA_ACERTO (
    CODIGO INTEGER,
    TIPO VARCHAR(2),
    QUANTIDADE FLOAT)
RETURNS (
    QUANTIDADEA NUMERIC(9,2))
AS
BEGIN
     SELECT PRO_QUANTIDADE FROM PRODUTOS WHERE PRO_CODIGO = :CODIGO
     INTO :QUANTIDADEA;
     if (:QUANTIDADEA IS NULL) then
      QUANTIDADEA = 0;

     IF ((:Tipo = 'E') OR (:Tipo = 'G')) THEN
     BEGIN
      UPDATE PRODUTOS SET PRO_QUANTIDADE = PRO_QUANTIDADE + :Quantidade WHERE PRO_CODIGO = :Codigo;
     END
     ELSE IF ((:Tipo = 'S') OR (:Tipo = 'P')) THEN
     BEGIN
      UPDATE PRODUTOS SET PRO_QUANTIDADE = PRO_QUANTIDADE - :Quantidade WHERE PRO_CODIGO = :Codigo;
     END
END^


ALTER PROCEDURE ATUALIZA_CAI (
    COD_CAIXA INTEGER,
    DINHEIRO FLOAT,
    CHEQUE FLOAT)
AS
BEGIN
     UPDATE CAIXA SET CAI_VALORD = CAI_VALORD + :Dinheiro, CAI_VALORC = CAI_VALORC + :Cheque
     WHERE CAI_CODIGO = :Cod_Caixa;
END^


ALTER PROCEDURE ATUALIZA_CHEQUE_DEP (
    CODIGO INTEGER)
AS
BEGIN
     UPDATE CHEQUES SET CHE_ESTADO = 2 WHERE CHE_CODIGO = :CODIGO;
END^


ALTER PROCEDURE ATUALIZA_CON (
    CODIGO INTEGER,
    VALOR FLOAT)
AS
BEGIN
     UPDATE CONTAS SET CON_SALDO = CON_SALDO + :VALOR
     WHERE CON_CODIGO = :CODIGO;
END^


ALTER PROCEDURE ATUALIZA_DESC (
    DESCONTO FLOAT,
    CODIGO INTEGER,
    TIPO VARCHAR(15))
AS
BEGIN
     IF (Tipo = 'Recebimento') THEN
     BEGIN
      UPDATE RECEBIMENTOS SET REC_DESCONTOS = :desconto
      WHERE REC_CODIGO = :Codigo;
     END
     IF (Tipo = 'Pagamento') THEN
     BEGIN
      UPDATE PAGAMENTOS SET PAG_DESCONTOS = :desconto
      WHERE PAG_CODIGO = :Codigo;
     END
END^


ALTER PROCEDURE ATUALIZA_ENCARGO_HEXTRA (
    CODIGO INTEGER)
RETURNS (
    HORA_EXTRA FLOAT,
    ADIANTAMENTO FLOAT,
    INSS FLOAT,
    HORA_FALTA FLOAT,
    SAL_FAMILIA FLOAT)
AS
declare variable horas float;
declare variable valor_hora float;
BEGIN
     HORA_EXTRA = 0;
     HORA_FALTA = 0;
     FOR SELECT HEX_HORAS, HEX_VALOR FROM HEXTRA WHERE HEX_DATAC = '01/01/1900' AND HEX_FOL = :CODIGO
     INTO :HORAS, :VALOR_HORA DO
     BEGIN
          if (:VALOR_HORA >= 0) then
           HORA_EXTRA = HORA_EXTRA + :VALOR_HORA;
          if (:VALOR_HORA < 0) then
           HORA_FALTA = HORA_FALTA + :VALOR_HORA;
     END
     SELECT SUM(AF_VALOR) FROM ADIANTAMENTO_FOLHA WHERE AF_DATAC = '01/01/1900' AND AF_FOL = :CODIGO
     INTO :ADIANTAMENTO;
     SELECT SUM(F13_VALOR) FROM FERIAS_13 WHERE F13_DATAC = '01/01/1900' AND F13_TIPO = 3 AND F13_FOL = :CODIGO
     INTO :INSS;
     if (INSS IS NULL) then
      INSS = 0;
     SELECT SUM(F13_VALOR) FROM FERIAS_13 WHERE F13_DATAC = '01/01/1900' AND F13_TIPO = 2 AND F13_FOL = :CODIGO
     INTO :SAL_FAMILIA;
     if (SAL_FAMILIA IS NULL) then
      SAL_FAMILIA = 0;

END^


ALTER PROCEDURE ATUALIZA_FATURAMENTO (
    FATURA INTEGER,
    FATURA_NOVA INTEGER)
AS
DECLARE VARIABLE CODIGO INTEGER;
DECLARE VARIABLE ESTADO INTEGER;
DECLARE VARIABLE VALOR INTEGER;
BEGIN
     FOR SELECT SUM(RP_DINHEIRO+RP_CHEQUE), REC_CODIGO, REC_ESTADO FROM RECEBIMENTOS, REC_PGM
     WHERE RP_REC = REC_CODIGO AND REC_FAT = :FATURA GROUP BY REC_CODIGO, REC_ESTADO
     INTO :VALOR, :CODIGO, :ESTADO DO
     BEGIN
       IF (ESTADO = 2) THEN
       BEGIN
         UPDATE RECEBIMENTOS SET REC_ESTADO = 3, REC_VALOR = :VALOR, REC_SITUACAO = 2, REC_FAT = :FATURA_NOVA WHERE REC_CODIGO = :CODIGO;
         DELETE FROM REC_PGM WHERE RP_REC = :CODIGO AND RP_DATAPGM IS NULL;
         UPDATE REC_PGM SET RP_JUROS = 0, RP_DESCONTOS = 0 WHERE RP_REC = :CODIGO;
       END
       ELSE IF (ESTADO = 3) THEN
       BEGIN
         UPDATE RECEBIMENTOS SET REC_SITUACAO = 2, REC_FAT = :FATURA_NOVA WHERE REC_CODIGO = :CODIGO;
       END
       ELSE IF (ESTADO = 1) THEN
       BEGIN
         UPDATE RECEBIMENTOS SET REC_SITUACAO = -2, REC_FAT = :FATURA_NOVA WHERE REC_CODIGO = :CODIGO;
       END
     END
     DELETE FROM FATURAMENTOS WHERE FAT_CODIGO = :FATURA;
END^


ALTER PROCEDURE ATUALIZA_FATURAMENTO2 (
    FATURA INTEGER,
    FATURA_NOVA INTEGER)
AS
declare variable codigo integer;
declare variable estado integer;
declare variable valor integer;
BEGIN
     FOR SELECT COM_CODIGO FROM COMPRAS, FATURAMENTO2 WHERE COM_FAT2 = FAT2_CODIGO AND FAT2_CODIGO = :FATURA
     INTO :CODIGO DO
     BEGIN
       UPDATE COMPRAS SET COM_FAT2 = :FATURA_NOVA WHERE COM_CODIGO = :CODIGO;
     END
     FOR SELECT SUM(PP_DINHEIRO+PP_CHEQUE), PAG_CODIGO, PAG_ESTADO FROM PAGAMENTOS, PAG_PGM
     WHERE PP_PAG = PAG_CODIGO AND PAG_FAT2 = :FATURA GROUP BY PAG_CODIGO, PAG_ESTADO
     INTO :VALOR, :CODIGO, :ESTADO DO
     BEGIN
       if (ESTADO = 2) then
       begin
         UPDATE PAGAMENTOS SET PAG_ESTADO = 3, PAG_VALOR = :VALOR, PAG_SITUACAO = 2, PAG_FAT2 = :FATURA_NOVA WHERE PAG_CODIGO = :CODIGO;
         DELETE FROM PAG_PGM WHERE PP_PAG = :CODIGO AND PP_DATAPGM IS NULL;
         UPDATE PAG_PGM SET PP_JUROS = 0, PP_DESCONTOS = 0 WHERE PP_PAG = :CODIGO;
       end
       else if (ESTADO = 3) then
       begin
         UPDATE PAGAMENTOS SET PAG_SITUACAO = 2, PAG_FAT2 = :FATURA_NOVA WHERE PAG_CODIGO = :CODIGO;
       end
       else if (ESTADO = 1) then
       begin
         UPDATE PAGAMENTOS SET PAG_SITUACAO = -2, PAG_FAT2 = :FATURA_NOVA WHERE PAG_CODIGO = :CODIGO;
       end

     END
     DELETE FROM FATURAMENTO2 WHERE FAT2_CODIGO = :FATURA;
END^


ALTER PROCEDURE ATUALIZA_FATURAMENTO2_COD
AS
declare variable codigo integer;
declare variable fdtf integer;
BEGIN
    FOR SELECT FAT2_CODIGO, COM_FOR FROM FATURAMENTO2, COMPRAS where FAT2_TIPO = 1 AND FAT2_DESCRICAO = COM_CODIGO
    INTO :Codigo, :FDTF DO
    BEGIN
     UPDATE FATURAMENTO2 SET FAT2_COD_FDTF = :FDTF
     WHERE FAT2_CODIGO = :Codigo;
    END
    FOR SELECT FAT2_CODIGO, CUST_SUD FROM FATURAMENTO2, CUSTOS where FAT2_TIPO = 2 AND FAT2_DESCRICAO = CUST_CODIGO
    INTO :Codigo, :FDTF DO
    BEGIN
     UPDATE FATURAMENTO2 SET FAT2_COD_FDTF = :FDTF
     WHERE FAT2_CODIGO = :Codigo;
    END
    FOR SELECT FAT2_CODIGO, TRI_IMP FROM FATURAMENTO2, TRIBUTACOES where FAT2_TIPO = 3 AND FAT2_DESCRICAO = TRI_CODIGO
    INTO :Codigo, :FDTF DO
    BEGIN
     UPDATE FATURAMENTO2 SET FAT2_COD_FDTF = :FDTF
     WHERE FAT2_CODIGO = :Codigo;
    END
    FOR SELECT FAT2_CODIGO, FRE_TRA FROM FATURAMENTO2, FRETES where FAT2_TIPO = 4 AND FAT2_DESCRICAO = FRE_CODIGO
    INTO :Codigo, :FDTF DO
    BEGIN
     UPDATE FATURAMENTO2 SET FAT2_COD_FDTF = :FDTF
     WHERE FAT2_CODIGO = :Codigo;
    END
END^


ALTER PROCEDURE ATUALIZA_FINANCIAMENTO
AS
declare variable codigo integer;
declare variable descricao integer;
BEGIN

     FOR SELECT FAT2_CODIGO, FAT2_DESCRICAO FROM FATURAMENTO2 WHERE FAT2_TIPO = 6
     INTO :CODIGO, :DESCRICAO DO
     BEGIN
       UPDATE FINANCIAMENTOS SET FIN_FAT2 = :CODIGO WHERE FIN_CODIGO = :DESCRICAO;
     END
END^


ALTER PROCEDURE ATUALIZA_FOLHA (
    DATA VARCHAR(10),
    DIA VARCHAR(2))
AS
DECLARE VARIABLE CODIGO INTEGER;
DECLARE VARIABLE SALARIO FLOAT;
DECLARE VARIABLE DATAPGM VARCHAR(3);
DECLARE VARIABLE FOLHA INTEGER;
BEGIN
     FOR SELECT FUN_CODIGO, FUN_SALARIO, FUN_DATAPGM FROM FUNCIONARIOS WHERE FUN_DATAPGM = :DIA AND FUN_ESTADO = 'ATIVO'
     INTO :CODIGO, :SALARIO, :DATAPGM DO
     BEGIN
          FOLHA = 0;
          SELECT FOL_CODIGO FROM FOLHA_PAGAMENTOS WHERE FOL_MES = :DATA AND FOL_FUN = :CODIGO
          INTO :FOLHA;
          IF (:FOLHA = 0) THEN
          BEGIN
               FOLHA = GEN_ID(GEN_FOL, 1);
               INSERT INTO FOLHA_PAGAMENTOS(FOL_CODIGO, FOL_FUN, FOL_MES, FOL_VALORSAL, FOL_ESTADO)
               VALUES(:FOLHA, :CODIGO, :DATA, :SALARIO, 'ATIVO');
          END
     END
END^


ALTER PROCEDURE ATUALIZA_GRADE (
    CODIGO INTEGER,
    TIPO VARCHAR(2),
    QUANTIDADE FLOAT,
    COD_GRADE INTEGER)
RETURNS (
    QUANT_GRADE NUMERIC(9,2))
AS
BEGIN
     SELECT GRA_QUANTIDADE FROM GRADES WHERE GRA_CODIGO = :COD_GRADE AND GRA_PRO = :CODIGO
     INTO :QUANT_GRADE;
     IF (:QUANT_GRADE IS NULL) THEN
      QUANT_GRADE = 0;
     IF ((:TIPO = 'E') OR (:TIPO = 'G')) THEN
     BEGIN
      UPDATE GRADES SET GRA_QUANTIDADE = GRA_QUANTIDADE + :QUANTIDADE WHERE GRA_CODIGO = :COD_GRADE AND GRA_PRO = :CODIGO;
     END
     ELSE IF ((:TIPO = 'S') OR (:TIPO = 'P')) THEN
     BEGIN
      UPDATE GRADES SET GRA_QUANTIDADE = GRA_QUANTIDADE - :QUANTIDADE WHERE GRA_CODIGO = :COD_GRADE AND GRA_PRO = :CODIGO;
     END
END^


ALTER PROCEDURE ATUALIZA_GRADE_COMPRA (
    CODIGO INTEGER,
    QUANTIDADE FLOAT,
    COD_GRADE INTEGER,
    VALOR NUMERIC(9,2))
RETURNS (
    QUANT_GRADE NUMERIC(9,2))
AS
BEGIN
     SELECT GRA_QUANTIDADE FROM GRADES WHERE GRA_CODIGO = :COD_GRADE
     INTO :QUANT_GRADE;
     IF (:QUANT_GRADE IS NULL) THEN
      QUANT_GRADE = 0;
     UPDATE GRADES SET GRA_QUANTIDADE = GRA_QUANTIDADE + :QUANTIDADE WHERE GRA_CODIGO = :COD_GRADE;
     UPDATE GRADES SET GRA_VALOR = :VALOR WHERE GRA_CODIGO = :COD_GRADE;
END^


ALTER PROCEDURE ATUALIZA_IMOBILIZADO (
    DATA1 DATE,
    DATA2 DATE)
AS
declare variable VALOR_NOVO FLOAT;
declare variable DATAC DATE;
declare variable VALORC FLOAT;
declare variable VALORD FLOAT;
declare variable CODIGO FLOAT;
declare variable PERCENTUALD NUMERIC(3,2);
begin

     FOR SELECT IMO_CODIGO, IMO_DATAC, IMO_VALORC, IMO_VALORD, IMO_PERCENTUALD FROM IMOBILIZADOS
     INTO :CODIGO, :DATAC, :VALORC, :VALORD, :PERCENTUALD DO
     BEGIN
          if ((DATAC + 30) <= DATA1) then
          begin
            VALOR_NOVO = VALORD +(((VALORC-VALORD)*(PERCENTUALD/100))/365)*30;
            UPDATE IMOBILIZADOS SET IMO_VALORD = :VALOR_NOVO WHERE IMO_CODIGO = :CODIGO;
          end
          else
          begin
            if ((DATAC+30) <= DATA2) then
            begin
              VALOR_NOVO = VALORD +(((VALORC-VALORD)*(PERCENTUALD/100))/365)*(DATA2-(DATAC+30));
              UPDATE IMOBILIZADOS SET IMO_VALORD = :VALOR_NOVO WHERE IMO_CODIGO = :CODIGO;
              /*VALORD_NOVO = VALORD_NOVO + (((VALORC-VALORD)*(PERCENTUALD/100))/365)*(DATA2-(DATAC+30));*/
            end
          end
     END
  suspend;
end^


ALTER PROCEDURE ATUALIZA_JUROS (
    JUROS FLOAT,
    CODIGO INTEGER,
    TIPO VARCHAR(15))
AS
BEGIN
     IF (Tipo = 'Recebimento') THEN
     BEGIN
      UPDATE RECEBIMENTOS SET REC_JUROS = :Juros
      WHERE REC_CODIGO = :Codigo;
     END
     IF (Tipo = 'Pagamento') THEN
     BEGIN
      UPDATE PAGAMENTOS SET PAG_JUROS = :Juros
      WHERE PAG_CODIGO = :Codigo;
     END
END^


