END^


ALTER PROCEDURE ATUALIZA_PAG_PGM (
    CODIGO INTEGER,
    DATAPGM DATE,
    DINHEIRO FLOAT,
    CHEQUE FLOAT,
    FUN INTEGER,
    MOV INTEGER,
    HORA TIME,
    CAI INTEGER,
    JUROS FLOAT,
    DESCONTOS FLOAT)
AS
declare variable cod_pp integer;
BEGIN
     SELECT PP_CODIGO FROM PAG_PGM WHERE PP_DATAPGM IS NULL AND PP_PAG = :CODIGO
     INTO :COD_PP;
     UPDATE PAG_PGM SET PP_DATAPGM = :DATAPGM, PP_DINHEIRO = :DINHEIRO, PP_CHEQUE = :CHEQUE, PP_FUN = :FUN, PP_MOV = :MOV, PP_HORA = :HORA, PP_CAI = :CAI, PP_JUROS = :JUROS, PP_DESCONTOS = :DESCONTOS
     WHERE PP_CODIGO = :COD_PP;
END^


ALTER PROCEDURE ATUALIZA_PAGAMENTO (
    COD_PAG INTEGER)
AS
DECLARE VARIABLE CODIGO INTEGER;
DECLARE VARIABLE ESTADO INTEGER;
DECLARE VARIABLE VALOR FLOAT;
BEGIN
     SELECT SUM(PP_DINHEIRO+PP_CHEQUE), PAG_CODIGO, PAG_ESTADO FROM PAGAMENTOS, PAG_PGM
     WHERE PAG_CODIGO = PP_PAG AND PAG_CODIGO = :COD_PAG GROUP BY PAG_CODIGO, PAG_ESTADO
     INTO :VALOR, :CODIGO, :ESTADO;
     BEGIN
       if (ESTADO = 2) then
       begin
         UPDATE PAGAMENTOS SET PAG_ESTADO = 3, PAG_VALOR = :VALOR, PAG_SITUACAO = 1, PAG_JUROS = 0, PAG_DESCONTOS = 0 WHERE PAG_CODIGO = :CODIGO;
         DELETE FROM PAG_PGM WHERE PP_PAG = :CODIGO AND PP_DATAPGM IS NULL;
         UPDATE PAG_PGM SET PP_JUROS = 0, PP_DESCONTOS = 0 WHERE PP_PAG = :CODIGO;
       end
       else if (ESTADO = 3) then
       begin
         UPDATE PAGAMENTOS SET PAG_SITUACAO = 1 WHERE PAG_CODIGO = :CODIGO;
       end
       else if (ESTADO = 1) then
       begin
         UPDATE PAGAMENTOS SET PAG_SITUACAO = -1 WHERE PAG_CODIGO = :CODIGO;
       end
     END
END^


ALTER PROCEDURE ATUALIZA_PP_ESTADO
AS
declare variable fat integer;
declare variable cod_fat integer;
declare variable cod_pp integer;
declare variable datac date;
BEGIN
    FOR SELECT PF_FAT FROM PED_FAT WHERE PF_TABELA = 'VENDAS'
    INTO :FAT DO
    BEGIN
         SELECT FAT_CODIGO FROM FATURAMENTOS WHERE FAT_CODIGO = :FAT
         INTO :COD_FAT;
         if (:COD_FAT = :FAT) then
         BEGIN
             FOR SELECT DISTINCT(PP_CODIGO) FROM PF_PARCELA, PED_FAT WHERE PP_PF = PF_CODIGO AND PF_FAT = :FAT
             INTO :COD_PP DO
             BEGIN
                  UPDATE PF_PARCELA SET PP_ESTADO = 2 WHERE PP_CODIGO = :COD_PP;
             END
         END
         ELSE
         BEGIN
             FOR SELECT DISTINCT(PP_CODIGO), PF_DATAC FROM PF_PARCELA, PED_FAT WHERE PP_PF = PF_CODIGO AND PF_FAT = :FAT
             INTO :COD_PP, :DATAC DO
             BEGIN
                  if (DATAC = '01/01/1900') then
                  BEGIN
                       UPDATE PF_PARCELA SET PP_ESTADO = 1 WHERE PP_CODIGO = :COD_PP;
                  END
                  ELSE
                  BEGIN
                       UPDATE PF_PARCELA SET PP_ESTADO = 2 WHERE PP_CODIGO = :COD_PP;
                  END
             END
         END
    END
END^


