END^


ALTER PROCEDURE ATUALIZA_VENCIMENTO2 (
    DATA DATE,
    CODIGO INTEGER,
    TIPO VARCHAR(20))
AS
DECLARE VARIABLE VENCIMENTO DATE;
DECLARE VARIABLE PAGAMENTO INTEGER;
BEGIN
     IF (:TIPO = 'Fornecedor') THEN
     BEGIN
      FOR SELECT P.PAG_VENCIMENTO, P.PAG_CODIGO FROM PAGAMENTOS P, FATURAMENTO2 F, FORNECEDORES FO, COMPRAS C
      WHERE FO.FOR_CODIGO = C.COM_FOR AND F.FAT2_TIPO = 1 AND F.FAT2_DESCRICAO = C.COM_CODIGO  AND P.PAG_FAT2 = F.FAT2_CODIGO AND P.PAG_ESTADO <> 1 AND FO.FOR_CODIGO = :CODIGO
      INTO :VENCIMENTO, :PAGAMENTO DO
      BEGIN
           IF (:VENCIMENTO < :DATA) THEN
           BEGIN
                UPDATE PAGAMENTOS SET PAG_VENCIMENTO = :DATA WHERE PAG_CODIGO = :PAGAMENTO;
           END
      END
     END
     ELSE IF (:TIPO = 'Despesa') THEN
     BEGIN
      FOR SELECT P.PAG_VENCIMENTO, P.PAG_CODIGO FROM PAGAMENTOS P, FATURAMENTO2 F, CUSTOS C, SUB_DES SD, DESPESAS D
      WHERE SD.SUD_DES = D.DES_CODIGO AND C.CUST_SUD = SD.SUD_CODIGO AND F.FAT2_TIPO = 2 AND F.FAT2_DESCRICAO = C.CUST_CODIGO  AND P.PAG_FAT2 = F.FAT2_CODIGO AND P.PAG_ESTADO <> 1 AND SD.SUD_CODIGO = :CODIGO
      INTO :VENCIMENTO, :PAGAMENTO DO
      BEGIN
           IF (:VENCIMENTO < :DATA) THEN
           BEGIN
                UPDATE PAGAMENTOS SET PAG_VENCIMENTO = :DATA WHERE PAG_CODIGO = :PAGAMENTO;
           END
      END
     END
     ELSE IF (:TIPO = 'Imposto') THEN
     BEGIN
      FOR SELECT P.PAG_VENCIMENTO, P.PAG_CODIGO FROM PAGAMENTOS P, FATURAMENTO2 F, TRIBUTACOES T, IMPOSTOS I
      WHERE I.IMP_CODIGO = T.TRI_IMP AND F.FAT2_TIPO = 3 AND F.FAT2_DESCRICAO = T.TRI_CODIGO  AND P.PAG_FAT2 = F.FAT2_CODIGO AND P.PAG_ESTADO <> 1 AND I.IMP_CODIGO = :CODIGO
      INTO :VENCIMENTO, :PAGAMENTO DO
      BEGIN
           IF (:VENCIMENTO < :DATA) THEN
           BEGIN
                UPDATE PAGAMENTOS SET PAG_VENCIMENTO = :DATA WHERE PAG_CODIGO = :PAGAMENTO;
           END
      END
     END
     ELSE IF (:TIPO = 'Frete') THEN
     BEGIN
      FOR SELECT P.PAG_VENCIMENTO, P.PAG_CODIGO FROM PAGAMENTOS P, FATURAMENTO2 F, TRANSPORTADORAS T, FRETES FR
      WHERE T.TRA_CODIGO = FR.FRE_TRA AND F.FAT2_TIPO = 4 AND F.FAT2_DESCRICAO = FR.FRE_CODIGO  AND P.PAG_FAT2 = F.FAT2_CODIGO AND P.PAG_ESTADO <> 1 AND T.TRA_CODIGO = :CODIGO
      INTO :VENCIMENTO, :PAGAMENTO DO
      BEGIN
           IF (:VENCIMENTO < :DATA) THEN
           BEGIN
                UPDATE PAGAMENTOS SET PAG_VENCIMENTO = :DATA WHERE PAG_CODIGO = :PAGAMENTO;
           END
      END
     END
END^


ALTER PROCEDURE ATUALIZA_VENDA
AS
DECLARE VARIABLE CODIGO INTEGER;
DECLARE VARIABLE FATURA INTEGER;
DECLARE VARIABLE CLIENTE INTEGER;
BEGIN
    FOR SELECT VEN_CODIGO, VEN_FAT FROM VENDAS
    INTO :CODIGO, :FATURA DO
    BEGIN
      SELECT FAT_CLI FROM FATURAMENTOS WHERE FAT_CODIGO = :FATURA
      INTO :CLIENTE;
      UPDATE VENDAS SET VEN_CLI = :CLIENTE
      WHERE VEN_CODIGO = :CODIGO;
    END
END^


ALTER PROCEDURE ATUALIZA_VENDA_COMPRA
AS
declare variable codigo integer;
declare variable descricao integer;
BEGIN
     FOR SELECT FAT_CODIGO, FAT_DESCRICAO FROM FATURAMENTOS WHERE FAT_TIPO = 1
     INTO :CODIGO, :DESCRICAO DO
     BEGIN
       UPDATE VENDAS SET VEN_FAT = :CODIGO WHERE VEN_CODIGO = :DESCRICAO;
     END
     FOR SELECT FAT2_CODIGO, FAT2_DESCRICAO FROM FATURAMENTO2 WHERE FAT2_TIPO = 1
     INTO :CODIGO, :DESCRICAO DO
     BEGIN
       UPDATE COMPRAS SET COM_FAT2 = :CODIGO WHERE COM_CODIGO = :DESCRICAO;
     END
     FOR SELECT FAT2_CODIGO, FAT2_DESCRICAO FROM FATURAMENTO2 WHERE FAT2_TIPO = 2
     INTO :CODIGO, :DESCRICAO DO
     BEGIN
       UPDATE CUSTOS SET CUST_FAT2 = :CODIGO WHERE CUST_CODIGO = :DESCRICAO;
     END
     FOR SELECT FAT2_CODIGO, FAT2_DESCRICAO FROM FATURAMENTO2 WHERE FAT2_TIPO = 3
     INTO :CODIGO, :DESCRICAO DO
     BEGIN
       UPDATE TRIBUTACOES SET TRI_FAT2 = :CODIGO WHERE TRI_CODIGO = :DESCRICAO;
     END
     FOR SELECT FAT2_CODIGO, FAT2_DESCRICAO FROM FATURAMENTO2 WHERE FAT2_TIPO = 4
     INTO :CODIGO, :DESCRICAO DO
     BEGIN
       UPDATE FRETES SET FRE_FAT2 = :CODIGO WHERE FRE_CODIGO = :DESCRICAO;
     END
END^


