ALTER PROCEDURE BALANCO_PATRIMONIAL (
    DATA DATE)
RETURNS (
    ESTOQUEC FLOAT,
    ESTOQUECM FLOAT,
    ESTOQUEL FLOAT,
    ESTOQUEV FLOAT,
    RECEBIMENTO FLOAT,
    PAGAMENTO FLOAT,
    CONTA FLOAT,
    FINANCIAMENTO FLOAT,
    DESPESA FLOAT,
    FOLHA_PAGAMENTO FLOAT)
AS
declare variable quantidade float;
declare variable valorc float;
declare variable valorcm float;
declare variable valorl float;
declare variable valorv float;
declare variable valor float;
declare variable juros float;
declare variable descontos float;
declare variable dinheiro float;
declare variable cheque float;
declare variable vale float;
declare variable inss float;
declare variable irrp float;
declare variable ferias float;
declare variable hora_extra float;
declare variable valor_folha float;
declare variable codigo integer;
BEGIN
     ESTOQUEC = 0;
     ESTOQUECM = 0;
     ESTOQUEL = 0;
     ESTOQUEV = 0;
     VALE = 0;
     INSS = 0;
     IRRP = 0;
     FERIAS = 0;
     HORA_EXTRA = 0;
     VALOR_FOLHA = 0;
     FOR SELECT PRO_QUANTIDADE, PRO_VALORC, PRO_VALORCM, PRO_VALORF, PRO_VALORV FROM PRODUTOS
     INTO :QUANTIDADE, :VALORC, :VALORCM, :VALORL, :VALORV DO
     BEGIN
          if (VALORC IS NULL) then
          begin
           ESTOQUEC = ESTOQUEC + 0;
          end
          else
          begin
           ESTOQUEC = ESTOQUEC + (VALORC*QUANTIDADE);
          end
          if (VALORCM IS NULL) then
          begin
           ESTOQUECM = ESTOQUECM + 0;
          end
          else
          begin
           ESTOQUECM = ESTOQUECM + (VALORCM*QUANTIDADE);
          end
          if (VALORL IS NULL) then
          begin
           ESTOQUEL = ESTOQUEL + 0;
          end
          else
          begin
           ESTOQUEL = ESTOQUEL + (VALORL*QUANTIDADE);
          end
          if (VALORV IS NULL) then
          begin
           ESTOQUEV = ESTOQUEV + 0;
          end
          else
          begin
           ESTOQUEV = ESTOQUEV + (VALORV*QUANTIDADE);
          end
     END
     VALOR = 0;
     JUROS = 0;
     DESCONTOS = 0;
     DINHEIRO = 0;
     CHEQUE = 0;
     SELECT SUM(R.REC_VALOR), SUM(R.REC_JUROS), SUM(R.REC_DESCONTOS)
     FROM RECEBIMENTOS R
     WHERE R.REC_ESTADO < 3 AND (R.REC_SITUACAO >= 0 AND R.REC_SITUACAO < 3)
     INTO :VALOR, :JUROS, :DESCONTOS;
     SELECT SUM(RP.RP_DINHEIRO), SUM(RP.RP_CHEQUE)
     FROM RECEBIMENTOS R, REC_PGM RP
     WHERE R.REC_CODIGO = RP.RP_REC AND R.REC_ESTADO = 2 AND (R.REC_SITUACAO >= 0 AND R.REC_SITUACAO < 3)
     INTO :DINHEIRO, :CHEQUE;
     if (:DINHEIRO IS NULL) then
      DINHEIRO = 0;
     if (:CHEQUE IS NULL) then
      CHEQUE = 0;
     
     RECEBIMENTO = (:VALOR + :JUROS - :DESCONTOS) - (:DINHEIRO + :CHEQUE);
     VALOR = 0;
     JUROS = 0;
     DESCONTOS = 0;
     DINHEIRO = 0;
     CHEQUE = 0;
     SELECT SUM(P.PAG_VALOR), SUM(P.PAG_JUROS), SUM(P.PAG_DESCONTOS)
     FROM PAGAMENTOS P, FATURAMENTO2 F
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND (F.FAT2_TIPO = 1) AND P.PAG_ESTADO <> 3
     AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
     INTO :VALOR, :JUROS, :DESCONTOS;
     SELECT SUM(PP.PP_DINHEIRO), SUM(PP.PP_CHEQUE)
     FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND (F.FAT2_TIPO = 1) AND P.PAG_CODIGO = PP.PP_PAG AND P.PAG_ESTADO = 2
     AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
     INTO :DINHEIRO, :CHEQUE;
     if (:DINHEIRO IS NULL) then
      DINHEIRO = 0;
     if (:CHEQUE IS NULL) then
      CHEQUE = 0;

     PAGAMENTO = ((:VALOR + :JUROS - :DESCONTOS) - (:DINHEIRO + :CHEQUE));
     VALOR = 0;
     JUROS = 0;
     DESCONTOS = 0;
     DINHEIRO = 0;
     CHEQUE = 0;
     SELECT SUM(P.PAG_VALOR), SUM(P.PAG_JUROS), SUM(P.PAG_DESCONTOS)
     FROM PAGAMENTOS P, FATURAMENTO2 F
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND ((F.FAT2_TIPO = 2) or (F.FAT2_TIPO = 3) or (F.FAT2_TIPO = 4)) AND P.PAG_ESTADO <> 3
     AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
     INTO :VALOR, :JUROS, :DESCONTOS;
     SELECT SUM(PP.PP_DINHEIRO), SUM(PP.PP_CHEQUE)
     FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND ((F.FAT2_TIPO = 2) or (F.FAT2_TIPO = 3) or (F.FAT2_TIPO = 4)) AND P.PAG_CODIGO = PP.PP_PAG AND P.PAG_ESTADO = 2
     AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
     INTO :DINHEIRO, :CHEQUE;
     if (:DINHEIRO IS NULL) then
      DINHEIRO = 0;
     if (:CHEQUE IS NULL) then
      CHEQUE = 0;


     DESPESA = ((:VALOR + :JUROS - :DESCONTOS) - (:DINHEIRO + :CHEQUE));
     
     SELECT SUM(P.PAG_VALOR), SUM(P.PAG_JUROS), SUM(P.PAG_DESCONTOS)
     FROM PAGAMENTOS P, FATURAMENTO2 F
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND F.FAT2_TIPO = 6 AND P.PAG_ESTADO <> 3
     INTO :VALOR, :JUROS, :DESCONTOS;
     SELECT SUM(PP.PP_DINHEIRO), SUM(PP.PP_CHEQUE)
     FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND F.FAT2_TIPO = 6 AND P.PAG_CODIGO = PP.PP_PAG AND P.PAG_ESTADO = 2
     INTO :DINHEIRO, :CHEQUE;
     if (:DINHEIRO IS NULL) then
      DINHEIRO = 0;
     if (:CHEQUE IS NULL) then
      CHEQUE = 0;
     FINANCIAMENTO = ((:VALOR + :JUROS - :DESCONTOS) - (:DINHEIRO + :CHEQUE));
     SELECT SUM(CON_SALDO)
     FROM CONTAS
     INTO :CONTA;

     FOR SELECT FOL_CODIGO, FOL_VALORSAL FROM FOLHA_PAGAMENTOS
     WHERE FOL_ESTADO = 'ATIVO'
     INTO :CODIGO, :VALOR DO
     BEGIN
      SELECT SUM(EF_VALOR) FROM ENCARGO_FOLHA WHERE EF_TIPO = 1 AND EF_FOL = :CODIGO
      INTO :VALE;
      SELECT SUM(EF_VALOR) FROM ENCARGO_FOLHA WHERE EF_TIPO = 2 AND EF_FOL = :CODIGO
      INTO :INSS;
      SELECT SUM(EF_VALOR) FROM ENCARGO_FOLHA WHERE EF_TIPO = 3 AND EF_FOL = :CODIGO
      INTO :IRRP;
      SELECT SUM(F13_VALOR) FROM FERIAS_13 WHERE F13_FOL = :CODIGO
      INTO :FERIAS;
      SELECT SUM(HEX_VALOR*HEX_HORAS) FROM HEXTRA WHERE HEX_FOL = :CODIGO
      INTO :HORA_EXTRA;

      if (VALE IS NULL) then
       VALE = 0;
      if (INSS IS NULL) then
       INSS = 0;
      if (IRRP IS NULL) then
       IRRP = 0;
      if (FERIAS IS NULL) then
       FERIAS = 0;
      if (HORA_EXTRA IS NULL) then
       HORA_EXTRA = 0;

      VALOR_FOLHA = VALOR_FOLHA + VALOR + FERIAS + HORA_EXTRA;
      DESCONTOS = DESCONTOS + VALE + INSS + IRRP;
     END
     FOLHA_PAGAMENTO = VALOR_FOLHA - DESCONTOS;
     
     
END^


ALTER PROCEDURE BP_ATIVO (
    DATA1 DATE,
    DATA2 DATE)
RETURNS (
    SALDO_CAIXA FLOAT,
    SALDO_BANCO FLOAT,
    SALDO_AP FLOAT,
    CONTA_RECEBER FLOAT,
    ADIANT_FORNECEDORES FLOAT,
    DESCONTO_TITULO FLOAT,
    VALOR_PRODUTOS FLOAT,
    CONTA_RECEBER_LP FLOAT,
    SALDO_AP_LP FLOAT,
    IMOBILIZADO FLOAT,
    DEPRECIACAO_ACUM FLOAT)
AS
declare variable VALOR_CAIXA float;
declare variable VALOR float;
declare variable VALOR_PG float;
declare variable PDV integer;
declare variable QUANTIDADE float;
declare variable VALORCM float;
declare variable DATAC date;
declare variable VALORC float;
declare variable VALORD float;
declare variable PERCENTUALD numeric(3,2);
declare variable COD_CAIXA float;
declare variable COD_CONF integer;
declare variable PERIODO_APURACAO integer;
BEGIN
     SALDO_CAIXA = 0;
     SALDO_BANCO = 0;
     SALDO_AP = 0;
     CONTA_RECEBER = 0;
     ADIANT_FORNECEDORES = 0;
     DESCONTO_TITULO = 0;
     VALOR_PRODUTOS = 0;
     CONTA_RECEBER_LP = 0;
     SALDO_AP_LP = 0;
     IMOBILIZADO = 0;
     DEPRECIACAO_ACUM = 0;
     VALOR_CAIXA = 0;
     /*VALORD_NOVO = 0;*/
     FOR SELECT MAX(CAI_CODIGO), CAI_PDV FROM CAIXA GROUP BY CAI_PDV
     INTO :COD_CAIXA, :PDV DO
     BEGIN
       SELECT CAI_VALORD FROM CAIXA WHERE CAI_CODIGO = :COD_CAIXA
       INTO :VALOR_CAIXA;
       if (VALOR_CAIXA IS NULL) then
        VALOR_CAIXA = 0;
       SALDO_CAIXA = SALDO_CAIXA + VALOR_CAIXA;
     END
     SELECT SUM(CON_SALDO) FROM CONTAS WHERE CON_TIPO = 'NORMAL'
     INTO :SALDO_BANCO;
     if (SALDO_BANCO IS NULL) then
      SALDO_BANCO = 0;
     SELECT SUM(CON_SALDO) FROM CONTAS WHERE CON_TIPO = 'APLICACAO'
     INTO :SALDO_AP;
     if (SALDO_AP IS NULL) then
      SALDO_AP = 0;
     SELECT SUM(R.REC_VALOR+R.REC_JUROS-R.REC_DESCONTOS) FROM RECEBIMENTOS R
     WHERE R.REC_ESTADO < 3 AND R.REC_VENCIMENTO <= :DATA2 AND (R.REC_SITUACAO >= 0 AND R.REC_SITUACAO < 3)
     INTO :VALOR;
     if (VALOR IS NULL) then
      VALOR = 0;
     SELECT SUM(RP.RP_DINHEIRO) FROM RECEBIMENTOS R, REC_PGM RP
     WHERE R.REC_CODIGO = RP.RP_REC AND R.REC_ESTADO = 2 AND R.REC_VENCIMENTO <= :DATA2 AND (R.REC_SITUACAO >= 0 AND R.REC_SITUACAO < 3)
     INTO :VALOR_PG;
     if (VALOR_PG IS NULL) then
      VALOR_PG = 0;
     CONTA_RECEBER = :VALOR - VALOR_PG;
     SELECT SUM(R.REC_VALOR+R.REC_JUROS-R.REC_DESCONTOS) FROM RECEBIMENTOS R, FATURAMENTOS F, CREDITO_FORNECEDOR C
     WHERE R.REC_FAT = F.FAT_CODIGO AND C.CF_FAT2 = F.FAT_CODIGO AND R.REC_ESTADO < 3 AND R.REC_VENCIMENTO <= :DATA2 AND (R.REC_SITUACAO >= 0 AND 
R.REC_SITUACAO < 3)
     INTO :VALOR;
     if (VALOR IS NULL) then
      VALOR = 0;
     SELECT SUM(RP.RP_DINHEIRO) FROM RECEBIMENTOS R, REC_PGM RP, FATURAMENTOS F, CREDITO_FORNECEDOR C
     WHERE R.REC_FAT = F.FAT_CODIGO AND C.CF_FAT2 = F.FAT_CODIGO AND R.REC_CODIGO = RP.RP_REC AND R.REC_ESTADO = 2 AND R.REC_VENCIMENTO <= :DATA2 
AND (R.REC_SITUACAO >= 0 AND R.REC_SITUACAO < 3)
     INTO :VALOR_PG;
     if (VALOR_PG IS NULL) then
      VALOR_PG = 0;
     ADIANT_FORNECEDORES = :VALOR - VALOR_PG;
     SELECT SUM(AC_VALOR+AC_VALORR) FROM ANT_CREDITO WHERE AC_DATA_COMPENS IS NULL AND AC_DATAD IS NULL
     INTO :DESCONTO_TITULO;
     if (DESCONTO_TITULO IS NULL) then
      DESCONTO_TITULO = 0;
     FOR SELECT PRO_QUANTIDADE, PRO_VALORCM FROM PRODUTOS
     INTO :QUANTIDADE, :VALORCM DO
     BEGIN
       if (VALORCM IS NULL) then
       begin
         VALOR_PRODUTOS = VALOR_PRODUTOS + 0;
       end
       else
       begin
         VALOR_PRODUTOS = VALOR_PRODUTOS + (VALORCM*QUANTIDADE);
       end
     END
     SELECT SUM(R.REC_VALOR+R.REC_JUROS-R.REC_DESCONTOS) FROM RECEBIMENTOS R
     WHERE R.REC_ESTADO < 3 AND R.REC_VENCIMENTO > :DATA2 AND (R.REC_SITUACAO >= 0 AND R.REC_SITUACAO < 3)
     INTO :VALOR;
     if (VALOR IS NULL) then
      VALOR = 0;
     SELECT SUM(RP.RP_DINHEIRO) FROM RECEBIMENTOS R, REC_PGM RP
     WHERE R.REC_CODIGO = RP.RP_REC AND R.REC_ESTADO = 2 AND R.REC_VENCIMENTO > :DATA2 AND (R.REC_SITUACAO >= 0 AND R.REC_SITUACAO < 3)
     INTO :VALOR_PG;
     if (VALOR_PG IS NULL) then
      VALOR_PG = 0;
     CONTA_RECEBER_LP = :VALOR - VALOR_PG;
     SELECT SUM(CON_SALDO) FROM CONTAS, APLICACAO_RESGATE WHERE AR_CON = CON_CODIGO AND CON_TIPO = 'APLICACAO' AND AR_VENCIMENTO > :DATA2
     INTO :SALDO_AP_LP;
     if (SALDO_AP_LP IS NULL) then
      SALDO_AP_LP = 0;
     SELECT SUM(IMO_VALORC-IMO_VALORV) FROM IMOBILIZADOS
     INTO :IMOBILIZADO;
     if (IMOBILIZADO IS NULL) then
      IMOBILIZADO = 0;
     DEPRECIACAO_ACUM = 0;
     SELECT MAX(CONF_CODIGO) FROM CONFIGURACOES
     INTO :COD_CONF;
     SELECT CONF_PERIODO_APURACAO FROM CONFIGURACOES WHERE CONF_CODIGO = :COD_CONF
     INTO :PERIODO_APURACAO;
     if (PERIODO_APURACAO IS NULL) then
      PERIODO_APURACAO = 0;
     FOR SELECT IMO_DATAC, IMO_VALORC, IMO_VALORD, IMO_PERCENTUALD FROM IMOBILIZADOS
     INTO :DATAC, :VALORC, :VALORD, :PERCENTUALD DO
     BEGIN
          if ((DATAC + 30) <= DATA1) then
          begin
            DEPRECIACAO_ACUM = DEPRECIACAO_ACUM + VALORD +(((VALORC-VALORD)*(PERCENTUALD/100))/365)*30;
            /*VALORD_NOVO = VALORD_NOVO + (((VALORC-VALORD)*(PERCENTUALD/100))/365)*30;*/
          end
          else
          begin
            if ((DATAC+30) <= (DATA2 - PERIODO_APURACAO)) then
            begin
              DEPRECIACAO_ACUM = DEPRECIACAO_ACUM + VALORD +(((VALORC-VALORD)*(PERCENTUALD/100))/365)*((DATA2-PERIODO_APURACAO)-(DATAC+30));
              /*VALORD_NOVO = VALORD_NOVO + (((VALORC-VALORD)*(PERCENTUALD/100))/365)*(DATA2-(DATAC+30));*/
            end
          end
     END
END^


ALTER PROCEDURE BP_PASSIVO (
    DATA1 DATE,
    DATA2 DATE)
RETURNS (
    EMPRESTIMOS FLOAT,
    FORNECEDOR FLOAT,
    DESPESA FLOAT,
    TRIBUTACAO FLOAT,
    FRETE FLOAT,
    FOLHAS FLOAT,
    ADIANT_CLIENTE FLOAT,
    EMPRESTIMO_LP FLOAT,
    FORNECEDOR_LP FLOAT,
    CONTA_PAGAR_LP FLOAT)
AS
declare variable VALOR float;
declare variable VALOR_PG float;
declare variable DESPESA_LP float;
declare variable TRIBUTO_LP float;
declare variable FRETE_LP float;
declare variable FOLHA_LP float;
declare variable ADIANT_CLIENTE_LP float;
declare variable VALOR_FOLHA float;
declare variable VALE float;
declare variable INSS float;
declare variable CODIGO integer;
declare variable DESCONTOS float;
declare variable HORA_EXTRA float;
declare variable FERIAS float;
BEGIN
     EMPRESTIMOS = 0;
     FORNECEDOR = 0;
     DESPESA = 0;
     TRIBUTACAO = 0;
     FRETE = 0;
     FOLHAS = 0;
     ADIANT_CLIENTE = 0;
     SELECT SUM(P.PAG_VALOR+P.PAG_JUROS-P.PAG_DESCONTOS) FROM PAGAMENTOS P, FATURAMENTO2 F, FINANCIAMENTOS FI
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND FI.FIN_FAT2 = F.FAT2_CODIGO AND P.PAG_ESTADO < 3 AND P.PAG_VENCIMENTO <= :DATA2 AND (P.PAG_SITUACAO >= 0 
AND P.PAG_SITUACAO < 3)
     INTO :VALOR;
     if (:VALOR IS NULL) then
       VALOR = 0;
     SELECT SUM(PP.PP_DINHEIRO) FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F, FINANCIAMENTOS FI
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND FI.FIN_FAT2 = F.FAT2_CODIGO AND P.PAG_CODIGO = PP.PP_PAG AND P.PAG_ESTADO = 2 AND P.PAG_VENCIMENTO <= 
:DATA2 AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
     INTO :VALOR_PG;
     if (:VALOR_PG IS NULL) then
       VALOR_PG = 0;
     EMPRESTIMOS = (:VALOR - :VALOR_PG);
     SELECT SUM(P.PAG_VALOR+P.PAG_JUROS-P.PAG_DESCONTOS) FROM PAGAMENTOS P, FATURAMENTO2 F
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND P.PAG_ESTADO < 3 AND FAT2_TIPO = 1 AND P.PAG_VENCIMENTO <= :DATA2 AND (P.PAG_SITUACAO >= 0 AND 
P.PAG_SITUACAO < 3)
     INTO :VALOR;
     if (:VALOR IS NULL) then
       VALOR = 0;
     SELECT SUM(PP.PP_DINHEIRO) FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND P.PAG_CODIGO = PP.PP_PAG AND FAT2_TIPO = 1 AND P.PAG_ESTADO = 2 AND P.PAG_VENCIMENTO <= :DATA2 AND 
(P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
     INTO :VALOR_PG;
     if (:VALOR_PG IS NULL) then
       VALOR_PG = 0;
     FORNECEDOR = (:VALOR - :VALOR_PG);
     SELECT SUM(P.PAG_VALOR+P.PAG_JUROS-P.PAG_DESCONTOS) FROM PAGAMENTOS P, FATURAMENTO2 F, CUSTOS C
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND C.CUST_FAT2 = F.FAT2_CODIGO AND P.PAG_ESTADO < 3 AND P.PAG_VENCIMENTO <= :DATA2 AND (P.PAG_SITUACAO >= 0 
AND P.PAG_SITUACAO < 3)
     INTO :VALOR;
     if (:VALOR IS NULL) then
       VALOR = 0;
     SELECT SUM(PP.PP_DINHEIRO) FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F, CUSTOS C
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND C.CUST_FAT2 = F.FAT2_CODIGO AND P.PAG_CODIGO = PP.PP_PAG AND P.PAG_ESTADO = 2 AND P.PAG_VENCIMENTO <= 
:DATA2 AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
     INTO :VALOR_PG;
     if (:VALOR_PG IS NULL) then
       VALOR_PG = 0;
     DESPESA = (:VALOR - :VALOR_PG);
     SELECT SUM(P.PAG_VALOR+P.PAG_JUROS-P.PAG_DESCONTOS) FROM PAGAMENTOS P, FATURAMENTO2 F, TRIBUTACOES T
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND T.TRI_FAT2 = F.FAT2_CODIGO AND P.PAG_ESTADO < 3 AND P.PAG_VENCIMENTO <= :DATA2 AND (P.PAG_SITUACAO >= 0 
AND P.PAG_SITUACAO < 3)
     INTO :VALOR;
     if (:VALOR IS NULL) then
       VALOR = 0;
     SELECT SUM(PP.PP_DINHEIRO) FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F, TRIBUTACOES T
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND T.TRI_FAT2 = F.FAT2_CODIGO AND P.PAG_CODIGO = PP.PP_PAG AND P.PAG_ESTADO = 2 AND P.PAG_VENCIMENTO <= 
:DATA2 AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
     INTO :VALOR_PG;
     if (:VALOR_PG IS NULL) then
       VALOR_PG = 0;
     TRIBUTACAO = (:VALOR - :VALOR_PG);
     SELECT SUM(P.PAG_VALOR+P.PAG_JUROS-P.PAG_DESCONTOS) FROM PAGAMENTOS P, FATURAMENTO2 F, FRETES FR
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND FR.FRE_FAT2 = F.FAT2_CODIGO AND P.PAG_ESTADO < 3 AND P.PAG_VENCIMENTO <= :DATA2 AND (P.PAG_SITUACAO >= 0 
AND P.PAG_SITUACAO < 3)
     INTO :VALOR;
     if (:VALOR IS NULL) then
       VALOR = 0;
     SELECT SUM(PP.PP_DINHEIRO) FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F, FRETES FR
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND FR.FRE_FAT2 = F.FAT2_CODIGO AND P.PAG_CODIGO = PP.PP_PAG AND P.PAG_ESTADO = 2 AND P.PAG_VENCIMENTO <= 
:DATA2 AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
     INTO :VALOR_PG;
     if (:VALOR_PG IS NULL) then
       VALOR_PG = 0;
     FRETE = (:VALOR - :VALOR_PG);
     VALOR_FOLHA = 0;
     DESCONTOS = 0;
     HORA_EXTRA = 0;
     FERIAS = 0;
     VALE = 0;
     INSS = 0;
     FOR SELECT FOL_CODIGO, FOL_VALORSAL FROM FOLHA_PAGAMENTOS
     WHERE FOL_ESTADO = 'ATIVO'
     INTO :CODIGO, :VALOR DO
     BEGIN
      SELECT SUM(HEX_VALOR) FROM HEXTRA WHERE HEX_DATAC = '01/01/1900' AND HEX_FOL = :CODIGO
      INTO :HORA_EXTRA;
      SELECT SUM(F13_VALOR) FROM FERIAS_13 WHERE F13_TIPO < 3 AND F13_DATAC = '01/01/1900' AND F13_FOL = :CODIGO
      INTO :FERIAS;
      SELECT SUM(AF_VALOR) FROM ADIANTAMENTO_FOLHA WHERE AF_DATAC = '01/01/1900' AND AF_FOL = :CODIGO
      INTO :VALE;
      SELECT SUM(F13_VALOR) FROM FERIAS_13 WHERE F13_TIPO = 3 AND F13_DATAC = '01/01/1900' AND F13_FOL = :CODIGO
      INTO :INSS;
      if (VALE IS NULL) then
       VALE = 0;
      if (INSS IS NULL) then
       INSS = 0;
      if (HORA_EXTRA IS NULL) then
       HORA_EXTRA = 0;
      if (FERIAS IS NULL) then
       FERIAS = 0;
      VALOR_FOLHA = VALOR_FOLHA + VALOR + HORA_EXTRA + FERIAS;
      DESCONTOS = DESCONTOS + VALE + INSS;
     END
     FOLHAS = VALOR_FOLHA - DESCONTOS;
     SELECT SUM(P.PAG_VALOR+P.PAG_JUROS-P.PAG_DESCONTOS) FROM PAGAMENTOS P, FATURAMENTO2 F, CREDITO_CLIENTE CC
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND CC.CC_FAT = F.FAT2_CODIGO AND P.PAG_ESTADO < 3 AND P.PAG_VENCIMENTO <= :DATA2 AND (P.PAG_SITUACAO >= 0 
AND P.PAG_SITUACAO < 3)
     INTO :VALOR;
     if (:VALOR IS NULL) then
       VALOR = 0;
     SELECT SUM(PP.PP_DINHEIRO) FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F, CREDITO_CLIENTE CC
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND CC.CC_FAT2 = F.FAT2_CODIGO AND P.PAG_CODIGO = PP.PP_PAG AND P.PAG_ESTADO = 2 AND P.PAG_VENCIMENTO <= 
:DATA2 AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
     INTO :VALOR_PG;
     if (:VALOR_PG IS NULL) then
       VALOR_PG = 0;
     ADIANT_CLIENTE = (:VALOR - :VALOR_PG);
     SELECT SUM(P.PAG_VALOR+P.PAG_JUROS-P.PAG_DESCONTOS) FROM PAGAMENTOS P, FATURAMENTO2 F, FINANCIAMENTOS FI
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND FI.FIN_FAT2 = F.FAT2_CODIGO AND P.PAG_ESTADO < 3 AND P.PAG_VENCIMENTO > :DATA2 AND (P.PAG_SITUACAO >= 0 
AND P.PAG_SITUACAO < 3)
     INTO :VALOR;
     if (:VALOR IS NULL) then
       VALOR = 0;
     SELECT SUM(PP.PP_DINHEIRO) FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F, FINANCIAMENTOS FI
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND FI.FIN_FAT2 = F.FAT2_CODIGO AND P.PAG_CODIGO = PP.PP_PAG AND P.PAG_ESTADO = 2 AND P.PAG_VENCIMENTO > 
:DATA2 AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
     INTO :VALOR_PG;
     if (:VALOR_PG IS NULL) then
       VALOR_PG = 0;
     EMPRESTIMO_LP = (:VALOR - :VALOR_PG);
     SELECT SUM(P.PAG_VALOR+P.PAG_JUROS-P.PAG_DESCONTOS) FROM PAGAMENTOS P, FATURAMENTO2 F
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND FAT2_TIPO = 1 AND P.PAG_ESTADO < 3 AND P.PAG_VENCIMENTO > :DATA2 AND (P.PAG_SITUACAO >= 0 AND 
P.PAG_SITUACAO < 3)
     INTO :VALOR;
     if (:VALOR IS NULL) then
       VALOR = 0;
     SELECT SUM(PP.PP_DINHEIRO) FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND FAT2_TIPO = 1 AND P.PAG_CODIGO = PP.PP_PAG AND P.PAG_ESTADO = 2 AND P.PAG_VENCIMENTO > :DATA2 AND 
(P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
     INTO :VALOR_PG;
     if (:VALOR_PG IS NULL) then
       VALOR_PG = 0;
     FORNECEDOR_LP = (:VALOR - :VALOR_PG);
     SELECT SUM(P.PAG_VALOR+P.PAG_JUROS-P.PAG_DESCONTOS) FROM PAGAMENTOS P, FATURAMENTO2 F, CUSTOS C
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND C.CUST_FAT2 = F.FAT2_CODIGO AND P.PAG_ESTADO < 3 AND P.PAG_VENCIMENTO > :DATA2 AND (P.PAG_SITUACAO >= 0 
AND P.PAG_SITUACAO < 3)
     INTO :VALOR;
     if (:VALOR IS NULL) then
       VALOR = 0;
     SELECT SUM(PP.PP_DINHEIRO) FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F, CUSTOS C
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND C.CUST_FAT2 = F.FAT2_CODIGO AND P.PAG_CODIGO = PP.PP_PAG AND P.PAG_ESTADO = 2 AND P.PAG_VENCIMENTO > 
:DATA2 AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
     INTO :VALOR_PG;
     if (:VALOR_PG IS NULL) then
       VALOR_PG = 0;
     DESPESA_LP = (:VALOR - :VALOR_PG);
     SELECT SUM(P.PAG_VALOR+P.PAG_JUROS-P.PAG_DESCONTOS) FROM PAGAMENTOS P, FATURAMENTO2 F, TRIBUTACOES T
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND T.TRI_FAT2 = F.FAT2_CODIGO AND P.PAG_ESTADO < 3 AND P.PAG_VENCIMENTO > :DATA2 AND (P.PAG_SITUACAO >= 0 
AND P.PAG_SITUACAO < 3)
     INTO :VALOR;
     if (:VALOR IS NULL) then
       VALOR = 0;
     SELECT SUM(PP.PP_DINHEIRO) FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F, TRIBUTACOES T
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND T.TRI_FAT2 = F.FAT2_CODIGO AND P.PAG_CODIGO = PP.PP_PAG AND P.PAG_ESTADO = 2 AND P.PAG_VENCIMENTO > 
:DATA2 AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
     INTO :VALOR_PG;
     if (:VALOR_PG IS NULL) then
       VALOR_PG = 0;
     TRIBUTO_LP = (:VALOR - :VALOR_PG);
     SELECT SUM(P.PAG_VALOR+P.PAG_JUROS-P.PAG_DESCONTOS) FROM PAGAMENTOS P, FATURAMENTO2 F, FRETES FR
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND FR.FRE_FAT2 = F.FAT2_CODIGO AND P.PAG_ESTADO < 3 AND P.PAG_VENCIMENTO > :DATA2 AND (P.PAG_SITUACAO >= 0 
AND P.PAG_SITUACAO < 3)
     INTO :VALOR;
     if (:VALOR IS NULL) then
       VALOR = 0;
     SELECT SUM(PP.PP_DINHEIRO) FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F, FRETES FR
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND FR.FRE_FAT2 = F.FAT2_CODIGO AND P.PAG_CODIGO = PP.PP_PAG AND P.PAG_ESTADO = 2 AND P.PAG_VENCIMENTO > 
:DATA2 AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
     INTO :VALOR_PG;
     if (:VALOR_PG IS NULL) then
       VALOR_PG = 0;
     FRETE_LP = (:VALOR - :VALOR_PG);
     FOLHA_LP = 0;
     SELECT SUM(P.PAG_VALOR+P.PAG_JUROS-P.PAG_DESCONTOS) FROM PAGAMENTOS P, FATURAMENTO2 F, CREDITO_CLIENTE CC
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND CC.CC_FAT = F.FAT2_CODIGO AND P.PAG_ESTADO < 3 AND P.PAG_VENCIMENTO > :DATA2 AND (P.PAG_SITUACAO >= 0 AND 
P.PAG_SITUACAO < 3)
     INTO :VALOR;
     if (:VALOR IS NULL) then
       VALOR = 0;
     SELECT SUM(PP.PP_DINHEIRO) FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F, CREDITO_CLIENTE CC
     WHERE F.FAT2_CODIGO = P.PAG_FAT2 AND CC.CC_FAT2 = F.FAT2_CODIGO AND P.PAG_CODIGO = PP.PP_PAG AND P.PAG_ESTADO = 2 AND P.PAG_VENCIMENTO > 
:DATA2 AND (P.PAG_SITUACAO >= 0 AND P.PAG_SITUACAO < 3)
     INTO :VALOR_PG;
     if (:VALOR_PG IS NULL) then
       VALOR_PG = 0;
     ADIANT_CLIENTE_LP = (:VALOR - :VALOR_PG);
     CONTA_PAGAR_LP = DESPESA_LP + TRIBUTO_LP + FRETE_LP + FOLHA_LP + ADIANT_CLIENTE_LP;
END^


ALTER PROCEDURE CALCULA_CARTEIRA (
    DATA1 DATE,
    DATA2 DATE)
RETURNS (
    EFETIVIDADE FLOAT,
    FREQUENCIA FLOAT,
    CLIENTE_NOVO FLOAT,
    CLIENTE_INATIVOS FLOAT,
    PRODUTOS_INATIVOS FLOAT,
    PRODUTOS_NOVOS FLOAT,
    N_PRODUTOS FLOAT,
    NCLIENTES FLOAT,
    EFETIVIDADEP FLOAT)
AS
declare variable clientesv float;
declare variable n_vendas float;
declare variable dias integer;
declare variable datav date;
declare variable codigo integer;
declare variable cod_gp integer;
declare variable n_produtos_venda float;
begin

     CLIENTESV = 0;
     CLIENTE_NOVO = 0;
     FOR SELECT DISTINCT(FAT_CLI) FROM FATURAMENTOS WHERE FAT_DATA BETWEEN :DATA1 AND :DATA2
     INTO :CODIGO DO
     BEGIN
          CLIENTESV = CLIENTESV + 1;
          SELECT MAX(VEN_CODIGO) FROM VENDAS, FATURAMENTOS WHERE VEN_FAT = FAT_CODIGO AND FAT_CLI = :CODIGO AND FAT_DATA < :DATA1
          INTO :COD_GP;
          if (COD_GP IS NULL) then
          begin
               CLIENTE_NOVO = CLIENTE_NOVO + 1;
          end
     END

     SELECT COUNT(CLI_CODIGO) FROM CLIENTES
     INTO :NCLIENTES;
     if (NCLIENTES IS NULL) then
      NCLIENTES = 0;
     if (NCLIENTES > 0) then
     begin
       EFETIVIDADE = (CLIENTESV/NCLIENTES)*100;
     end
     else
     begin
       EFETIVIDADE = 0;
     end
     CLIENTE_INATIVOS = NCLIENTES - CLIENTESV;

     SELECT COUNT(VEN_CODIGO)
     FROM VENDAS, FATURAMENTOS
     WHERE VEN_FAT = FAT_CODIGO AND VEN_DATAC = '01/01/1900'
     AND VEN_DATA BETWEEN :DATA1 AND :DATA2
     INTO :N_VENDAS;

     DIAS = 0;
     FOR SELECT DISTINCT(FAT_DATA) FROM FATURAMENTOS WHERE FAT_DATA BETWEEN :DATA1 AND :DATA2
     INTO :DATAV DO
     BEGIN
       DIAS = DIAS + 1;
     END

     if (DIAS > 0) then
     begin
       FREQUENCIA = N_VENDAS/DIAS;
     end
     else
     begin
       FREQUENCIA = 0;
     end

     N_PRODUTOS_VENDA = 0;
     FOR SELECT DISTINCT(VE_PRO)
     FROM VENDAS, VEN_EST
     WHERE VEN_CODIGO = VE_VEN AND VEN_DATAC = '01/01/1900' AND VEN_DATA BETWEEN :DATA1 AND :DATA2
     INTO :N_PRODUTOS DO
     BEGIN
       N_PRODUTOS_VENDA = N_PRODUTOS_VENDA + 1;
     END

     SELECT COUNT(PRO_CODIGO) FROM PRODUTOS
     INTO :N_PRODUTOS;

     PRODUTOS_INATIVOS = N_PRODUTOS - N_PRODUTOS_VENDA;

     EFETIVIDADEP = (N_PRODUTOS_VENDA/N_PRODUTOS)*100;

     PRODUTOS_NOVOS = 0;
     FOR SELECT DISTINCT(PRO_CODIGO) FROM PRODUTOS, COMPRAS, COM_EST
     WHERE COM_CODIGO = CE_COM AND CE_PRO = PRO_CODIGO AND COM_DATA BETWEEN :DATA1 AND :DATA2
     INTO :CODIGO DO
     BEGIN
          SELECT MAX(CE_CODIGO) FROM COM_EST, COMPRAS WHERE CE_COM = COM_CODIGO AND CE_PRO = :CODIGO AND COM_DATA < :DATA1
          INTO :COD_GP;
          if (COD_GP IS NULL) then
          begin
               PRODUTOS_NOVOS = PRODUTOS_NOVOS + 1;
          end
     END
  suspend;
end^


ALTER PROCEDURE CALCULA_CLASSIFICACAO (
    DATA DATE,
    DATA1 DATE,
    DATA2 DATE)
RETURNS (
    VENDAT FLOAT,
    LUCROT FLOAT)
AS
declare variable CODIGO integer;
declare variable COD_GP integer;
declare variable COD_DG integer;
declare variable COD_CLI integer;
declare variable VENDA float;
declare variable LUCRO float;
declare variable VALOR1 float;
declare variable VALOR2 float;
declare variable PESO float;
declare variable CLASSIFICACAO float;
declare variable PONTUACAO integer;
declare variable PORC float;
declare variable PORC2 float;
declare variable VALOR float;
declare variable VALOR_CLASSIF float;
declare variable DIAS integer;
declare variable SOMA_DIAS integer;
declare variable CONTADOR integer;
declare variable PMR1 integer;
declare variable PMR float;
declare variable PONTO_FIDEL integer;
declare variable FIDELIDADE varchar(15);
declare variable COMPRA float;
declare variable LUCROG float;
declare variable ATRATIVIDADE integer;
declare variable COD_PESO integer;
declare variable VENDAG float;
declare variable DESCONTAR varchar(4);
BEGIN
     CODIGO = 0;
     VENDAT = 0;
     COD_GP = 0;
     VENDAG = 0;
     COD_DG = GEN_ID(GEN_DG, 1);
     SELECT SUM(VE_VALOR), SUM(VE_LUCRO) FROM VENDAS, VEN_EST
     WHERE VEN_CODIGO = VE_VEN AND VEN_DATAC = '01/01/1900' AND VEN_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VENDAT, :LUCROT;
     if (VENDAT IS NULL) then
      VENDAT = 0;
     if (LUCROT IS NULL) then
      LUCROT = 0;
     INSERT INTO DEMANDA_G1 VALUES(:COD_DG, :DATA, :DATA1, :DATA2, :VENDAT, :LUCROT);
     FOR SELECT G1_CODIGO FROM GRUPO_1
     INTO :CODIGO DO
     BEGIN
          PESO = 0;
          SELECT SUM(VE_VALOR), SUM(VE_LUCRO) FROM VENDAS, VEN_EST, PRODUTOS, GRUPOS, GRUPO_1
          WHERE PRO_CODIGO = VE_PRO AND PRO_GRU = GRU_CODIGO AND GRU_G1 = G1_CODIGO AND
          VEN_CODIGO = VE_VEN AND VEN_DATAC = '01/01/1900' AND VEN_DATA BETWEEN :DATA1 AND :DATA2
          AND G1_CODIGO = :CODIGO
          INTO :VENDA, :LUCRO;
          if (VENDA IS NULL) then
           VENDA = 0;
          if (VENDAT IS NULL) then
           VENDAT = 0;
          if (LUCRO IS NULL) then
           LUCRO = 0;
          if (LUCROT IS NULL) then
           LUCROT = 0;
          if (VENDAT > 0) then
           VALOR1 = (VENDA/VENDAT)*100;
          if (LUCROT > 0) then
           VALOR2 = (LUCRO/LUCROT)*100;
          PESO = (VALOR1 + VALOR2)/2;
          COD_GP = GEN_ID(GEN_GP, 1);
          INSERT INTO G1_PESO VALUES(:COD_GP, :CODIGO, :PESO, :COD_DG);
     END
     FOR SELECT GP_G1, GP_CODIGO FROM G1_PESO WHERE GP_DG = :COD_DG
     INTO :CODIGO , :COD_GP DO
     BEGIN
          SELECT SUM(VE_VALOR) FROM VENDAS, VEN_EST, PRODUTOS, GRUPOS, GRUPO_1
          WHERE PRO_CODIGO = VE_PRO AND PRO_GRU = GRU_CODIGO AND GRU_G1 = G1_CODIGO AND
          VEN_CODIGO = VE_VEN AND VEN_DATAC = '01/01/1900' AND VEN_DATA BETWEEN :DATA1 AND :DATA2
          AND G1_CODIGO = :CODIGO
          INTO :VENDAG;
          FOR SELECT DISTINCT(FAT_CLI) FROM FATURAMENTOS, VENDAS, CLIENTES WHERE FAT_CLI = CLI_CODIGO AND VEN_FAT = FAT_CODIGO AND CLI_DESCONTAR = 
'SIM' AND VEN_DATA BETWEEN :DATA1 AND :DATA2
          INTO :COD_CLI DO
          BEGIN
               PESO = 0;
               SELECT SUM(VE_VALOR) FROM VENDAS, VEN_EST, PRODUTOS, GRUPOS, GRUPO_1, FATURAMENTOS
               WHERE VEN_FAT = FAT_CODIGO AND PRO_CODIGO = VE_PRO AND PRO_GRU = GRU_CODIGO AND GRU_G1 = G1_CODIGO AND
               VEN_CODIGO = VE_VEN AND VEN_DATAC = '01/01/1900' AND VEN_DATA BETWEEN :DATA1 AND :DATA2
               AND G1_CODIGO = :CODIGO AND FAT_CLI = :COD_CLI
               INTO :VENDA;
               if (VENDA IS NULL) then
                VENDA = 0;
               if (VENDAG IS NULL) then
                VENDAG = 0;
               if (VENDAG > 0) then
                PESO = (VENDA/VENDAG)*100;
               if ((PESO >= 0) and (PESO <=0.10)) then
                PONTUACAO = 1;
               else if ((PESO > 0.10) and (PESO <=0.25)) then
                PONTUACAO = 2;
               else if ((PESO > 0.25) and (PESO <=0.50)) then
                PONTUACAO = 3;
               else if ((PESO > 0.50) and (PESO <=0.75)) then
                PONTUACAO = 4;
               else if (PESO > 0.75) then
                PONTUACAO = 5;
                INSERT INTO GP_CLI VALUES(GEN_ID(GEN_GC, 1), :COD_CLI, :COD_GP, :PONTUACAO, :PESO, :VENDAG);
          END
     END
     FOR SELECT DISTINCT(FAT_CLI), CLI_FIDELIDADE, CLI_CLASSIFICACAO, CLI_DESCONTAR FROM FATURAMENTOS, VENDAS, CLIENTES WHERE FAT_CLI = CLI_CODIGO 
AND VEN_FAT = FAT_CODIGO AND CLI_DESCONTAR = 'SIM' AND VEN_DATA BETWEEN :DATA1 AND :DATA2
     INTO :COD_CLI, :FIDELIDADE, :VALOR_CLASSIF, :DESCONTAR DO
     BEGIN
          ATRATIVIDADE = GEN_ID(GEN_ATR, 1);
          INSERT INTO ATRATIVIDADES VALUES(:ATRATIVIDADE, :COD_DG, :COD_CLI);
          COMPRA = 0;
          CLASSIFICACAO = 0;
          PORC = 0;
          PORC2 = 0;
          LUCROG = 0;
          SELECT SUM(VE_VALOR), SUM(VE_LUCRO) FROM VENDAS, VEN_EST, FATURAMENTOS
          WHERE VEN_FAT = FAT_CODIGO AND VEN_CODIGO = VE_VEN AND VEN_DATAC = '01/01/1900'
          AND VEN_DATA BETWEEN :DATA1 AND :DATA2 AND FAT_CLI = :COD_CLI
          INTO :VALOR, :LUCRO;
          if (VALOR IS NULL) then
           VALOR = 0;
          if (VENDAT IS NULL) then
           VENDAT = 0;
          if (LUCRO IS NULL) then
           LUCRO = 0;
          if (LUCROT IS NULL) then
           LUCROT = 0;
          if (VENDAT > 0) then
           PORC = (VALOR/VENDAT);
          if (PORC < 0.001) then
           COMPRA = 1;
          ELSE if ((porc >= 0.001) and (PORC < 0.003)) then
           COMPRA = 2;
          ELSE if ((porc >= 0.003) and (PORC < 0.01)) then
           COMPRA = 3;
          ELSE if ((porc >= 0.01) and (PORC < 0.015)) then
           COMPRA = 4;
          ELSE COMPRA = 5;
          SELECT PES_CODIGO, PES_PESO FROM PESOS WHERE PES_CODIGO = 1
          INTO :COD_PESO, :PESO;
          CLASSIFICACAO = CLASSIFICACAO + (PESO*COMPRA);
          INSERT INTO ATR_PESO VALUES(GEN_ID(GEN_AP, 1), :ATRATIVIDADE, :COD_PESO, :COMPRA, :VALOR, :VENDAT);
          if (VALOR <> 0) then
           PORC2 = (LUCRO/VALOR);
          if (PORC2 < 0.02) then
           LUCROG = 1;
          ELSE if ((PORC2 >= 0.02) and (PORC2 < 0.05)) then
           LUCROG = 2;
          ELSE if ((PORC2 >= 0.05) and (PORC2 < 0.10)) then
           LUCROG = 3;
          ELSE if ((PORC2 >= 0.10) and (PORC2 < 0.12)) then
           LUCROG = 4;
          ELSE LUCROG = 5;
          SELECT PES_CODIGO, PES_PESO FROM PESOS WHERE PES_CODIGO = 2
          INTO :COD_PESO, :PESO;
          CLASSIFICACAO = CLASSIFICACAO + (PESO*LUCROG);
          INSERT INTO ATR_PESO VALUES(GEN_ID(GEN_AP, 1), :ATRATIVIDADE, :COD_PESO, :LUCROG, :LUCRO, :VALOR);
          if (FIDELIDADE = 'Nenhuma') then
           PONTO_FIDEL = 1;
          ELSE if (FIDELIDADE = 'Ruim') then
           PONTO_FIDEL = 2;
          ELSE if (FIDELIDADE = 'Regular') then
           PONTO_FIDEL = 3;
          ELSE if (FIDELIDADE = 'Bom') then
           PONTO_FIDEL = 4;
          ELSE if (FIDELIDADE = 'Otimo') then
           PONTO_FIDEL = 5;
          SELECT PES_CODIGO, PES_PESO FROM PESOS WHERE PES_CODIGO = 3
          INTO :COD_PESO, :PESO;
          CLASSIFICACAO = CLASSIFICACAO + (PESO*PONTO_FIDEL);
          INSERT INTO ATR_PESO VALUES(GEN_ID(GEN_AP, 1), :ATRATIVIDADE, :COD_PESO, :PONTO_FIDEL, 0, 0);
          SOMA_DIAS = 0;
          CONTADOR = 0;
          PMR1 = 0;
          PMR = 0;
          FOR SELECT CAST((RP_DATAPGM - VEN_DATA) AS INTEGER)
          FROM VENDAS, FATURAMENTOS, RECEBIMENTOS, REC_PGM
          WHERE VEN_FAT = FAT_CODIGO AND REC_FAT = FAT_CODIGO AND REC_CODIGO = RP_REC
          AND RP_DATAPGM IS NOT NULL AND (REC_SITUACAO >= 0 AND REC_SITUACAO < 3) AND FAT_CLI = :COD_CLI AND RP_DATAPGM BETWEEN :DATA1 AND :DATA2
          INTO :DIAS DO
          BEGIN
               SOMA_DIAS = SOMA_DIAS + DIAS;
               CONTADOR = CONTADOR + 1;
          END
          if (CONTADOR > 0) then
          begin
           PMR = (SOMA_DIAS/CONTADOR);
          end
          else
          begin
           PMR = 100;
          end
          if (PMR < 20) then
           PMR1 = 5;
          else if ((PMR >= 20) and (pmr < 30)) then
           PMR1 = 4;
          else if ((PMR >= 30) and (pmr < 60)) then
           PMR1 = 3;
          else if ((PMR >= 60) and (pmr < 90)) then
           PMR1 = 2;
          else if (PMR >= 90) then
           PMR1 = 1;
          SELECT PES_CODIGO, PES_PESO FROM PESOS WHERE PES_CODIGO = 4
          INTO :COD_PESO, :PESO;
          CLASSIFICACAO = CLASSIFICACAO + (PESO*PMR1);
          INSERT INTO ATR_PESO VALUES(GEN_ID(GEN_AP, 1), :ATRATIVIDADE, :COD_PESO, :PMR1, :PMR, 0);
          /*INSERT INTO ATR_PESO VALUES(GEN_ID(GEN_AP, 1), :ATRATIVIDADE, :COMPRA, :LUCRO, :PONTO_FIDEL, :PMR, :COMPRAP, :LUCROP, :FIDELIDADEP, :PMRP);*/
          if (CLASSIFICACAO <= 100) then
          begin
            if (DESCONTAR = 'SIM') then
            begin
              UPDATE CLIENTES SET CLI_NOTA = '7-CIC', CLI_DESCONTO = 8, CLI_CLASSIFICACAO = :CLASSIFICACAO, CLI_PMR = :PMR WHERE CLI_CODIGO = :COD_CLI;
            end
            else
            begin
              UPDATE CLIENTES SET CLI_NOTA = '7-CIC', CLI_CLASSIFICACAO = :CLASSIFICACAO, CLI_PMR = :PMR WHERE CLI_CODIGO = :COD_CLI;
            end
          end
          else if ((CLASSIFICACAO > 100) and (CLASSIFICACAO < 200)) then
          begin
            if (DESCONTAR = 'SIM') then
            begin
              UPDATE CLIENTES SET CLI_NOTA = '6-CVS', CLI_DESCONTO = 10, CLI_CLASSIFICACAO = :CLASSIFICACAO, CLI_PMR = :PMR WHERE CLI_CODIGO = :COD_CLI;
            end
            else
            begin
              UPDATE CLIENTES SET CLI_NOTA = '6-CVS', CLI_CLASSIFICACAO = :CLASSIFICACAO, CLI_PMR = :PMR WHERE CLI_CODIGO = :COD_CLI;
            end
          end
          else if ((CLASSIFICACAO >= 200) and (CLASSIFICACAO < 300)) then
          begin
            if (DESCONTAR = 'SIM') then
            begin
              UPDATE CLIENTES SET CLI_NOTA = '5-CIS', CLI_DESCONTO = 10, CLI_CLASSIFICACAO = :CLASSIFICACAO, CLI_PMR = :PMR WHERE CLI_CODIGO = :COD_CLI;
            end
            else
            begin
              UPDATE CLIENTES SET CLI_NOTA = '5-CIS', CLI_CLASSIFICACAO = :CLASSIFICACAO, CLI_PMR = :PMR WHERE CLI_CODIGO = :COD_CLI;
            end
          end
          else if ((CLASSIFICACAO >= 300) and (CLASSIFICACAO < 350)) then
          begin
            if (DESCONTAR = 'SIM') then
            begin
              UPDATE CLIENTES SET CLI_NOTA = '4-CBI', CLI_DESCONTO = 10, CLI_CLASSIFICACAO = :CLASSIFICACAO, CLI_PMR = :PMR WHERE CLI_CODIGO = :COD_CLI;
            end
            else
            begin
              UPDATE CLIENTES SET CLI_NOTA = '4-CBI', CLI_CLASSIFICACAO = :CLASSIFICACAO, CLI_PMR = :PMR WHERE CLI_CODIGO = :COD_CLI;
            end
          end
          else if ((CLASSIFICACAO >= 350) and (CLASSIFICACAO < 400)) then
          begin
            if (DESCONTAR = 'SIM') then
            begin
              UPDATE CLIENTES SET CLI_NOTA = '3-CT', CLI_DESCONTO = 12, CLI_CLASSIFICACAO = :CLASSIFICACAO, CLI_PMR = :PMR WHERE CLI_CODIGO = :COD_CLI;
            end
            else
            begin
              UPDATE CLIENTES SET CLI_NOTA = '3-CT', CLI_CLASSIFICACAO = :CLASSIFICACAO, CLI_PMR = :PMR WHERE CLI_CODIGO = :COD_CLI;
            end
          end
          else if ((CLASSIFICACAO >= 400) and (CLASSIFICACAO < 425)) then
          begin
            if (DESCONTAR = 'SIM') then
            begin
              UPDATE CLIENTES SET CLI_NOTA = '2-CP', CLI_DESCONTO = 15, CLI_CLASSIFICACAO = :CLASSIFICACAO, CLI_PMR = :PMR WHERE CLI_CODIGO = :COD_CLI;
            end
            else
            begin
              UPDATE CLIENTES SET CLI_NOTA = '2-CP', CLI_CLASSIFICACAO = :CLASSIFICACAO, CLI_PMR = :PMR WHERE CLI_CODIGO = :COD_CLI;
            end
          end
          else if (CLASSIFICACAO >= 425) then
          begin
            if (DESCONTAR = 'SIM') then
            begin
              UPDATE CLIENTES SET CLI_NOTA = '1-VIC', CLI_DESCONTO = 17, CLI_CLASSIFICACAO = :CLASSIFICACAO, CLI_PMR = :PMR WHERE CLI_CODIGO = :COD_CLI;
            end
            else
            begin
              UPDATE CLIENTES SET CLI_NOTA = '1-VIC', CLI_CLASSIFICACAO = :CLASSIFICACAO, CLI_PMR = :PMR WHERE CLI_CODIGO = :COD_CLI;
            end
          end
     END
END^


ALTER PROCEDURE CALCULA_DESCONTO (
    COD_CLIENTE INTEGER,
    DATA1 DATE,
    DATA2 DATE,
    FATURAMENTO NUMERIC(9,2))
RETURNS (
    COMPRA INTEGER,
    LUCRO INTEGER,
    COMPRA1 NUMERIC(9,2),
    LUCRO1 NUMERIC(9,4),
    PMR INTEGER,
    PMR1 INTEGER)
AS
declare variable valor float;
declare variable porc float;
declare variable porc2 float;
declare variable dias integer;
declare variable soma_dias integer;
declare variable contador integer;
begin
  /* Procedure Text */
  VALOR = 0;
  PORC = 0;
  LUCRO1 = 0;
  COMPRA1 = 0;
  SELECT SUM(RP.RP_DINHEIRO+RP.RP_CHEQUE)
  FROM FATURAMENTOS F, RECEBIMENTOS R, REC_PGM RP
  WHERE F.FAT_CODIGO = R.REC_FAT AND RP.RP_REC = R.REC_CODIGO AND R.REC_ESTADO = 3 AND F.FAT_CLI = :COD_CLIENTE
  AND RP.RP_DATAPGM IS NOT NULL AND RP.RP_DATAPGM BETWEEN :DATA1 AND :DATA2
  INTO :VALOR;
  if (VALOR IS NULL) then
   VALOR = 0;
  if (FATURAMENTO IS NULL) then
   FATURAMENTO = 0;

  PORC = :VALOR/:FATURAMENTO;
  COMPRA1 = PORC*100;
  if (PORC < 0.001) then
   COMPRA = 1;
  ELSE if ((porc >= 0.001) and (PORC < 0.005)) then
   COMPRA = 2;
  ELSE if ((porc >= 0.005) and (PORC < 0.01)) then
   COMPRA = 3;
  ELSE if ((porc >= 0.01) and (PORC < 0.02)) then
   COMPRA = 4;
  ELSE COMPRA = 5;

  SELECT SUM(VE.VE_LUCRO)
  FROM VEN_EST VE, VENDAS V, FATURAMENTOS F, RECEBIMENTOS R, REC_PGM RP
  WHERE VE.VE_VEN = V.VEN_CODIGO AND F.FAT_TIPO = 1 AND F.FAT_DESCRICAO = V.VEN_CODIGO AND
  F.FAT_CODIGO = R.REC_FAT AND R.REC_CODIGO = RP.RP_REC AND R.REC_ESTADO = 3 AND
  RP.RP_DATAPGM IS NOT NULL AND F.FAT_CLI = :COD_CLIENTE AND RP.RP_DATAPGM BETWEEN :DATA1 AND :DATA2
  INTO :LUCRO;
  if (LUCRO IS NULL) then
   LUCRO = 0;
  if (VALOR > 0) then
  BEGIN
   PORC2 = LUCRO/VALOR;
   LUCRO1 = PORC2*100;
  END
  ELSE PORC2 = 0;
  if (PORC2 < 0.05) then
   LUCRO = 1;
  ELSE if ((PORC2 >= 0.05) and (PORC2 < 0.07)) then
   LUCRO = 2;
  ELSE if ((PORC2 >= 0.07) and (PORC2 < 0.10)) then
   LUCRO = 3;
  ELSE if ((PORC2 >= 0.10) and (PORC2 < 0.12)) then
   LUCRO = 4;
  ELSE LUCRO = 5;

  SOMA_DIAS = 0;
  CONTADOR = 0;
  FOR SELECT CAST((RP_DATAPGM - VEN_DATA) AS INTEGER)
  FROM VENDAS, FATURAMENTOS, RECEBIMENTOS, REC_PGM
  WHERE VEN_FAT = FAT_CODIGO AND REC_FAT = FAT_CODIGO AND REC_CODIGO = RP_REC
  AND RP_DATAPGM IS NOT NULL AND FAT_CLI = :COD_CLIENTE AND RP_DATAPGM BETWEEN :DATA1 AND :DATA2
  INTO :DIAS DO
  BEGIN
    SOMA_DIAS = SOMA_DIAS + DIAS;
    CONTADOR = CONTADOR + 1;
  END
  if (CONTADOR > 0) then
  begin
    PMR = (SOMA_DIAS/CONTADOR);
  end
  if (PMR < 45) then
   PMR1 = 5;
  else if ((PMR >= 45) and (pmr < 60)) then
   PMR1 = 4;
  else if ((PMR >= 60) and (pmr < 75)) then
   PMR1 = 3;
  else if ((PMR >= 75) and (pmr < 90)) then
   PMR1 = 2;
  else if (PMR >= 90) then
   PMR1 = 1;
  suspend;
end^


ALTER PROCEDURE CALCULA_INDICADORES (
    DATA1 DATE,
    DATA2 DATE)
RETURNS (
    COMPRA_VENDA NUMERIC(3,2),
    RECEBIMENTO_VENDA NUMERIC(3,2),
    RENTABILIDADE NUMERIC(3,2),
    COMPRAV_COMPRAP NUMERIC(3,2),
    VENDAV_VENDAP NUMERIC(3,2),
    PAGAMENTO_COMPRA NUMERIC(3,2),
    DESPESAF_RECEITAF NUMERIC(3,2),
    PAGAMENTOT_COMPRA NUMERIC(9,2),
    RECEBIMENTOT_VENDA NUMERIC(3,2),
    RECEITA_DESPESA NUMERIC(3,2))
AS
declare variable valor numeric(9,2);
declare variable valor2 numeric(9,2);
declare variable valort numeric(9,2);
declare variable valort2 numeric(9,2);
declare variable codigo integer;
BEGIN
     VALORT = 0;
     VALORT2 = 0;
     FOR SELECT SUM(CE_QUANTIDADE), CE_PRO
     FROM COMPRAS, COM_EST, PRODUTOS
     WHERE PRO_CODIGO = CE_PRO AND CE_COM = COM_CODIGO AND
     COM_DATA BETWEEN :DATA1 AND :DATA2
     GROUP BY CE_PRO INTO :VALOR, :CODIGO DO
     BEGIN

          SELECT SUM(VE_QUANTIDADE)
          FROM VENDAS, VEN_EST
          WHERE VE_VEN = VEN_CODIGO AND VEN_DATA BETWEEN :DATA1 AND :DATA2 AND VE_PRO = :CODIGO
          INTO :VALOR2;
          if (VALOR2 IS NULL) then
           VALOR2 = 0;
          if (VALOR IS NULL) then
           VALOR = 0;
          VALORT2 = VALORT2 + VALOR2;
          VALORT = VALORT + VALOR;
     END
     if (VALORT2 <> 0) then
      Compra_Venda = (VALORT/VALORT2)*100;
     else Compra_Venda = 0;

     VALORT = 0;
     VALORT2 = 0;

     SELECT SUM(RP_DINHEIRO)
     FROM RECEBIMENTOS, REC_PGM, FATURAMENTOS
     WHERE REC_CODIGO = RP_REC AND FAT_CODIGO = REC_FAT
     AND (REC_SITUACAO >= 0 AND REC_SITUACAO < 3) AND RP_DATAPGM BETWEEN :DATA1 AND :DATA2 AND FAT_CODIGO IN (SELECT DISTINCT(FAT_CODIGO)
     FROM FATURAMENTOS, VENDAS
     WHERE FAT_CODIGO = VEN_FAT AND VEN_DATA BETWEEN :DATA1 AND :DATA2)
     INTO :VALORT;
          if (VALORT IS NULL) then
           VALORT = 0;

     SELECT SUM(VE_VALOR)
     FROM VEN_EST, VENDAS
     WHERE VE_VEN = VEN_CODIGO AND VEN_DATAC = '01/01/1900' AND VEN_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VALORT2;
     if (VALORT2 IS NULL) then
      VALORT2 = 0;
     if (VALORT2 <> 0) then
      Recebimento_Venda = (VALORT/VALORT2)*100;
     else Recebimento_Venda = 0;

     VALORT = 0;
     VALORT2 = 0;

     SELECT SUM(PP_DINHEIRO)
     FROM PAGAMENTOS, PAG_PGM, FATURAMENTO2
     WHERE PAG_CODIGO = PP_PAG AND FAT2_CODIGO = PAG_FAT2
     AND (PAG_SITUACAO >= 0 AND PAG_SITUACAO < 3) AND PP_DATAPGM BETWEEN :DATA1 AND :DATA2 AND FAT2_CODIGO IN (SELECT DISTINCT(FAT2_CODIGO)
     FROM FATURAMENTO2, COMPRAS
     WHERE FAT2_CODIGO = COM_FAT2 AND COM_DATA BETWEEN :DATA1 AND :DATA2)
     INTO :VALORT;
     if (VALORT IS NULL) then
      VALORT = 0;
     SELECT SUM(CE_VALOR)
     FROM COM_EST, COMPRAS
     WHERE CE_COM = COM_CODIGO AND COM_DATAC = '01/01/1900' AND COM_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VALORT2;
     if (VALORT2 IS NULL) then
      VALORT2 = 0;
     
     if (VALORT2 <> 0) then
      Pagamento_Compra = (VALORT/VALORT2)*100;
     else Pagamento_Compra = 0;

     VALORT = 0;
     VALORT2 = 0;
     SELECT SUM((DGE_311+DGE_312)-(DGE_321+DGE_322+DGE_323-DGE_324+DGE_325-DGE_326)), SUM(DGE_LL)
     FROM DGE
     WHERE DGE_DATAI >= :DATA1 AND DGE_DATAF <= :DATA2 INTO :VALORT2, :VALORT;
     if (VALORT IS NULL) then
      VALORT = 0;
     if (VALORT2 IS NULL) then
      VALORT2 = 0;
     
     if (VALORT2 <> 0) then
      Rentabilidade = (VALORT/VALORT2)*100;
     else Rentabilidade = 0;

     VALORT = 0;
     VALORT2 = 0;
     SELECT SUM(RP_DINHEIRO)
     FROM REC_PGM, RECEBIMENTOS, FATURAMENTOS, VENDAS
     WHERE RP_REC = REC_CODIGO AND REC_FAT = FAT_CODIGO AND VEN_FAT = FAT_CODIGO
     AND (REC_SITUACAO >= 0 AND REC_SITUACAO < 3) AND RP_DATAPGM = VEN_DATA AND VEN_DATAC = '01/01/1900' AND VEN_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VALORT;
     if (VALORT IS NULL) then
      VALORT = 0;
     
     SELECT SUM(VE_VALOR)
     FROM VEN_EST, VENDAS
     WHERE VE_VEN = VEN_CODIGO AND VEN_DATAC = '01/01/1900' AND VEN_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VALORT2;
     if (VALORT2 IS NULL) then
      VALORT2 = 0;
     
     if (VALORT2 <> 0) then
      VendaV_VendaP  = (VALORT/VALORT2)*100;
     else VendaV_VendaP = 0;

     VALORT = 0;
     VALORT2 = 0;
     SELECT SUM(PP_DINHEIRO)
     FROM PAG_PGM, PAGAMENTOS, FATURAMENTO2, COMPRAS
     WHERE PP_PAG = PAG_CODIGO AND PAG_FAT2 = FAT2_CODIGO AND COM_FAT2 = FAT2_CODIGO
     AND (PAG_SITUACAO >= 0 AND PAG_SITUACAO < 3) AND PP_DATAPGM = COM_DATA AND COM_DATAC = '01/01/1900' AND COM_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VALORT;
     if (VALORT IS NULL) then
      VALORT = 0;

     SELECT SUM(CE_VALOR)
     FROM COM_EST, COMPRAS
     WHERE CE_COM = COM_CODIGO AND COM_DATAC = '01/01/1900' AND COM_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VALORT2;
     if (VALORT2 IS NULL) then
      VALORT2 = 0;
     
     if (VALORT2 <> 0) then
      CompraV_CompraP  = (VALORT/VALORT2)*100;
     else CompraV_CompraP = 0;

     VALORT = 0;
     VALORT2 = 0;
     SELECT SUM(DGE_371), SUM(DGE_372)
     FROM DGE
     WHERE DGE_DATAI >= :DATA1 AND DGE_DATAF <= :DATA2
     INTO :VALORT, :VALORT2;
     if (VALORT IS NULL) then
      VALORT = 0;
     if (VALORT2 IS NULL) then
      VALORT2 = 0;
     
     if (VALORT2 <> 0) then
      DespesaF_ReceitaF = (VALORT/-VALORT2)*100;
     else DespesaF_ReceitaF = 0;

     SELECT SUM(PP_DINHEIRO)
     FROM PAG_PGM
     WHERE PP_DATAPGM BETWEEN :DATA1 AND :DATA2
     INTO :VALORT;
     if (VALORT IS NULL) then
      VALORT = 0;
     
     SELECT SUM(CE_VALOR)
     FROM COM_EST, COMPRAS
     WHERE CE_COM = COM_CODIGO AND COM_DATAC = '01/01/1900' AND COM_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VALORT2;
     if (VALORT2 IS NULL) then
      VALORT2 = 0;
     
     if (VALORT2 <> 0) then
      PagamentoT_Compra = (VALORT/VALORT2)*100;
     else PagamentoT_Compra = 0;

     VALORT = 0;
     VALORT2 = 0;
     SELECT SUM(MOV_CREDITO)
     FROM MOVIMENTACOES
     WHERE MOV_PLANO LIKE '1%' AND MOV_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VALOR;
     if (VALOR IS NULL) then
      VALOR = 0;
     
     SELECT SUM(MOV_DEBITO)
     FROM MOVIMENTACOES
     WHERE MOV_PLANO LIKE '4%' AND MOV_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VALOR2;
     if (VALOR2 IS NULL) then
      VALOR2 = 0;
     
     SELECT SUM(MOV_DEBITO)
     FROM MOVIMENTACOES
     WHERE MOV_PLANO LIKE '2%' AND MOV_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VALORT;
     if (VALORT IS NULL) then
      VALORT = 0;
     
     SELECT SUM(MOV_CREDITO)
     FROM MOVIMENTACOES
     WHERE MOV_PLANO LIKE '3%' AND MOV_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VALORT2;
     if (VALORT2 IS NULL) then
      VALORT2 = 0;
     
     if ((VALORT-VALORT2) <> 0) then
      Receita_Despesa = ((VALOR-VALOR2)/(VALORT-VALORT2))*100;
     else Receita_Despesa = 0;

     SELECT SUM(RP_DINHEIRO)
     FROM REC_PGM
     WHERE RP_DATAPGM BETWEEN :DATA1 AND :DATA2
     INTO :VALORT;
     if (VALORT IS NULL) then
      VALORT = 0;
     
     SELECT SUM(VE_VALOR)
     FROM VEN_EST, VENDAS
     WHERE VE_VEN = VEN_CODIGO AND VEN_DATAC = '01/01/1900' AND VEN_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VALORT2;
     if (VALORT2 IS NULL) then
      VALORT2 = 0;
     
     if (VALORT2 <> 0) then
      RecebimentoT_Venda = (VALORT/VALORT2)*100;
     else RecebimentoT_Venda = 0;

END^


ALTER PROCEDURE CALCULA_INDICE (
    DATA1 DATE,
    DATA2 DATE,
    DIAS INTEGER,
    MESES INTEGER)
RETURNS (
    TRI FLOAT,
    PMR INTEGER,
    PMP INTEGER,
    RL FLOAT,
    II FLOAT)
AS
declare variable total_venda float;
declare variable venda float;
declare variable juros float;
declare variable descontos float;
declare variable lucro float;
declare variable cai float;
declare variable receber float;
declare variable banco float;
declare variable est float;
declare variable imobilizado float;
declare variable depreciacao float;
declare variable inadimplencia float;
declare variable ativoi float;
declare variable ativof float;
declare variable im float;
declare variable mll float;
declare variable ri float;
declare variable dinheiro float;
declare variable cheque float;
declare variable prazo float;
declare variable compra float;
declare variable total_compra float;
declare variable soma_dre float;
declare variable credito float;
declare variable cancelamento float;
declare variable valor_prazo float;
declare variable valor_pago float;
declare variable recebido float;
declare variable cod_ordena integer;
declare variable saldoa float;
declare variable saldoatual float;
declare variable dlucro float;
declare variable atrasado float;
declare variable atrasado2 float;
declare variable reinvestimento float;
begin
     SELECT BP_CAIXA, BP_RECEBER, BP_SALDOB, BP_ESTOQUE, BP_IMOBILIZADO, BP_DEPRECIACAO, BP_INADIMPLENCIA FROM BAL_PAT
     WHERE BP_DATAI = :DATA1
     INTO :CAI, :RECEBER, :BANCO, :EST, :IMOBILIZADO, :DEPRECIACAO, :INADIMPLENCIA;
     if (:BANCO > 0) then
      ATIVOI = CAI + RECEBER + BANCO + EST + IMOBILIZADO - DEPRECIACAO - INADIMPLENCIA;
     else ATIVOI = CAI + RECEBER + EST + IMOBILIZADO - DEPRECIACAO - INADIMPLENCIA;
     SELECT BP_CAIXA, BP_RECEBER, BP_SALDOB, BP_ESTOQUE, BP_IMOBILIZADO, BP_DEPRECIACAO, BP_INADIMPLENCIA FROM BAL_PAT
     WHERE BP_DATAF = :DATA2
     INTO :CAI, :RECEBER, :BANCO, :EST, :IMOBILIZADO, :DEPRECIACAO, :INADIMPLENCIA;
     if (:BANCO > 0) then
      ATIVOF = CAI + RECEBER + BANCO + EST + IMOBILIZADO - DEPRECIACAO - INADIMPLENCIA;
     else ATIVOF = CAI + RECEBER + EST + IMOBILIZADO - DEPRECIACAO - INADIMPLENCIA;
     if ((ATIVOI > 0) AND (ATIVOF > 0)) then
     begin
      IM = (ATIVOI+ATIVOF)/2;
     end
     SELECT SUM(VE.VE_VALOR), SUM(VE.VE_LUCRO) FROM VENDAS V, VEN_EST VE WHERE V.VEN_CODIGO = VE.VE_VEN AND V.VEN_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VENDA, :LUCRO;
     SELECT SUM(R.REC_JUROS), SUM(R.REC_DESCONTOS) FROM RECEBIMENTOS R, FATURAMENTOS F, VENDAS V
     WHERE V.VEN_CODIGO = F.FAT_DESCRICAO AND F.FAT_TIPO = 1 AND R.REC_FAT = F.FAT_CODIGO AND V.VEN_DATA BETWEEN :DATA1 AND :DATA2
     INTO :JUROS, :DESCONTOS;
     if (:VENDA IS NULL) then
      VENDA = 0;
     if (:JUROS IS NULL) then
      JUROS = 0;
     if (:DESCONTOS IS NULL) then
      DESCONTOS = 0;
     TOTAL_VENDA = VENDA + JUROS - DESCONTOS;
     RI = TOTAL_VENDA/IM;
     MLL = LUCRO/TOTAL_VENDA;
     TRI = (MLL*RI)*100;
     if (TRI IS NULL) then
      TRI = 0;
     SELECT SUM(VE.VE_VALOR)
     FROM VEN_EST VE, VENDAS V, FATURAMENTOS F
     WHERE VE.VE_CODIGO = V.VEN_CODIGO AND V.VEN_CODIGO = F.FAT_DESCRICAO AND F.FAT_TIPO = 1 AND F.FAT_TIPOPGM = 1
     AND V.VEN_DATA BETWEEN :DATA1 AND :DATA2
     INTO :DINHEIRO;
     if (TOTAL_VENDA IS NULL) then
      TOTAL_VENDA = 0;
     if (DINHEIRO IS NULL) then
      DINHEIRO = 0;
     PRAZO = TOTAL_VENDA - DINHEIRO;
     if (MESES > 0) then
      PMR = (PRAZO/(TOTAL_VENDA/DIAS))/MESES;
     else PMR = 0;

     SELECT SUM(CE.CE_VALOR) FROM COMPRAS C, COM_EST CE WHERE C.COM_CODIGO = CE.CE_COM AND C.COM_DATA BETWEEN :DATA1 AND :DATA2
     INTO :COMPRA;
     SELECT SUM(P.PAG_JUROS), SUM(P.PAG_DESCONTOS) FROM PAGAMENTOS P, FATURAMENTO2 F, COMPRAS C
     WHERE C.COM_CODIGO = F.FAT2_DESCRICAO AND F.FAT2_TIPO = 1 AND P.PAG_FAT2 = F.FAT2_CODIGO AND C.COM_DATA BETWEEN :DATA1 AND :DATA2
     INTO :JUROS, :DESCONTOS;
     if (:VENDA IS NULL) then
      VENDA = 0;
     if (:JUROS IS NULL) then
      JUROS = 0;
     if (:DESCONTOS IS NULL) then
      DESCONTOS = 0;
     TOTAL_COMPRA = COMPRA + JUROS - DESCONTOS;
     
     SELECT SUM(CE.CE_VALOR)
     FROM COM_EST CE, COMPRAS C, FATURAMENTO2 F
     WHERE CE.CE_COM = C.COM_CODIGO AND C.COM_CODIGO = F.FAT2_DESCRICAO AND F.FAT2_TIPO = 1 AND F.FAT2_TIPOPGM = 1
     AND C.COM_DATA BETWEEN :DATA1 AND :DATA2
     INTO :DINHEIRO;
     if (TOTAL_COMPRA IS NULL) then
      TOTAL_COMPRA = 0;
     if (DINHEIRO IS NULL) then
      DINHEIRO = 0;
     PRAZO = TOTAL_COMPRA - DINHEIRO;
     if (MESES > 0 ) then
      PMP = (PRAZO/(TOTAL_COMPRA/DIAS))/MESES;
     else PMP = 0;

     SELECT SUM(BP_DRE), SUM(BP_DLUCRO), SUM(BP_REINVESTIMENTO)
     FROM BAL_PAT
     WHERE BP_DATAI >= :DATA1 AND BP_DATAF <= :DATA2
     INTO :SOMA_DRE, :DLUCRO, :REINVESTIMENTO;

     SELECT MAX(MOV_ORDENA)
     FROM MOVIMENTACOES
     WHERE MOV_DATA < :DATA1
     INTO :COD_ORDENA;
     if (:COD_ORDENA = 0) then
      COD_ORDENA = -1;

     SELECT SUM(MOV_CREDITO-MOV_DEBITO+MOV_SALDOANT)
     FROM MOVIMENTACOES
     WHERE MOV_ORDENA = :COD_ORDENA
     INTO :SALDOA;

     SELECT MAX(MOV_ORDENA)
     FROM MOVIMENTACOES
     WHERE MOV_DATA = :DATA2
     INTO :COD_ORDENA;
     if (:COD_ORDENA = 0) then
      COD_ORDENA = -1;

     SELECT SUM(MOV_CREDITO-MOV_DEBITO+MOV_SALDOANT)
     FROM MOVIMENTACOES
     WHERE MOV_ORDENA = :COD_ORDENA
     INTO :SALDOATUAL;
     if (:SOMA_DRE IS NULL) then
      SOMA_DRE = 0;
     if (:SALDOA IS NULL) then
      SALDOA = 0;
     if (:SALDOATUAL IS NULL) then
      SALDOATUAL = 0;
     if (:DLUCRO IS NULL) then
      DLUCRO = 0;
     RL = ((:SALDOATUAL-:SALDOA+:DLUCRO+:REINVESTIMENTO)/(SOMA_DRE))*100;

     SELECT SUM(VE_VALOR)
     FROM VENDAS, FATURAMENTOS, VEN_EST
     WHERE FAT_DESCRICAO = VEN_CODIGO AND VEN_CODIGO = VE_VEN AND FAT_TIPOPGM = 3
     AND VEN_DATAC = '01/01/1900' AND FAT_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VALOR_PRAZO;

     SELECT SUM(REC_VALOR+REC_JUROS-REC_DESCONTOS)
     FROM RECEBIMENTOS, FATURAMENTOS
     WHERE FAT_CODIGO = REC_FAT AND FAT_TIPOPGM = 3 AND REC_ESTADO < 3 AND
     ((REC_VENCIMENTO+50) < :DATA2)  AND FAT_DATA BETWEEN :DATA1 AND :DATA2
     INTO :ATRASADO;

     SELECT SUM(REC_VALOR+REC_JUROS-REC_DESCONTOS)
     FROM RECEBIMENTOS, FATURAMENTOS, REC_PGM
     WHERE REC_CODIGO = RP_REC AND FAT_CODIGO = REC_FAT AND FAT_TIPOPGM = 2 AND
     ((REC_VENCIMENTO+50) < :DATA2) AND FAT_DATA BETWEEN :DATA1 AND :DATA2
     INTO :ATRASADO2;

     SELECT SUM(RP_DINHEIRO+RP_CHEQUE)
     FROM RECEBIMENTOS, FATURAMENTOS, REC_PGM
     WHERE REC_CODIGO = RP_REC AND FAT_CODIGO = REC_FAT AND FAT_TIPOPGM = 2 AND
     ((REC_VENCIMENTO+50) < :DATA2) AND FAT_DATA BETWEEN :DATA1 AND :DATA2
     INTO :RECEBIDO;

     if (:VALOR_PRAZO IS NULL) then
      VALOR_PRAZO = 0;
     if (:ATRASADO IS NULL) then
      ATRASADO = 0;
     if (:ATRASADO2 IS NULL) then
      ATRASADO2 = 0;
     if (:RECEBIDO IS NULL) then
      RECEBIDO = 0;
     II = (((:ATRASADO+:ATRASADO2)-:RECEBIDO)/(VALOR_PRAZO))*100;
  suspend;
end^


ALTER PROCEDURE CALCULA_LUCRO (
    CAIXA INTEGER)
RETURNS (
    LUCRO FLOAT)
AS
DECLARE VARIABLE DINHEIRO FLOAT;
DECLARE VARIABLE CHEQUE FLOAT;
DECLARE VARIABLE REC INTEGER;
DECLARE VARIABLE VALOR FLOAT;
DECLARE VARIABLE JUROS FLOAT;
DECLARE VARIABLE DESCONTOS FLOAT;
DECLARE VARIABLE VALORL FLOAT;
BEGIN
     LUCRO = 0;
     FOR SELECT RP.RP_DINHEIRO, RP.RP_CHEQUE, RP.RP_REC, R.REC_VALOR, R.REC_JUROS, R.REC_DESCONTOS FROM RECEBIMENTOS R, REC_PGM RP
     WHERE R.REC_CODIGO = RP.RP_REC AND RP.RP_CAI = :CAIXA
     INTO :DINHEIRO, :CHEQUE, :REC, :VALOR, :JUROS, :DESCONTOS DO
     BEGIN
          FOR SELECT VE.VE_LUCRO FROM VENDAS V, VEN_EST VE, FATURAMENTOS F, RECEBIMENTOS R
          WHERE V.VEN_CODIGO = VE.VE_VEN AND F.FAT_TIPO = 1 AND F.FAT_DESCRICAO = V.VEN_CODIGO AND F.FAT_CODIGO = R.REC_FAT AND R.REC_CODIGO = :REC
          INTO :VALORL DO
          BEGIN
               if (VALORL IS NULL) then
                VALORL = 0;
               LUCRO = :LUCRO + :VALORL;
          END
     END
END^


ALTER PROCEDURE CALCULA_REC_FLUXO (
    DATA1 DATE,
    DATA2 DATE)
RETURNS (
    TOTAL_VALOR NUMERIC(9,2),
    TOTAL_VALOR_REC NUMERIC(9,2))
AS
declare variable codigo integer;
declare variable valor float;
declare variable valor_rec float;
begin
  /* Procedure Text */
  TOTAL_VALOR = 0;
  TOTAL_VALOR_REC = 0;
  FOR SELECT DISTINCT(REC_CODIGO), REC_VALOR
  FROM RECEBIMENTOS, FATURAMENTOS, VENDAS
  WHERE VEN_FAT = FAT_CODIGO AND FAT_CODIGO = REC_FAT AND REC_VENCIMENTO > VEN_DATA AND REC_VENCIMENTO BETWEEN :DATA1 AND :DATA2
  INTO :CODIGO, :VALOR DO
  BEGIN
    if (CODIGO IS NULL) then
     CODIGO = 0;
    if (VALOR IS NULL) then
     VALOR = 0;
    SELECT SUM(RP_DINHEIRO) FROM REC_PGM
    WHERE RP_REC = :CODIGO AND RP_DATAPGM BETWEEN :DATA1 AND :DATA2
    INTO :VALOR_REC;
    if (VALOR_REC IS NULL) then
     VALOR_REC = 0;
    TOTAL_VALOR_REC = TOTAL_VALOR_REC + VALOR_REC;
    TOTAL_VALOR = TOTAL_VALOR + VALOR;
  END

  suspend;
end^


ALTER PROCEDURE CALCULA_REC_FLUXO2 (
    DATA1 DATE,
    DATA2 DATE)
RETURNS (
    TOTAL_VALOR NUMERIC(9,2),
    TOTAL_VALOR_REC NUMERIC(9,2))
AS
declare variable valor float;
declare variable valor_rec float;
begin
  /* Procedure Text */
  TOTAL_VALOR = 0;
  TOTAL_VALOR_REC = 0;
  SELECT SUM(RP_DINHEIRO)
  FROM RECEBIMENTOS, REC_PGM
  WHERE REC_CODIGO = RP_REC AND REC_VENCIMENTO < :DATA1 AND RP_DATAPGM BETWEEN :DATA1 AND :DATA2
  INTO :VALOR_REC;
  TOTAL_VALOR_REC = TOTAL_VALOR_REC + VALOR_REC;
  SELECT SUM(REC_VALOR)
  FROM RECEBIMENTOS, REC_PGM
  WHERE REC_CODIGO = RP_REC AND REC_VENCIMENTO < :DATA1 AND RP_DATAPGM >= :DATA1
  INTO :VALOR;
  TOTAL_VALOR = TOTAL_VALOR + VALOR;
  suspend;
end^


ALTER PROCEDURE CALCULA_REC_VENDA (
    DATA1 DATE,
    DATA2 DATE)
RETURNS (
    REC_VENDA NUMERIC(9,2))
AS
declare variable codigo integer;
declare variable valor float;
declare variable valor_rec float;
declare variable RECEBIDO float;
declare variable VENDA float;
begin
  /* Procedure Text */
  REC_VENDA = 0;
  RECEBIDO = 0;
  VENDA = 0;
  FOR SELECT SUM(VE_VALOR), FAT_CODIGO
  FROM VENDAS, VEN_EST, FATURAMENTOS
  WHERE VEN_FAT = FAT_CODIGO AND VE_VEN = VEN_CODIGO AND VEN_DATAC = '01/01/1900'
  AND VEN_DATA BETWEEN :DATA1 AND :DATA2
  GROUP BY FAT_CODIGO
  INTO :VALOR, :CODIGO DO
  BEGIN
    if (CODIGO IS NULL) then
     CODIGO = 0;
    if (VALOR IS NULL) then
     VALOR = 0;
    VENDA = VENDA + VALOR;
    SELECT SUM(RP_DINHEIRO) FROM REC_PGM, RECEBIMENTOS
    WHERE RP_REC = REC_CODIGO AND REC_FAT = :CODIGO AND RP_DATAPGM BETWEEN :DATA1 AND :DATA2
    INTO :VALOR_REC;
    if (VALOR_REC IS NULL) then
     VALOR_REC = 0;
    RECEBIDO = RECEBIDO + VALOR_REC;
  END
  REC_VENDA = RECEBIDO/VENDA;

  suspend;
end^


ALTER PROCEDURE CANCELA_NOTA_FISCAL (
    CODIGO INTEGER,
    DATA DATE)
AS
DECLARE VARIABLE PRODUTO INTEGER;
DECLARE VARIABLE QUANTIDADE FLOAT;
DECLARE VARIABLE QUANTIDADEA FLOAT;
DECLARE VARIABLE VALORC FLOAT;
DECLARE VARIABLE VALORCM FLOAT;
DECLARE VARIABLE VALORV FLOAT;
DECLARE VARIABLE OPERACAO CHAR(1);
DECLARE VARIABLE AJ_ESTOQUE CHAR(1);
DECLARE VARIABLE CLI_FOR VARCHAR(50);
BEGIN
    SELECT CFO_AJUSTAR_ESTOQUE, CFO_OPERACAO FROM CFOP, NOTAS_FISCAIS
    WHERE NOT_CFOP = CFO_CFOP AND NOT_CODIGO = :CODIGO
    INTO :AJ_ESTOQUE, :OPERACAO;
    IF(:AJ_ESTOQUE = 'S') THEN
    BEGIN
      /*busco cliente/fornecedor*/
      SELECT CF_NOME FROM NOTAS_FISCAIS INNER JOIN CLIENTES_FORNECEDORES ON NOT_CF = CF_CODIGO AND 
NOT_CODIGO = :CODIGO
      INTO :CLI_FOR;
      IF(:OPERACAO = 'E') THEN
      BEGIN
        FOR SELECT NI_PRO, NI_QUANTIDADE*COALESCE(NI_MULTIPLICADOR, 1) FROM NOT_ITENS WHERE NI_NOT = 
:CODIGO
        INTO :PRODUTO, :QUANTIDADE DO
        BEGIN
          /*busco a quantidade anterior*/
          SELECT PRO_QUANTIDADE, PRO_VALORC, PRO_VALORCM, PRO_VALORV FROM PRODUTOS WHERE PRO_CODIGO = 
:PRODUTO
          INTO :QUANTIDADEA, :VALORC, :VALORCM, :VALORV;
          /*insere historico*/
          INSERT INTO HIS_PRO (HP_CODIGO, HP_DATA, HP_PRO, HP_ORIGEM, HP_DOC, HP_QUANTIDADE, 
HP_VALORC, HP_VALORV, HP_VALORCM, HP_VALOROP, 
HP_VALORM, HP_TIPO, HP_TIPO2, HP_QUANTIDADEA)
          VALUES(GEN_ID(GEN_HP, 1), CURRENT_DATE, :PRODUTO, LEFT('Canc. NF - '||:CLI_FOR, 30), 
:CODIGO, :QUANTIDADE, :VALORC*:QUANTIDADE,
          :VALORV*:QUANTIDADE, :VALORCM*:QUANTIDADE, 0, 0, 'S', 7, :QUANTIDADEA);
          /*atualiza o estoque*/
          UPDATE PRODUTOS SET PRO_QUANTIDADE = PRO_QUANTIDADE - :QUANTIDADE
          WHERE PRO_CODIGO = :PRODUTO;
        END
      END ELSE
      BEGIN
        FOR SELECT NI_PRO, NI_QUANTIDADE*COALESCE(NI_MULTIPLICADOR, 1) FROM NOT_ITENS WHERE NI_NOT = 
:CODIGO
        INTO :PRODUTO, :QUANTIDADE DO
        BEGIN
          /*busco a quantidade anterior*/
          SELECT PRO_QUANTIDADE, PRO_VALORC, PRO_VALORCM, PRO_VALORV FROM PRODUTOS WHERE PRO_CODIGO = 
:PRODUTO
          INTO :QUANTIDADEA, :VALORC, :VALORCM, :VALORV;
          /*insere historico*/
          INSERT INTO HIS_PRO (HP_CODIGO, HP_DATA, HP_PRO, HP_ORIGEM, HP_DOC, HP_QUANTIDADE, 
HP_VALORC, HP_VALORV, HP_VALORCM, HP_VALOROP, 
HP_VALORM, HP_TIPO, HP_TIPO2, HP_QUANTIDADEA)
          VALUES(GEN_ID(GEN_HP, 1), CURRENT_DATE, :PRODUTO, LEFT('Canc. NF - '||:CLI_FOR, 30), 
:CODIGO, :QUANTIDADE, :VALORC*:QUANTIDADE,
          :VALORV*:QUANTIDADE, :VALORCM*:QUANTIDADE, 0, 0, 'E', 7, :QUANTIDADEA);
          /*atualiza o estoque*/
          UPDATE PRODUTOS SET PRO_QUANTIDADE = PRO_QUANTIDADE + :QUANTIDADE
          WHERE PRO_CODIGO = :PRODUTO;
        END
      END
    END
    UPDATE NOTAS_FISCAIS SET NOT_DATAC = :DATA WHERE NOT_CODIGO = :CODIGO;
END^


ALTER PROCEDURE CANCELA_PAGAMENTO (
    COD_PAG_PGM INTEGER)
AS
DECLARE VARIABLE COD_PAG INTEGER;
DECLARE VARIABLE JUROS NUMERIC(9,2);
DECLARE VARIABLE DESCONTOS NUMERIC(9,2);
DECLARE VARIABLE ESTADO SMALLINT;
DECLARE VARIABLE COD_PAG_PGM2 INTEGER;
BEGIN
    /*PEGA OS DADOS DO PAGAMENTO*/
    SELECT PP_PAG, PP_JUROS, PP_DESCONTOS FROM PAG_PGM WHERE PP_CODIGO = :COD_PAG_PGM
    INTO :COD_PAG, :JUROS, :DESCONTOS;
    /*ATUALIZA O REGISTRO DE PAGAMENTO*/
    UPDATE PAGAMENTOS SET PAG_ESTADO = 1, PAG_JUROS = PAG_JUROS - :JUROS,
    PAG_DESCONTOS = PAG_DESCONTOS - :DESCONTOS
    WHERE PAG_CODIGO = :COD_PAG;
    /*DELETA O REGISTRO DE PAG_PGM E CRIA UM NOVO ABERTO*/
    DELETE FROM PAG_PGM WHERE PP_CODIGO = :COD_PAG_PGM;
    SELECT PP_CODIGO FROM PAG_PGM WHERE PP_PAG = :COD_PAG AND PP_DATAPGM IS NULL
    INTO :COD_PAG_PGM2;
    IF(:COD_PAG_PGM2 IS NULL) THEN
    BEGIN
      INSERT INTO PAG_PGM(PP_CODIGO, PP_DINHEIRO, PP_CHEQUE, PP_PAG)
      VALUES(GEN_ID(GEN_PP, 1), 0, 0, :COD_PAG);
    END
END^


ALTER PROCEDURE CANCELA_RECEBIMENTO (
    COD_REC_PGM INTEGER)
AS
DECLARE VARIABLE COD_REC INTEGER;
DECLARE VARIABLE JUROS NUMERIC(9,2);
DECLARE VARIABLE DESCONTOS NUMERIC(9,2);
DECLARE VARIABLE ULTREC DATE;
DECLARE VARIABLE ESTADO SMALLINT;
DECLARE VARIABLE COD_REC_PGM2 INTEGER;
BEGIN
    /*PEGA OS DADOS DO RECEBIMENTO*/
    SELECT RP_REC, RP_JUROS, RP_DESCONTOS FROM REC_PGM WHERE 
RP_CODIGO = :COD_REC_PGM
    INTO :COD_REC, :JUROS, :DESCONTOS;
    /*PEGA A DATA DO ULTIMO RECEBIMENTO DA PARCELA*/
    ULTREC = NULL;
    FOR SELECT RP_DATAPGM FROM REC_PGM WHERE RP_REC = :COD_REC AND 
RP_CODIGO <> :COD_REC_PGM ORDER BY RP_DATAPGM
    INTO :ULTREC DO
    BEGIN ESTADO = 2; END
    IF(:ULTREC IS NULL) THEN
    BEGIN
      SELECT REC_VENCIMENTO FROM RECEBIMENTOS WHERE REC_CODIGO = 
:COD_REC INTO :ULTREC;
      ESTADO = 1;
    END
    /*ATUALIZA O REGISTRO DE RECEBIMENTO*/
    UPDATE RECEBIMENTOS SET REC_ESTADO = :ESTADO, REC_JUROS = 
REC_JUROS - :JUROS,
    REC_DESCONTOS = REC_DESCONTOS - :DESCONTOS, REC_DATAR = :ULTREC
    WHERE REC_CODIGO = :COD_REC;
    /*DELETA O REGISTRO DE REC_PGM E CRIA UM NOVO ABERTO*/
    DELETE FROM REC_PGM WHERE RP_CODIGO = :COD_REC_PGM;
    SELECT RP_CODIGO FROM REC_PGM WHERE RP_REC = :COD_REC AND 
RP_DATAPGM IS NULL
    INTO :COD_REC_PGM2;
    IF(:COD_REC_PGM2 IS NULL) THEN
    BEGIN
      INSERT INTO REC_PGM(RP_CODIGO, RP_DINHEIRO, RP_CHEQUE, 
RP_REC)
      VALUES(GEN_ID(GEN_RR, 1), 0, 0, :COD_REC);
    END
END^


ALTER PROCEDURE CANCELA_RECEITA (
    FATURA INTEGER,
    DATA DATE,
    CODIGO INTEGER)
AS
DECLARE VARIABLE RECEBIMENTO INTEGER;
DECLARE VARIABLE JUROS FLOAT;
DECLARE VARIABLE DESCONTOS FLOAT;
DECLARE VARIABLE ESTADO INTEGER;
DECLARE VARIABLE VALORJ FLOAT;
DECLARE VARIABLE VALORD FLOAT;
BEGIN
     VALORJ = 0;
     VALORD = 0;
     FOR SELECT REC_CODIGO, REC_ESTADO, REC_JUROS, REC_DESCONTOS FROM RECEBIMENTOS WHERE REC_FAT = :FATURA
     INTO :RECEBIMENTO, :ESTADO, :JUROS, :DESCONTOS DO
     BEGIN
      IF (JUROS IS NULL) THEN
       JUROS = 0;
      IF (DESCONTOS IS NULL) THEN
       DESCONTOS = 0;
      IF (ESTADO = 2) THEN
      BEGIN
        VALORJ = VALORJ + JUROS;
        VALORD = VALORD + DESCONTOS;
      END
      --DELETE FROM REC_PGM WHERE RP_REC = :RECEBIMENTO;
      --DELETE FROM RECEBIMENTOS WHERE REC_CODIGO = :RECEBIMENTO;
      --ATUALIZA A SITUACAO PARA 4 = CANCELADO
      UPDATE RECEBIMENTOS SET REC_SITUACAO = 4 WHERE REC_CODIGO = :RECEBIMENTO;
     END
     UPDATE BAL_PAT SET BP_AJUSTE = BP_AJUSTE + (:VALORD-:VALORJ) WHERE BP_CODIGO = :CODIGO;
END^


ALTER PROCEDURE CANCELAMENTOS (
    MES INTEGER,
    ANO INTEGER,
    DATA DATE)
RETURNS (
    VENDAC FLOAT,
    COMPRAC FLOAT,
    DESPESAC FLOAT,
    TRIBUTACAOC FLOAT,
    FRETEC FLOAT)
AS
DECLARE VARIABLE VALOR FLOAT;
DECLARE VARIABLE VALORF FLOAT;
DECLARE VARIABLE VALORD FLOAT;
BEGIN
     VENDAC = 0;
     COMPRAC = 0;
     DESPESAC = 0;
     TRIBUTACAOC =0;
     FRETEC = 0;
     
     SELECT SUM(VE.VE_VALOR), SUM(VE.VE_VALORF), SUM(VE_DIFERENCA)
     FROM VENDAS V, VEN_EST VE
     WHERE EXTRACT(MONTH FROM V.VEN_DATAC) = :MES
     AND EXTRACT(YEAR FROM V.VEN_DATAC) = :ANO AND VE.VE_VEN = V.VEN_CODIGO
     INTO :VALOR, :VALORF, :VALORD;
     
     if (:VALOR IS  NULL) then
      VALOR = 0;
     if (:VALORF IS  NULL) then
      VALORF = 0;
     if (:VALORD IS  NULL) then
      VALORD = 0;
     
     VENDAC = (VALOR + VALORD) - VALORF;

     SELECT SUM(CUST_VALOR)
     FROM CUSTOS
     WHERE EXTRACT(MONTH FROM CUST_DATAC) = :MES
     AND EXTRACT(YEAR FROM CUST_DATAC) = :ANO
     INTO :VALOR;
     if (:VALOR IS  NULL) then
      VALOR = 0;
     
     DESPESAC = VALOR;
     
     SELECT SUM(TRI_VALOR)
     FROM TRIBUTACOES
     WHERE EXTRACT(MONTH FROM TRI_DATAC) = :MES
     AND EXTRACT(YEAR FROM TRI_DATAC) = :ANO
     INTO :VALOR;
     if (:VALOR IS  NULL) then
      VALOR = 0;
     
     TRIBUTACAOC = VALOR;
      
     SELECT SUM(FRE_VALOR)
     FROM FRETES
     WHERE EXTRACT(MONTH FROM FRE_DATAC) = :MES
     AND EXTRACT(YEAR FROM FRE_DATAC) = :ANO
     INTO :VALOR;
     if (:VALOR IS  NULL) then
      VALOR = 0;
     
     FRETEC = VALOR;
     
END^


ALTER PROCEDURE CHEQUE_ORIGEM (
    ORIGEM INTEGER,
    DESTINO INTEGER,
    DESCRICAOO INTEGER,
    DESCRICAOD INTEGER)
RETURNS (
    NOMEO VARCHAR(50),
    NOMED VARCHAR(50),
    FORMAO VARCHAR(20),
    FORMAD VARCHAR(20))
AS
BEGIN
     IF (:ORIGEM <> 5) THEN
     BEGIN
      SELECT CLI_NOME FROM CLIENTES WHERE CLI_CODIGO = :DESCRICAOO
      INTO :NOMEO;
      IF (:ORIGEM = 1) THEN
      BEGIN
       FORMAO = 'VENDA';
      END
      IF (:ORIGEM = 2) THEN
      BEGIN
       FORMAO = 'SERVICO';
      END
      IF (:ORIGEM = 3) THEN
      BEGIN
       FORMAO = 'LOCACAO';
      END
      IF (:ORIGEM = 4) THEN
      BEGIN
       FORMAO = 'RECEBIMENTO';
      END
     END
     IF (:ORIGEM = 5) THEN
     BEGIN
      SELECT CON_DESCRICAO FROM CONTAS WHERE CON_CODIGO = :DESCRICAOO
      INTO :NOMEO;
      FORMAO = 'BANCO';
     END
     IF (:DESTINO = 1) THEN
     BEGIN
      SELECT CAI_CODIGO FROM CAIXA WHERE CAI_CODIGO = :DESCRICAOD
      INTO :NOMED;
      FORMAD = 'CAIXA';
     END
     IF (:DESTINO = 2) THEN
     BEGIN
      SELECT CON_DESCRICAO FROM CONTAS WHERE CON_CODIGO = :DESCRICAOD
      INTO :NOMED;
      FORMAD = 'BANCO';
     END
     IF (:DESTINO = 3) THEN
     BEGIN
      SELECT FOR_NOME FROM FORNECEDORES WHERE FOR_CODIGO = :DESCRICAOD
      INTO :NOMED;
      FORMAD = 'COMPRA';
     END
     IF (:DESTINO = 4) THEN
     BEGIN
      SELECT SUD_NOME FROM SUB_DES WHERE SUD_CODIGO = :DESCRICAOD
      INTO :NOMED;
      FORMAD = 'DESPESA';
     END
     IF (:DESTINO = 5) THEN
     BEGIN
      SELECT IMP_NOME FROM IMPOSTOS WHERE IMP_CODIGO = :DESCRICAOD
      INTO :NOMED;
      FORMAD = 'TRIBUTACAO';
     END
     IF (:DESTINO = 6) THEN
     BEGIN
      SELECT TRA_CODIGO FROM TRANSPORTADORAS WHERE TRA_CODIGO = :DESCRICAOD
      INTO :NOMED;
      FORMAD = 'FRETE';
     END
     IF (:DESTINO = 7) THEN
     BEGIN
      SELECT F.FUN_NOME FROM FUNCIONARIOS F, FOLHA_PAGAMENTOS FO WHERE
      F.FUN_CODIGO = FO.FOL_FUN AND FO.FOL_CODIGO = :DESCRICAOD
      INTO :NOMED;
      FORMAD = 'FOLHA';
     END
END^


