ALTER PROCEDURE CREDITA_CONTA (
    DATA DATE,
    COD_REC INTEGER,
    COD_CONTA INTEGER,
    VALOR FLOAT,
    FUN INTEGER,
    HORA TIME,
    DINHEIRO FLOAT,
    CHEQUE FLOAT,
    DESCRICAO VARCHAR(30),
    VALORPG FLOAT)
AS
DECLARE VARIABLE COD_MOV INTEGER;
DECLARE VARIABLE SALDO FLOAT;
DECLARE VARIABLE COD_RR INTEGER;
DECLARE VARIABLE RR_COD INTEGER;
BEGIN
     SELECT CON_SALDO FROM CONTAS WHERE CON_CODIGO = :COD_CONTA
     INTO :SALDO;
     UPDATE CONTAS SET CON_SALDO = CON_SALDO + :VALORPG WHERE CON_CODIGO = :COD_CONTA;
     COD_MOV = GEN_ID(GEN_MOV, 1);
     SELECT RP_CODIGO FROM REC_PGM WHERE RP_DATAPGM IS NULL AND RP_REC = :COD_REC
     INTO :COD_RR;
     if (VALOR = VALORPG) then
     BEGIN
      UPDATE RECEBIMENTOS SET REC_ESTADO = 3 WHERE REC_CODIGO = :COD_REC;
      UPDATE REC_PGM SET RP_DATAPGM = :DATA, RP_DINHEIRO = :DINHEIRO, RP_CHEQUE = :CHEQUE, RP_FUN = :FUN, RP_MOV = :COD_MOV, RP_HORA = :HORA, RP_CAI = 0
      WHERE RP_CODIGO = :COD_RR;
     END
     ELSE IF (VALOR > VALORPG) THEN
     BEGIN
      UPDATE RECEBIMENTOS SET REC_ESTADO = 2 WHERE REC_CODIGO = :COD_REC;
      UPDATE REC_PGM SET RP_DATAPGM = :DATA, RP_DINHEIRO = :DINHEIRO, RP_CHEQUE = :CHEQUE, RP_FUN = :FUN, RP_MOV = :COD_MOV, RP_HORA = :HORA, RP_CAI = 0
      WHERE RP_CODIGO = :COD_RR;
      RR_COD = GEN_ID(GEN_RR, 1);
      INSERT INTO REC_PGM(RP_CODIGO, RP_REC, RP_DINHEIRO, RP_CHEQUE)
      VALUES(:RR_COD, :COD_REC, 0, 0);
     END
     INSERT INTO MOVIMENTACOES(MOV_CODIGO, MOV_DATA, MOV_DESCRICAO, MOV_CREDITO, MOV_DEBITO, MOV_SALDOANT, MOV_CON, MOV_TIPO)
     VALUES(:COD_MOV, :DATA, :DESCRICAO, :VALORPG, 0, :SALDO, :COD_CONTA, 12);

END^


ALTER PROCEDURE DADOS_CARTEIRA (
    COD_CLIENTE INTEGER,
    DATA DATE)
RETURNS (
    DATAU_COMPRA DATE,
    VALORU_COMPRA FLOAT,
    DATAM_COMPRA DATE,
    VALORM_COMPRA FLOAT,
    DATAU_RECEB DATE,
    VALORU_RECEB FLOAT,
    VALOR_DEVEDOR FLOAT,
    TOTAL_COMPRA FLOAT,
    TICKET_MEDIO FLOAT,
    FREQUENCIA FLOAT,
    COMPRA_ANO FLOAT)
AS
declare variable valor float;
declare variable n_venda integer;
declare variable codigo integer;
BEGIN
    SELECT VEN_DATA, VEN_VALOR FROM VENDAS WHERE VEN_CODIGO = (SELECT MAX(VEN_CODIGO)
    FROM VENDAS, FATURAMENTOS
    WHERE VEN_FAT = FAT_CODIGO AND VEN_DATAC = '01/01/1900' AND FAT_CLI = :COD_CLIENTE)
    INTO :datau_compra, :valoru_compra;

    SELECT MAX(VEN_CODIGO) FROM VENDAS WHERE VEN_VALOR = (SELECT MAX(VEN_VALOR)
    FROM VENDAS, FATURAMENTOS
    WHERE VEN_FAT = FAT_CODIGO AND VEN_DATAC = '01/01/1900' AND FAT_CLI = :COD_CLIENTE)
    INTO :codigo;

    SELECT VEN_DATA, VEN_VALOR FROM VENDAS WHERE VEN_CODIGO = :CODIGO
    INTO :datam_compra, :valorm_compra;

    SELECT MAX(RP_DATAPGM)
    FROM FATURAMENTOS, RECEBIMENTOS, REC_PGM
    WHERE FAT_CODIGO = REC_FAT AND REC_CODIGO = RP_REC AND FAT_CLI = :COD_CLIENTE
    INTO :datau_receb;

    SELECT SUM(RP_DINHEIRO)
    FROM FATURAMENTOS, RECEBIMENTOS, REC_PGM
    WHERE FAT_CODIGO = REC_FAT AND REC_CODIGO = RP_REC AND RP_DATAPGM = :datau_receb AND FAT_CLI = :COD_CLIENTE
    INTO :valoru_receb;

    SELECT (SUM(REC_VALOR + REC_JUROS - REC_DESCONTOS) - SUM(RP_DINHEIRO+RP_CHEQUE))
    FROM RECEBIMENTOS, FATURAMENTOS, REC_PGM
    WHERE FAT_CODIGO = REC_FAT AND REC_CODIGO = RP_REC AND REC_ESTADO < 3 AND (REC_SITUACAO >= 0 AND REC_SITUACAO <= 2)
    AND FAT_CLI = :COD_CLIENTE
    INTO :valor_devedor;

    SELECT SUM(VE_VALOR)
    FROM VENDAS, FATURAMENTOS, VEN_EST
    WHERE VEN_FAT = FAT_CODIGO AND VE_VEN = VEN_CODIGO AND VEN_DATAC = '01/01/1900' AND FAT_CLI = :COD_CLIENTE
    AND VEN_DATA BETWEEN (:DATA-1825) AND :DATA
    INTO :total_compra;
    
    ticket_medio = 0;
    SELECT SUM(VE_VALOR)
    FROM VENDAS, FATURAMENTOS, VEN_EST
    WHERE VEN_FAT = FAT_CODIGO AND VE_VEN = VEN_CODIGO AND VEN_DATAC = '01/01/1900' AND FAT_CLI = :COD_CLIENTE
    AND VEN_DATA BETWEEN (:DATA-365) AND :DATA
    INTO :valor;

    SELECT COUNT(VEN_CODIGO)
    FROM VENDAS, FATURAMENTOS
    WHERE VEN_FAT = FAT_CODIGO AND VEN_DATAC = '01/01/1900' AND FAT_CLI = :COD_CLIENTE
    AND VEN_DATA BETWEEN (:DATA-365) AND :DATA
    INTO :n_venda;

    if (n_venda is null) then
     n_venda = 0;
    if (n_venda > 0) then
     ticket_medio = valor/n_venda;

    frequencia = n_venda/12;
    compra_ano = total_compra/5;
END^


ALTER PROCEDURE DEBITA_CONTA (
    DATA DATE,
    COD_PAG INTEGER,
    COD_CONTA INTEGER,
    VALOR FLOAT,
    FUN INTEGER,
    HORA TIME,
    DINHEIRO FLOAT,
    CHEQUE FLOAT,
    DESCRICAO VARCHAR(30),
    VALORPG FLOAT,
    JUROS FLOAT,
    DESCONTOS FLOAT,
    COD_FIN FLOAT,
    DATAHORA TIMESTAMP,
    ESTADO VARCHAR(1),
    COD_MOV INTEGER)
AS
declare variable SALDO float;
declare variable COD_PP integer;
declare variable PP_COD integer;
declare variable COD_CAIXA integer;
declare variable X integer;
BEGIN
     SELECT PP_CODIGO FROM PAG_PGM WHERE PP_DATAPGM IS NULL AND PP_PAG = :COD_PAG
     INTO :COD_PP;
     if (VALOR = VALORPG) then
     BEGIN
      UPDATE PAGAMENTOS SET PAG_ESTADO = 3, PAG_JUROS = PAG_JUROS + :JUROS, PAG_DESCONTOS = PAG_DESCONTOS + :DESCONTOS WHERE PAG_CODIGO = 
:COD_PAG;
      SELECT COUNT(P.PAG_CODIGO) FROM PAGAMENTOS P, FATURAMENTO2 F WHERE P.PAG_FAT2 = F.FAT2_CODIGO AND F.FAT2_TIPO = 6 AND F.FAT2_DESCRICAO = 
:COD_FIN AND P.PAG_ESTADO <> 3
      INTO :X;
      if (X = 0) then
      BEGIN
           UPDATE FINANCIAMENTOS SET FIN_ESTADO = 2 WHERE FIN_CODIGO = :COD_FIN;
      END
      UPDATE PAG_PGM SET PP_DATAPGM = :DATA, PP_DINHEIRO = :DINHEIRO, PP_CHEQUE = :CHEQUE, PP_FUN = :FUN, PP_MOV = :COD_MOV, PP_HORA = :HORA, PP_CAI 
= :COD_CAIXA,
      PP_JUROS = :JUROS, PP_DESCONTOS = :DESCONTOS WHERE PP_CODIGO = :COD_PP;
     END
     ELSE IF (VALOR > VALORPG) THEN
     BEGIN
      UPDATE PAGAMENTOS SET PAG_ESTADO = 2, PAG_JUROS = PAG_JUROS + :JUROS, PAG_DESCONTOS = PAG_DESCONTOS + :DESCONTOS WHERE PAG_CODIGO = 
:COD_PAG;
      UPDATE PAG_PGM SET PP_DATAPGM = :DATA, PP_DINHEIRO = :DINHEIRO, PP_CHEQUE = :CHEQUE, PP_FUN = :FUN, PP_MOV = :COD_MOV, PP_HORA = :HORA, PP_CAI 
= :COD_CAIXA
      WHERE PP_CODIGO = :COD_PP;
      PP_COD = GEN_ID(GEN_PP, 1);
      INSERT INTO PAG_PGM(PP_CODIGO, PP_PAG, PP_DINHEIRO, PP_CHEQUE)
      VALUES(:PP_COD, :COD_PAG, 0, 0);
     END
     IF (COD_CONTA > 0) THEN
     BEGIN
       SELECT CON_SALDO FROM CONTAS WHERE CON_CODIGO = :COD_CONTA
       INTO :SALDO;
       UPDATE CONTAS SET CON_SALDO = :SALDO - :DINHEIRO
       WHERE CON_CODIGO = :COD_CONTA;
       INSERT INTO MOVIMENTACOES(MOV_CODIGO, MOV_DATA, MOV_DESCRICAO, MOV_CREDITO, MOV_DEBITO, MOV_SALDOANT, MOV_CON, MOV_TIPO, 
MOV_DATAHORA,
       MOV_ORDENA, MOV_PLANO, MOV_NOME, MOV_CAI, MOV_ESTADO, MOV_TROCO)
       VALUES(GEN_ID(GEN_MOV, 1), :DATA, :DESCRICAO, 0, :VALORPG, :SALDO, :COD_CONTA, 5, :DATAHORA, GEN_ID(GEN_MOV2, 1), '5.4', 'TRANSFERENCIA', :COD_CAIXA, 
:ESTADO, 0);
     END
END^


ALTER PROCEDURE DELETA_ADIANTAMENTO (
    FATURA2 INTEGER,
    DATA DATE)
AS
declare variable pagamento integer;
declare variable AF integer;
declare variable juros float;
declare variable descontos float;
declare variable estado integer;
declare variable valorj float;
declare variable valord float;
begin
     VALORJ = 0;
     VALORD = 0;
     FOR SELECT PAG_CODIGO, PAG_ESTADO, PAG_JUROS, PAG_DESCONTOS FROM PAGAMENTOS WHERE PAG_FAT2 = :FATURA2
     INTO :PAGAMENTO, :ESTADO, :JUROS, :DESCONTOS DO
     BEGIN
      if (JUROS IS NULL) then
       JUROS = 0;
      if (DESCONTOS IS NULL) then
       DESCONTOS = 0;
      IF (ESTADO = 2) THEN
      BEGIN
        VALORJ = VALORJ + JUROS;
        VALORD = VALORD + DESCONTOS;
      END
      DELETE FROM PAG_PGM WHERE PP_PAG = :PAGAMENTO;
      DELETE FROM PAGAMENTOS WHERE PAG_CODIGO = :PAGAMENTO;
     END
     
     FOR SELECT AF_CODIGO FROM ADIANTAMENTO_FOLHA WHERE AF_FAT2 = :FATURA2
     INTO :AF DO
     BEGIN
       UPDATE ADIANTAMENTO_FOLHA SET AF_DATAC = :DATA
       WHERE AF_CODIGO = :AF;
     END
  suspend;
end^


