ALTER PROCEDURE DELETA_COMPRA (
    FATURA2 INTEGER,
    DATA DATE,
    CODIGO INTEGER)
AS
DECLARE VARIABLE PAGAMENTO INTEGER;
DECLARE VARIABLE COMPRA INTEGER;
DECLARE VARIABLE JUROS FLOAT;
DECLARE VARIABLE DESCONTOS FLOAT;
DECLARE VARIABLE ESTADO INTEGER;
DECLARE VARIABLE VALORJ FLOAT;
DECLARE VARIABLE VALORD FLOAT;
BEGIN
    VALORJ = 0;
    VALORD = 0;
