ALTER PROCEDURE DELETA_PEDIDO_COMPRA (
    FATURA2 INTEGER,
    DATA DATE)
AS
declare variable compra integer;
declare variable produto integer;
declare variable quantidade float;
begin
     SELECT COM_CODIGO FROM COMPRAS WHERE COM_FAT2 = :FATURA2
     INTO :COMPRA;
     FOR SELECT CE_PRO, CE_QUANTIDADE FROM COM_EST WHERE CE_COM = :COMPRA
     INTO :PRODUTO, :QUANTIDADE DO
     begin
          UPDATE PRODUTOS SET PRO_QUANTIDADE = PRO_QUANTIDADE - :QUANTIDADE
          WHERE PRO_CODIGO = :PRODUTO;
     end
     UPDATE COMPRAS SET COM_DATAC = :DATA
     WHERE COM_CODIGO = :COMPRA;
  suspend;
end^


ALTER PROCEDURE DELETA_PEDIDO_VENDA (
    CODIGO INTEGER,
    DATA DATE)
AS
declare variable venda integer;
declare variable produto integer;
declare variable quantidade float;
declare variable cod_pf integer;
begin
     SELECT VEN_CODIGO FROM VENDAS WHERE VEN_FAT = :CODIGO
     INTO :VENDA;
     FOR SELECT VE_PRO, VE_QUANTIDADE FROM VEN_EST WHERE VE_VEN = :VENDA
     INTO :PRODUTO, :QUANTIDADE do
     BEGIN
          UPDATE PRODUTOS SET PRO_QUANTIDADE = PRO_QUANTIDADE + :QUANTIDADE
          WHERE PRO_CODIGO = :PRODUTO;
     END

     UPDATE VENDAS SET VEN_DATAC = :DATA, VEN_DEVOLUCAO_P = 'S' WHERE VEN_CODIGO = :VENDA;
     SELECT PF_CODIGO FROM PED_FAT WHERE PF_FAT = :CODIGO
     INTO :COD_PF;
     UPDATE PED_FAT SET PF_DATAC = :DATA WHERE PF_CODIGO = :COD_PF;
  suspend;
end^


