ALTER PROCEDURE DIFERENCA_CUSTOM (
    CODIGO INTEGER,
    CODVE INTEGER,
    CUSTOM FLOAT,
    QUANTIDADE FLOAT)
AS
DECLARE VARIABLE VALORCM FLOAT;
DECLARE VARIABLE DIFERENCA FLOAT;
BEGIN
     SELECT PRO_VALORCM FROM PRODUTOS WHERE PRO_CODIGO = :CODIGO
     INTO VALORCM;
     DIFERENCA = CAST(CUSTOM - (VALORCM*QUANTIDADE) AS NUMERIC(9,4));
     UPDATE VEN_EST SET VE_DIFERENCA = VE_DIFERENCA + :DIFERENCA WHERE VE_CODIGO = :CODVE;
END^


ALTER PROCEDURE DIFERENCA_CUSTOM_C (
    CODIGO INTEGER,
    CODCE INTEGER,
    CUSTOM FLOAT,
    QUANTIDADE FLOAT)
AS
DECLARE VARIABLE VALORCM FLOAT;
DECLARE VARIABLE DIFERENCA FLOAT;
BEGIN
     SELECT PRO_VALORCM FROM PRODUTOS WHERE PRO_CODIGO = :CODIGO
     INTO :VALORCM;
     DIFERENCA = CAST((CUSTOM*QUANTIDADE) - (VALORCM*QUANTIDADE) AS NUMERIC(9,4));
     UPDATE COM_EST SET CE_DIFERENCA = CE_DIFERENCA + :DIFERENCA WHERE CE_CODIGO = :CODCE;
END^


ALTER PROCEDURE DRE (
    DATA1 DATE,
    DATA2 DATE)
RETURNS (
    VENDA FLOAT,
    CMV FLOAT,
    DESPESA FLOAT)
AS
DECLARE VARIABLE VALOR FLOAT;
DECLARE VARIABLE JUROS FLOAT;
DECLARE VARIABLE DESCONTOS FLOAT;
BEGIN
     VENDA = 0;
     CMV = 0;
     DESPESA = 0;
     SELECT SUM(R.REC_VALOR), SUM(R.REC_JUROS), SUM(R.REC_DESCONTOS)
     FROM RECEBIMENTOS R, FATURAMENTOS F
     WHERE F.FAT_CODIGO = R.REC_FAT AND F.FAT_TIPO = 1 AND F.FAT_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VALOR, :JUROS, :DESCONTOS;
     VENDA = VALOR + JUROS - DESCONTOS;
     SELECT SUM(VE.VE_VALORF)
     FROM VENDAS V, VEN_EST VE
     WHERE VE.VE_VEN = V.VEN_CODIGO AND V.VEN_DATA BETWEEN :DATA1 AND :DATA2
     INTO :CMV;
     SELECT SUM(P.PAG_VALOR), SUM(P.PAG_JUROS), SUM(P.PAG_DESCONTOS)
     FROM PAGAMENTOS P, FATURAMENTO2 F
     WHERE F.FAT2_TIPO = 2 AND F.FAT2_CODIGO = P.PAG_FAT2 AND F.FAT2_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VALOR, :JUROS, :DESCONTOS;
     DESPESA = VALOR + JUROS - DESCONTOS;
     SELECT SUM(P.PAG_VALOR), SUM(P.PAG_JUROS), SUM(P.PAG_DESCONTOS)
     FROM PAGAMENTOS P, FATURAMENTO2 F
     WHERE F.FAT2_TIPO = 5 AND F.FAT2_CODIGO = P.PAG_FAT2 AND F.FAT2_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VALOR, :JUROS, :DESCONTOS;
     DESPESA = DESPESA + (VALOR + JUROS - DESCONTOS);
END^


