DECLARE VARIABLE CUSTOC FLOAT;
DECLARE VARIABLE CUSTO_MAT FLOAT;
DECLARE VARIABLE CUSTO_ALMOX FLOAT;
DECLARE VARIABLE CUSTO_SALARIO SMALLINT;
BEGIN
     VENDA_PRODUTO = 0;
     VENDA_CANCELADA = 0;
     IMPOSTO_VENDA = 0;
     PERDA_PRODUTO = 0;
     BONUS_PRODUTO = 0;
     CUSTO_PRODUTO = 0;
     COMISSOES_VENDA = 0;
     FRETE_COMPRA = 0;
     ICMS = 0;
     SALARIOS = 0;
     DESPESA_ADMINISTRATIVA = 0;
     RECEITA_FINANCEIRA = 0;
     DESPESA_FINANCEIRA = 0;
     RNO = 0;
     DNO = 0;
     VALORD_NOVO = 0;
     SELECT SUM(VE.VE_VALOR)
     FROM VENDAS V, VEN_EST VE, FATURAMENTOS F
     WHERE V.VEN_DATA BETWEEN :DATA1 AND :DATA2 AND VE.VE_VEN = V.VEN_CODIGO AND VEN_FAT = FAT_CODIGO
     INTO :VALOR;
     IF (:VALOR IS  NULL) THEN
      VALOR = 0;
     VENDA_PRODUTO = VALOR;
     SELECT SUM(VE_VALORCM)
     FROM VENDAS V, VEN_EST VE, FATURAMENTOS F
     WHERE V.VEN_DATA BETWEEN :DATA1 AND :DATA2 AND VE.VE_VEN = V.VEN_CODIGO AND VEN_FAT = FAT_CODIGO
     INTO :CUSTO_PRODUTO;
     IF (:CUSTO_PRODUTO IS  NULL) THEN
      CUSTO_PRODUTO = 0;
     SELECT SUM(COM_VALOR+COM_FRETE+COM_ICMS+COM_DARF)
     FROM COMPRAS
     WHERE COM_DATA BETWEEN :DATA1 AND :DATA2 AND COM_TIPO = 'VS' AND COM_DATAC = '01/01/1900'
     INTO :CUSTOC;
     IF (:CUSTOC IS  NULL) THEN
      CUSTOC = 0;
     SELECT SUM(VE.VE_VALOR), SUM(VE.VE_VALORCM), SUM(VE_DIFERENCA)
     FROM VENDAS V, VEN_EST VE, FATURAMENTOS F
     WHERE V.VEN_DATAC BETWEEN :DATA1 AND :DATA2 AND VE.VE_VEN = V.VEN_CODIGO AND VEN_FAT = FAT_CODIGO
     INTO :VALOR, :VALORCM, :VALORD;
     IF (:VALOR IS  NULL) THEN
      VALOR = 0;
     IF (:VALORCM IS  NULL) THEN
      VALORCM = 0;
     IF (:VALORD IS  NULL) THEN
      VALORD = 0;
     CUSTO_PRODUTO = CUSTO_PRODUTO - VALORCM + CUSTOC;
     VENDA_CANCELADA = (VALOR + VALORD);/* - VALORCM;
     /*SELECT SUM(CE_VALOR)
     FROM COMPRAS, COM_EST
     WHERE COM_CODIGO = CE_COM AND COM_DATAC BETWEEN :DATA1 AND :DATA2
     INTO :VALOR;
     IF (:VALOR IS  NULL) THEN
      VALOR = 0;
     COMPRAC = VALOR;*/
     SELECT SUM(CUST_VALOR)
     FROM CUSTOS
     WHERE CUST_TIPO = 'D' AND CUST_DATAC BETWEEN :DATA1 AND :DATA2
     INTO :VALOR;
     IF (:VALOR IS  NULL) THEN
      VALOR = 0;
     DESPESAC = VALOR;
     SELECT SUM(CUST_VALOR)
     FROM CUSTOS
     WHERE CUST_TIPO = 'C' AND CUST_DATAC BETWEEN :DATA1 AND :DATA2
     INTO :VALOR;
     IF (:VALOR IS  NULL) THEN
      VALOR = 0;
     CUSTOC = VALOR;
     SELECT SUM(TRI_VALOR)
     FROM TRIBUTACOES
     WHERE TRI_DATAC BETWEEN :DATA1 AND :DATA2
     INTO :VALOR;
     IF (:VALOR IS  NULL) THEN
      VALOR = 0;
     TRIBUTACAOC = VALOR;
     SELECT SUM(FRE_VALOR)
     FROM FRETES
     WHERE FRE_DATAC BETWEEN :DATA1 AND :DATA2
     INTO :VALOR;
     IF (:VALOR IS  NULL) THEN
      VALOR = 0;
     FRETEC = VALOR;
     OUTROS_CANCEL = DESPESAC + TRIBUTACAOC + FRETEC + CUSTOC;
     SELECT SUM(TRI_VALOR) FROM TRIBUTACOES, IMPOSTOS, FATURAMENTO2
     WHERE TRI_IMP = IMP_CODIGO AND TRI_FAT2 = FAT2_CODIGO AND IMP_TIPO = 'V' AND FAT2_DATA BETWEEN :DATA1 AND :DATA2
     INTO :IMPOSTO_VENDA;
     IF (:IMPOSTO_VENDA IS  NULL) THEN
      IMPOSTO_VENDA = 0;
     SELECT SUM(AE_VALOR) FROM ACERTO_EST WHERE (AE_TIPO = 'S' OR AE_TIPO = 'P')
     AND AE_DATA BETWEEN :DATA1 AND :DATA2
     INTO :PERDA_PRODUTO;
     IF (:PERDA_PRODUTO IS  NULL) THEN
      PERDA_PRODUTO = 0;
     SELECT SUM(AE_VALOR) FROM ACERTO_EST WHERE (AE_TIPO = 'E' OR AE_TIPO = 'G')
     AND AE_DATA BETWEEN :DATA1 AND :DATA2
     INTO :BONUS_PRODUTO;
     IF (:BONUS_PRODUTO IS  NULL) THEN
      BONUS_PRODUTO = 0;
     /*FAZER PROCEDIMENTO PARA GERAR VALOR DA COMISSAO */
     SELECT SUM(FRE_VALOR) FROM FRETES, FATURAMENTO2 WHERE FRE_FAT2 = FAT2_CODIGO AND
     FAT2_DATA BETWEEN :DATA1 AND :DATA2
     INTO :FRETE_COMPRA;
     IF (:FRETE_COMPRA IS  NULL) THEN
      FRETE_COMPRA = 0;
     SELECT SUM(TRI_VALOR) FROM TRIBUTACOES, IMPOSTOS, FATURAMENTO2
     WHERE TRI_IMP = IMP_CODIGO AND TRI_FAT2 = FAT2_CODIGO AND IMP_TIPO = 'C' AND FAT2_DATA BETWEEN :DATA1 AND :DATA2
     INTO :ICMS;
     IF (:ICMS IS  NULL) THEN
      ICMS = 0;
     SELECT SUM(FOL_VALORSAL)
     FROM FOLHA_PAGAMENTOS, FUNCIONARIOS
     WHERE FOL_FUN = FUN_CODIGO AND FUN_TIPO = 'D' AND FOL_DATA BETWEEN :DATA1 AND :DATA2
     INTO :FOLHAS;
     IF (:FOLHAS IS  NULL) THEN
      FOLHAS = 0;
     SELECT SUM(HEX_VALOR) FROM HEXTRA, FOLHA_PAGAMENTOS, FUNCIONARIOS
     WHERE HEX_FOL = FOL_CODIGO AND FOL_FUN = FUN_CODIGO AND FUN_TIPO = 'D' AND HEX_DATA BETWEEN :DATA1 AND :DATA2
     INTO :HORA_EXTRA;
     IF (:HORA_EXTRA IS  NULL) THEN
      HORA_EXTRA = 0;
     SALARIOS = FOLHAS + HORA_EXTRA;
     SELECT SUM(CUST_VALOR)
     FROM CUSTOS
     WHERE CUST_TIPO = 'D' AND CUST_DATA BETWEEN :DATA1 AND :DATA2
     INTO :DESPESA_ADMINISTRATIVA;
     IF (:DESPESA_ADMINISTRATIVA IS NULL) THEN
      DESPESA_ADMINISTRATIVA = 0;
     SELECT SUM(CUST_VALOR)
     FROM CUSTOS
     WHERE CUST_TIPO = 'C' AND CUST_DATA BETWEEN :DATA1 AND :DATA2
     INTO :CUSTO_MAT;
     IF (:CUSTO_MAT IS NULL) THEN
       CUSTO_MAT = 0;
     SELECT SUM(FOL_VALORSAL)
     FROM FOLHA_PAGAMENTOS, FUNCIONARIOS
     WHERE FOL_FUN = FUN_CODIGO AND FUN_TIPO = 'C' AND FOL_DATA BETWEEN :DATA1 AND :DATA2
     INTO :FOLHAS;
     IF (:FOLHAS IS  NULL) THEN
      FOLHAS = 0;
     SELECT SUM(HEX_VALOR) FROM HEXTRA, FOLHA_PAGAMENTOS, FUNCIONARIOS
     WHERE HEX_FOL = FOL_CODIGO AND FOL_FUN = FUN_CODIGO AND FUN_TIPO = 'C' AND HEX_DATA BETWEEN :DATA1 AND :DATA2
     INTO :HORA_EXTRA;
     IF (:HORA_EXTRA IS  NULL) THEN
      HORA_EXTRA = 0;
     CUSTO_SALARIO = FOLHAS + HORA_EXTRA;
     SELECT SUM(COM_VALOR+COM_FRETE+COM_ICMS+COM_DARF)
     FROM COMPRAS
     WHERE COM_DATA BETWEEN :DATA1 AND :DATA2 AND COM_TIPO = 'PR' AND COM_DATAC = '01/01/1900'
     INTO :CUSTO_ALMOX;
     IF (:CUSTO_ALMOX IS  NULL) THEN
      CUSTO_ALMOX = 0;
     CUSTO_PRODUCAO = CUSTO_MAT + CUSTO_ALMOX + CUSTO_SALARIO;
     SELECT SUM(LD_VALOR) FROM LANCAMENTO_DRF
     WHERE (LD_ESTADO = 'RJ' OR LD_ESTADO = 'RD') AND LD_DATA BETWEEN :DATA1 AND :DATA2
     INTO :RECEITA_FINANCEIRA;
     IF (:RECEITA_FINANCEIRA IS NULL) THEN
      RECEITA_FINANCEIRA = 0;
     SELECT SUM(LD_VALOR) FROM LANCAMENTO_DRF
     WHERE (LD_ESTADO = 'DJ' OR LD_ESTADO = 'DD') AND LD_DATA BETWEEN :DATA1 AND :DATA2
     INTO :DESPESA_FINANCEIRA;
     IF (:DESPESA_FINANCEIRA IS NULL) THEN
      DESPESA_FINANCEIRA = 0;
     SELECT SUM(RD_VALOR) FROM RNO_DNO
     WHERE (RD_TIPO = 'RNO') AND RD_DATA BETWEEN :DATA1 AND :DATA2
     INTO :RNO;
     IF (:RNO IS NULL) THEN
      RNO = 0;
     SELECT SUM(RD_VALOR) FROM RNO_DNO
     WHERE (RD_TIPO = 'DNO') AND RD_DATA BETWEEN :DATA1 AND :DATA2
     INTO :DNO;
     IF (:DNO IS NULL) THEN
      DNO = 0;
     FOR SELECT IMO_DATAC, IMO_VALORC, IMO_VALORD, IMO_PERCENTUALD FROM IMOBILIZADOS
     INTO :DATAC, :VALORC, :VALORD2, :PERCENTUALD DO
     BEGIN
          IF ((DATAC + 30) <= DATA1) THEN
          BEGIN
            VALORD_NOVO = VALORD_NOVO + (((VALORC-VALORD2)*(PERCENTUALD/100))/365)*30;
          END
          ELSE
          BEGIN
            IF ((DATAC+30) <= DATA2) THEN
            BEGIN
              VALORD_NOVO = VALORD_NOVO + (((VALORC-VALORD2)*(PERCENTUALD/100))/365)*(DATA2-(DATAC+30));
            END
          END
     END
END^


ALTER PROCEDURE DRE2 (
    MES INTEGER,
    ANO INTEGER,
    DATA DATE)
RETURNS (
    VENDA FLOAT,
    CMV FLOAT,
    DESPESA FLOAT,
    RNO FLOAT,
    DNO FLOAT,
    AI FLOAT,
    AJUSTE1 FLOAT,
    AJUSTE2 FLOAT,
    VI FLOAT)
AS
declare variable valor float;
declare variable juros float;
declare variable descontos float;
declare variable cheque float;
declare variable dinheiro float;
declare variable fretex float;
declare variable fretey float;
declare variable tributox float;
declare variable tributoy float;
declare variable vista float;
declare variable tributoc float;
declare variable fretec float;
BEGIN
     VENDA = 0;
     CMV = 0;
     DESPESA = 0;
     RNO =0;
     DNO = 0;
     AI = 0;
     AJUSTE1 = 0;
     AJUSTE2 = 0;
     VI = 0;
     SELECT SUM(VE.VE_VALOR)
     FROM VENDAS V, VEN_EST VE
     WHERE EXTRACT(MONTH FROM V.VEN_DATA) = :MES
     AND EXTRACT(YEAR FROM V.VEN_DATA) = :ANO AND VE.VE_VEN = V.VEN_CODIGO
     INTO :VALOR;
     
     if (:VALOR IS  NULL) then
      VALOR = 0;
     
     VENDA = VALOR;
     SELECT SUM(VE.VE_VALORF)
     FROM VENDAS V, VEN_EST VE
     WHERE EXTRACT(MONTH FROM V.VEN_DATA) = :MES
     AND EXTRACT(YEAR FROM V.VEN_DATA) = :ANO AND VE.VE_VEN = V.VEN_CODIGO
     INTO :CMV;
     if (:CMV IS  NULL) then
      CMV = 0;

     SELECT SUM(C.CUST_VALOR)
     FROM CUSTOS C, FATURAMENTO2 F
     WHERE F.FAT2_TIPO = 2 AND F.FAT2_DESCRICAO = C.CUST_CODIGO AND
     EXTRACT(MONTH FROM F.FAT2_DATA) = :MES AND EXTRACT(YEAR FROM F.FAT2_DATA) = :ANO
     INTO :VALOR;
     if (:VALOR IS NULL) then
      VALOR = 0;

     if (:CHEQUE IS NULL) then
      CHEQUE = 0;
     DESPESA = VALOR - CHEQUE;

     SELECT SUM(FOL_VALORSAL)
     FROM FOLHA_PAGAMENTOS
     WHERE EXTRACT(MONTH FROM FOL_DATA) = :MES
     AND EXTRACT(YEAR FROM FOL_DATA) = :ANO
     INTO :VALOR;

     if (:CHEQUE IS NULL) then
      CHEQUE = 0;
     if (:VALOR IS  NULL) then
      VALOR = 0;
     if (:JUROS IS  NULL) then
      JUROS = 0;
     if (:DESCONTOS IS  NULL) then
      DESCONTOS = 0;

     DESPESA = DESPESA + (VALOR + JUROS - DESCONTOS) - CHEQUE;

     SELECT SUM(RD_VALOR)
     FROM RNO_DNO
     WHERE EXTRACT(MONTH FROM RD_DATA) = :MES
     AND EXTRACT(YEAR FROM RD_DATA) = :ANO AND RD_TIPO = 'RNO'
     INTO :RNO;

     SELECT SUM(RD_VALOR)
     FROM RNO_DNO
     WHERE EXTRACT(MONTH FROM RD_DATA) = :MES
     AND EXTRACT(YEAR FROM RD_DATA) = :ANO AND RD_TIPO = 'DNO'
     INTO :DNO;
     
     SELECT SUM(RD_VALOR)
     FROM RNO_DNO
     WHERE EXTRACT(MONTH FROM RD_DATA) = :MES
     AND EXTRACT(YEAR FROM RD_DATA) = :ANO AND RD_TIPO = 'AI'
     INTO :AI;

     SELECT SUM(RD_VALOR)
     FROM RNO_DNO
     WHERE EXTRACT(MONTH FROM RD_DATA) = :MES
     AND EXTRACT(YEAR FROM RD_DATA) = :ANO AND RD_TIPO = 'VI'
     INTO :VI;

     SELECT SUM(AE_VALOR)
     FROM ACERTO_EST
     WHERE EXTRACT(MONTH FROM AE_DATA) = :MES
     AND EXTRACT(YEAR FROM AE_DATA) = :ANO AND ((AE_TIPO = 'E') OR (AE_TIPO = 'G'))
     INTO :AJUSTE1;
     
     SELECT SUM(AE_VALOR)
     FROM ACERTO_EST
     WHERE EXTRACT(MONTH FROM AE_DATA) = :MES
     AND EXTRACT(YEAR FROM AE_DATA) = :ANO AND ((AE_TIPO = 'S') OR (AE_TIPO = 'P'))
     INTO :AJUSTE2;

     if (:RNO IS  NULL) then
      RNO = 0;
     if (:DNO IS  NULL) then
      DNO = 0;
     if (:AI IS  NULL) then
      AI = 0;
     if (:VI IS  NULL) then
      VI = 0;
     if (:AJUSTE1 IS  NULL) then
      AJUSTE1 = 0;
     if (:AJUSTE2 IS  NULL) then
      AJUSTE2 = 0;


END^


ALTER PROCEDURE E_DRE_BP (
    DATA1 DATE,
    DATA2 DATE)
RETURNS (
    VENDA_PRODUTO FLOAT,
    VENDA_CANCELADA FLOAT,
    IMPOSTO_VENDA FLOAT,
    PERDA_PRODUTO FLOAT,
    BONUS_PRODUTO FLOAT,
    CUSTO_PRODUTO FLOAT,
    COMISSOES_VENDA FLOAT,
    FRETE_COMPRA FLOAT,
    ICMS FLOAT,
    SALARIOS FLOAT,
    DESPESA_ADMINISTRATIVA FLOAT,
    RECEITA_FINANCEIRA FLOAT,
    DESPESA_FINANCEIRA FLOAT,
    RNO FLOAT,
    DNO FLOAT,
    OUTROS_CANCEL FLOAT,
    VALORD_NOVO FLOAT,
    CUSTO_PRODUCAO FLOAT)
AS
declare variable VALOR float;
declare variable VALORCM float;
declare variable VALORD float;
declare variable DESPESAC float;
declare variable TRIBUTACAOC float;
declare variable FRETEC float;
declare variable COMPRAC float;
declare variable DATAC date;
declare variable VALORC float;
declare variable VALORD2 float;
declare variable FOLHAS float;
declare variable HORA_EXTRA float;
declare variable PERCENTUALD numeric(3,2);
declare variable CUSTOC float;
declare variable CUSTO_MAT float;
declare variable CUSTO_ALMOX float;
declare variable CUSTO_SALARIO smallint;
declare variable PAGAMENTOC float;
BEGIN
     VENDA_PRODUTO = 0;
     VENDA_CANCELADA = 0;
     IMPOSTO_VENDA = 0;
     PERDA_PRODUTO = 0;
     BONUS_PRODUTO = 0;
     CUSTO_PRODUTO = 0;
     COMISSOES_VENDA = 0;
     FRETE_COMPRA = 0;
     ICMS = 0;
     SALARIOS = 0;
     DESPESA_ADMINISTRATIVA = 0;
     RECEITA_FINANCEIRA = 0;
     DESPESA_FINANCEIRA = 0;
     RNO = 0;
     DNO = 0;
     VALORD_NOVO = 0;
     SELECT SUM(VE.VE_VALOR)
     FROM VENDAS V, VEN_EST VE, FATURAMENTOS F
     WHERE V.VEN_DATA BETWEEN :DATA1 AND :DATA2 AND VE.VE_VEN = V.VEN_CODIGO AND VEN_FAT = FAT_CODIGO
     INTO :VALOR;
     if (:VALOR IS  NULL) then
      VALOR = 0;
     VENDA_PRODUTO = VALOR;
     SELECT SUM(VE_VALORCM)
     FROM VENDAS V, VEN_EST VE, FATURAMENTOS F
     WHERE V.VEN_DATA BETWEEN :DATA1 AND :DATA2 AND VE.VE_VEN = V.VEN_CODIGO AND VEN_FAT = FAT_CODIGO
     INTO :CUSTO_PRODUTO;
     if (:CUSTO_PRODUTO IS  NULL) then
      CUSTO_PRODUTO = 0;
     SELECT SUM(COM_VALOR+COM_FRETE+COM_ICMS+COM_DARF)
     FROM COMPRAS
     WHERE COM_DATA BETWEEN :DATA1 AND :DATA2 AND COM_TIPO = 'VS' AND COM_DATAC = '01/01/1900'
     INTO :CUSTOC;
     if (:CUSTOC IS  NULL) then
      CUSTOC = 0;
     SELECT SUM(VE.VE_VALOR), SUM(VE.VE_VALORCM)
     FROM VENDAS V, VEN_EST VE, FATURAMENTOS F
     WHERE V.VEN_DATAC BETWEEN :DATA1 AND :DATA2 AND VE.VE_VEN = V.VEN_CODIGO AND V.VEN_FAT = F.FAT_CODIGO
     INTO :VALOR, :VALORCM;
     if (:VALOR IS  NULL) then
      VALOR = 0;
     if (:VALORCM IS  NULL) then
      VALORCM = 0;
     SELECT SUM(VE_DIFERENCA)
     FROM VENDAS V, VEN_EST VE
     WHERE V.VEN_DATAC BETWEEN :DATA1 AND :DATA2 AND VE.VE_VEN = V.VEN_CODIGO
     INTO :VALORD;
     if (:VALORD IS  NULL) then
      VALORD = 0;
     CUSTO_PRODUTO = CUSTO_PRODUTO - VALORCM + CUSTOC;
     VENDA_CANCELADA = (VALOR + VALORD);
     SELECT SUM(CE_DIFERENCA)
     FROM COMPRAS, COM_EST
     WHERE COM_CODIGO = CE_COM AND COM_DATAC BETWEEN :DATA1 AND :DATA2
     INTO :VALORD;
     if (:VALORD IS  NULL) then
      VALORD = 0;
     SELECT SUM(CUST_VALOR)
     FROM CUSTOS
     WHERE CUST_TIPO = 'D' AND CUST_DATAC BETWEEN :DATA1 AND :DATA2
     INTO :VALOR;
     if (:VALOR IS  NULL) then
      VALOR = 0;
     DESPESAC = VALOR;
     SELECT SUM(CUST_VALOR)
     FROM CUSTOS
     WHERE CUST_TIPO = 'C' AND CUST_DATAC BETWEEN :DATA1 AND :DATA2
     INTO :VALOR;
     if (:VALOR IS  NULL) then
      VALOR = 0;
     CUSTOC = VALOR;
     SELECT SUM(TRI_VALOR)
     FROM TRIBUTACOES
     WHERE TRI_DATAC BETWEEN :DATA1 AND :DATA2
     INTO :VALOR;
     if (:VALOR IS  NULL) then
      VALOR = 0;
     TRIBUTACAOC = VALOR;
     SELECT SUM(FRE_VALOR)
     FROM FRETES
     WHERE FRE_DATAC BETWEEN :DATA1 AND :DATA2
     INTO :VALOR;
     if (:VALOR IS  NULL) then
      VALOR = 0;
     FRETEC = VALOR;
     SELECT SUM(PAG_VALOR+PAG_JUROS-PAG_DESCONTOS)
     FROM PAGAMENTOS
     WHERE PAG_SITUACAO = 3 AND PAG_DATAC BETWEEN :DATA1 AND :DATA2
     INTO :VALOR;
     if (:VALOR IS  NULL) then
      VALOR = 0;
     PAGAMENTOC = VALOR;
     OUTROS_CANCEL = DESPESAC + TRIBUTACAOC + FRETEC + CUSTOC + VALORD + PAGAMENTOC;
     SELECT SUM(TRI_VALOR) FROM TRIBUTACOES, IMPOSTOS, FATURAMENTO2
     WHERE TRI_IMP = IMP_CODIGO AND TRI_FAT2 = FAT2_CODIGO AND IMP_TIPO = 'V' AND FAT2_DATA BETWEEN :DATA1 AND :DATA2
     INTO :IMPOSTO_VENDA;
     if (:IMPOSTO_VENDA IS  NULL) then
      IMPOSTO_VENDA = 0;
     SELECT SUM(AE_VALOR) FROM ACERTO_EST WHERE (AE_TIPO = 'S' OR AE_TIPO = 'P')
     AND AE_DATA BETWEEN :DATA1 AND :DATA2
     INTO :PERDA_PRODUTO;
     if (:PERDA_PRODUTO IS  NULL) then
      PERDA_PRODUTO = 0;
     SELECT SUM(AE_VALOR) FROM ACERTO_EST WHERE (AE_TIPO = 'E' OR AE_TIPO = 'G')
     AND AE_DATA BETWEEN :DATA1 AND :DATA2
     INTO :BONUS_PRODUTO;
     if (:BONUS_PRODUTO IS  NULL) then
      BONUS_PRODUTO = 0;
     SELECT SUM(FRE_VALOR) FROM FRETES, FATURAMENTO2 WHERE FRE_FAT2 = FAT2_CODIGO AND
     FAT2_DATA BETWEEN :DATA1 AND :DATA2
     INTO :FRETE_COMPRA;
     if (:FRETE_COMPRA IS  NULL) then
      FRETE_COMPRA = 0;
     SELECT SUM(TRI_VALOR) FROM TRIBUTACOES, IMPOSTOS, FATURAMENTO2
     WHERE TRI_IMP = IMP_CODIGO AND TRI_FAT2 = FAT2_CODIGO AND IMP_TIPO = 'C' AND FAT2_DATA BETWEEN :DATA1 AND :DATA2
     INTO :ICMS;
     if (:ICMS IS  NULL) then
      ICMS = 0;
     SELECT SUM(FOL_VALORSAL)
     FROM FOLHA_PAGAMENTOS, FUNCIONARIOS
     WHERE FOL_FUN = FUN_CODIGO AND FUN_TIPO = 'D' AND FOL_DATA BETWEEN :DATA1 AND :DATA2
     INTO :FOLHAS;
     if (:FOLHAS IS  NULL) then
      FOLHAS = 0;
     SELECT SUM(HEX_VALOR) FROM HEXTRA, FOLHA_PAGAMENTOS, FUNCIONARIOS
     WHERE HEX_FOL = FOL_CODIGO AND FOL_FUN = FUN_CODIGO AND FUN_TIPO = 'D' AND HEX_DATA BETWEEN :DATA1 AND :DATA2
     INTO :HORA_EXTRA;
     if (:HORA_EXTRA IS  NULL) then
      HORA_EXTRA = 0;
     SALARIOS = FOLHAS + HORA_EXTRA;
     SELECT SUM(CUST_VALOR)
     FROM CUSTOS
     WHERE CUST_TIPO = 'D' AND CUST_DATA BETWEEN :DATA1 AND :DATA2
     INTO :DESPESA_ADMINISTRATIVA;
     if (:DESPESA_ADMINISTRATIVA IS NULL) then
      DESPESA_ADMINISTRATIVA = 0;
     SELECT SUM(CUST_VALOR)
     FROM CUSTOS
     WHERE CUST_TIPO = 'C' AND CUST_DATA BETWEEN :DATA1 AND :DATA2
     INTO :CUSTO_MAT;
     if (:CUSTO_MAT IS NULL) then
       CUSTO_MAT = 0;
     SELECT SUM(FOL_VALORSAL)
     FROM FOLHA_PAGAMENTOS, FUNCIONARIOS
     WHERE FOL_FUN = FUN_CODIGO AND FUN_TIPO = 'C' AND FOL_DATA BETWEEN :DATA1 AND :DATA2
     INTO :FOLHAS;
     if (:FOLHAS IS  NULL) then
      FOLHAS = 0;
     SELECT SUM(HEX_VALOR) FROM HEXTRA, FOLHA_PAGAMENTOS, FUNCIONARIOS
     WHERE HEX_FOL = FOL_CODIGO AND FOL_FUN = FUN_CODIGO AND FUN_TIPO = 'C' AND HEX_DATA BETWEEN :DATA1 AND :DATA2
     INTO :HORA_EXTRA;
     if (:HORA_EXTRA IS  NULL) then
      HORA_EXTRA = 0;
     CUSTO_SALARIO = FOLHAS + HORA_EXTRA;
     SELECT SUM(COM_VALOR+COM_FRETE+COM_ICMS+COM_DARF)
     FROM COMPRAS
     WHERE COM_DATA BETWEEN :DATA1 AND :DATA2 AND COM_TIPO = 'PR' AND COM_DATAC = '01/01/1900'
     INTO :CUSTO_ALMOX;
     if (:CUSTO_ALMOX IS  NULL) then
      CUSTO_ALMOX = 0;
     CUSTO_PRODUCAO = CUSTO_MAT + CUSTO_ALMOX + CUSTO_SALARIO;
     SELECT SUM(LD_VALOR) FROM LANCAMENTO_DRF
     WHERE (LD_ESTADO = 'RJ' OR LD_ESTADO = 'RD') AND LD_DATA BETWEEN :DATA1 AND :DATA2
     INTO :RECEITA_FINANCEIRA;
     if (:RECEITA_FINANCEIRA IS NULL) then
      RECEITA_FINANCEIRA = 0;
     SELECT SUM(LD_VALOR) FROM LANCAMENTO_DRF
     WHERE (LD_ESTADO = 'DJ' OR LD_ESTADO = 'DD') AND LD_DATA BETWEEN :DATA1 AND :DATA2
     INTO :DESPESA_FINANCEIRA;
     if (:DESPESA_FINANCEIRA IS NULL) then
      DESPESA_FINANCEIRA = 0;
     SELECT SUM(RD_VALOR) FROM RNO_DNO
     WHERE (RD_TIPO = 'RNO') AND RD_DATA BETWEEN :DATA1 AND :DATA2
     INTO :RNO;
     if (:RNO IS NULL) then
      RNO = 0;
     SELECT SUM(RD_VALOR) FROM RNO_DNO
     WHERE (RD_TIPO = 'DNO') AND RD_DATA BETWEEN :DATA1 AND :DATA2
     INTO :DNO;
     if (:DNO IS NULL) then
      DNO = 0;
     FOR SELECT IMO_DATAC, IMO_VALORC, IMO_VALORD, IMO_PERCENTUALD FROM IMOBILIZADOS
     INTO :DATAC, :VALORC, :VALORD2, :PERCENTUALD DO
     BEGIN
          if ((DATAC + 30) <= DATA1) then
          begin
            VALORD_NOVO = VALORD_NOVO + (((VALORC-VALORD2)*(PERCENTUALD/100))/365)*30;
          end
          else
          begin
            if ((DATAC+30) <= DATA2) then
            begin
              VALORD_NOVO = VALORD_NOVO + (((VALORC-VALORD2)*(PERCENTUALD/100))/365)*(DATA2-(DATAC+30));
            end
          end
     END
END^


