    NOT_DESCONTO = :DESCONTO, NOT_TRANS_NOME = :TRANS_NOME, NOT_TRANS_FRETE = :TRANS_FRETE,
    NOT_TRANS_PLACA = :TRANS_PLACA, NOT_TRANS_UF_VEIC = :TRANS_UF_VEIC,
    NOT_TRANS_CPF_CNPJ = :TRANS_CPF_CNPJ, NOT_TRANS_ENDERECO = :TRANS_ENDERECO,
    NOT_TRANS_MUNICIPIO = :TRANS_MUNICIPIO, NOT_TRANS_UF = :TRANS_UF,
    NOT_TRANS_INSCRICAO = :TRANS_INSCRICAO, NOT_TRANS_QUANTIDADE = :TRANS_QUANTIDADE,
    NOT_TRANS_ESPECIE = :TRANS_ESPECIE, NOT_TRANS_MARCA = :TRANS_MARCA,
    NOT_TRANS_NUMERO = :TRANS_NUMERO, NOT_TRANS_PESOBRUTO = :TRANS_PESOB,
    NOT_TRANS_PESOLIQ = :TRANS_PESOL, NOT_INF_COMP = :INF_COMP, NOT_FUN = :FUN,
    NOT_IC = :IC, NOT_ONF = :ONF, NOT_OBS = :OBS, NOT_MODELO = :MODELO,
    NOT_CHAVE_NFE = :CHAVE_NFE, NOT_OPER_CONSUM_FINAL = :OPER_CONSUM_FINAL,
    NOT_COMP_PRESENTE = :COMP_PRESENTE, NOT_NF_REFERENCIADAS = :NF_REFERENCIADAS,
    NOT_INS = :INSCRICAO, NOT_CONDICAO_PGTO = :CONDICAO_PGTO,
    NOT_IND_EMISSAO = :IND_EMISSAO, NOT_SERIE = :SERIE
    WHERE NOT_CODIGO = :CODIGO;
END^


