ALTER PROCEDURE ESTADO_CHEQUE (
    COD_CHEQUE INTEGER,
    ESTADO INTEGER,
    DATA DATE)
AS
begin
     if (ESTADO = 6) then
     begin
       UPDATE CHEQUES SET CHE_ESTADO = 6 WHERE CHE_CODIGO = :COD_CHEQUE;
       INSERT INTO CHE_HIS VALUES(GEN_ID(GEN_CH,1), :DATA, 'CHEQUE EXCLUIDO', :COD_CHEQUE);
     end
     else if (ESTADO = 4) then
     begin
       UPDATE CHEQUES SET CHE_ESTADO = 4 WHERE CHE_CODIGO = :COD_CHEQUE;
       INSERT INTO CHE_HIS VALUES(GEN_ID(GEN_CH,1), :DATA, 'CHEQUE DEVOLVIDO1', :COD_CHEQUE);
     end
     else if (ESTADO = 5) then
     begin
       UPDATE CHEQUES SET CHE_ESTADO = 5 WHERE CHE_CODIGO = :COD_CHEQUE;
       INSERT INTO CHE_HIS VALUES(GEN_ID(GEN_CH,1), :DATA, 'CHEQUE DEVOLVIDO2', :COD_CHEQUE);
     end
     /* Procedure Text */
  suspend;
end^


ALTER PROCEDURE EXCLUI_CHEQUE (
    COD_CHEQUE INTEGER)
AS
begin
     UPDATE CHEQUES SET CHE_ESTADO = 6 WHERE CHE_CODIGO = :COD_CHEQUE;
     /* Procedure Text */
  suspend;
end^


ALTER PROCEDURE FECHAMENTO (
    CODIGO INTEGER)
RETURNS (
    TOTAL_COMPRA FLOAT,
    TOTAL_VENDA FLOAT,
    TOTAL_RECEBIMENTO FLOAT,
    TOTAL_PAGAMENTO FLOAT,
    TOTAL_TRIBUTACAO FLOAT,
    TOTAL_DESPESA FLOAT,
    TOTAL_FRETE FLOAT,
    TOTAL_FOLHA FLOAT)
AS
DECLARE VARIABLE VALOR FLOAT;
DECLARE VARIABLE JUROS FLOAT;
DECLARE VARIABLE DESCONTOS FLOAT;
DECLARE VARIABLE DINHEIRO FLOAT;
DECLARE VARIABLE CHEQUE FLOAT;
DECLARE VARIABLE VALOR_DEVI FLOAT;
begin
     SELECT SUM(R.REC_VALOR), SUM(R.REC_JUROS), SUM(R.REC_DESCONTOS)
     FROM FATURAMENTOS F, RECEBIMENTOS R
     WHERE F.FAT_TIPO = 1 AND R.REC_FAT = F.FAT_CODIGO AND  R.REC_CAI = :CODIGO
     INTO :VALOR, :JUROS, :DESCONTOS;
     TOTAL_VENDA = (:VALOR + :JUROS - :DESCONTOS);
     if (TOTAL_VENDA IS NULL) then
      TOTAL_VENDA = 0;
     SELECT SUM(RP.RP_DINHEIRO), SUM(RP.RP_CHEQUE)
     FROM RECEBIMENTOS R, REC_PGM RP
     WHERE R.REC_CODIGO = RP.RP_REC AND RP.RP_CAI = :CODIGO
     INTO :DINHEIRO, :CHEQUE;
     TOTAL_RECEBIMENTO = (:DINHEIRO + :CHEQUE);
     if (TOTAL_RECEBIMENTO IS NULL) then
      TOTAL_RECEBIMENTO = 0;
     ELSE
     SELECT SUM(PP.PP_DINHEIRO), SUM(PP.PP_CHEQUE)
     FROM PAGAMENTOS P, PAG_PGM PP
     WHERE P.PAG_CODIGO = PP.PP_PAG AND PP.PP_CAI = :CODIGO
     INTO :DINHEIRO, :CHEQUE;
     TOTAL_PAGAMENTO = (:DINHEIRO + :CHEQUE);
     if (TOTAL_PAGAMENTO IS NULL) then
      TOTAL_PAGAMENTO = 0;
     SELECT SUM(P.PAG_VALOR), SUM(P.PAG_JUROS), SUM(P.PAG_DESCONTOS)
     FROM FATURAMENTO2 F, PAGAMENTOS P
     WHERE F.FAT2_TIPO = 1 AND P.PAG_FAT2 = F.FAT2_CODIGO AND P.PAG_CAI = :CODIGO
     INTO :VALOR, :JUROS, :DESCONTOS;
     TOTAL_COMPRA = (:VALOR + :JUROS - :DESCONTOS);
     if (TOTAL_COMPRA IS NULL) then
      TOTAL_COMPRA = 0;
     SELECT SUM(P.PAG_VALOR), SUM(P.PAG_JUROS), SUM(P.PAG_DESCONTOS)
     FROM FATURAMENTO2 F, PAGAMENTOS P
     WHERE F.FAT2_TIPO = 2  AND P.PAG_FAT2 = F.FAT2_CODIGO AND P.PAG_CAI = :CODIGO
     INTO :VALOR, :JUROS, :DESCONTOS;
     TOTAL_DESPESA = (:VALOR + :JUROS - :DESCONTOS);
     if (TOTAL_DESPESA IS NULL) then
      TOTAL_DESPESA = 0;
     SELECT SUM(P.PAG_VALOR), SUM(P.PAG_JUROS), SUM(P.PAG_DESCONTOS)
     FROM FATURAMENTO2 F, PAGAMENTOS P
     WHERE F.FAT2_TIPO = 3 AND P.PAG_FAT2 = F.FAT2_CODIGO AND P.PAG_CAI = :CODIGO
     INTO :VALOR, :JUROS, :DESCONTOS;
     TOTAL_TRIBUTACAO = (:VALOR + :JUROS - :DESCONTOS);
     if (TOTAL_TRIBUTACAO IS NULL) then
      TOTAL_TRIBUTACAO = 0;
     SELECT SUM(P.PAG_VALOR), SUM(P.PAG_JUROS), SUM(P.PAG_DESCONTOS)
     FROM FATURAMENTO2 F, PAGAMENTOS P
     WHERE F.FAT2_TIPO = 4 AND P.PAG_FAT2 = F.FAT2_CODIGO AND P.PAG_CAI = :CODIGO
     INTO :VALOR, :JUROS, :DESCONTOS;
     TOTAL_FRETE = (:VALOR + :JUROS - :DESCONTOS);
     if (TOTAL_FRETE IS NULL) then
      TOTAL_FRETE = 0;
     SELECT SUM(P.PAG_VALOR), SUM(P.PAG_JUROS), SUM(P.PAG_DESCONTOS)
     FROM FATURAMENTO2 F, PAGAMENTOS P
     WHERE F.FAT2_TIPO = 5 AND P.PAG_FAT2 = F.FAT2_CODIGO AND P.PAG_CAI = :CODIGO
     INTO :VALOR, :JUROS, :DESCONTOS;
     TOTAL_FOLHA = (:VALOR + :JUROS - :DESCONTOS);
     if (TOTAL_FOLHA IS NULL) then
      TOTAL_FOLHA = 0;
 
end^


ALTER PROCEDURE FECHAMENTO_BALANCO (
    CODIGO INTEGER)
RETURNS (
    SOBRA FLOAT,
    FALTA FLOAT,
    ENTRADA FLOAT,
    SAIDA FLOAT,
    SOMA FLOAT,
    PERDA FLOAT,
    GARANTIA FLOAT)
AS
declare variable VALORV FLOAT;
declare variable QUANTIDADE FLOAT;
BEGIN
     SOBRA = 0;
     FALTA = 0;
     ENTRADA = 0;
     SAIDA = 0;
     PERDA = 0;
     GARANTIA = 0;
     VALORV = 0;
     QUANTIDADE = 0;
     SOMA = 0;
     SELECT SUM(CAI_SOBRA), SUM(CAI_FALTA) FROM CAIXA WHERE CAI_BAL = :CODIGO
     INTO :SOBRA, :FALTA;
     if (:SOBRA IS NULL) then
      SOBRA = 0;
     if (:FALTA IS NULL) then
      FALTA = 0;
     SELECT SUM(AE_VALOR) FROM ACERTO_EST WHERE AE_TIPO = 'E' AND AE_BAL = :CODIGO
     INTO :ENTRADA;
     if (:ENTRADA IS NULL) then
      ENTRADA = 0;
     SELECT SUM(AE_VALOR) FROM ACERTO_EST WHERE AE_TIPO = 'S' AND AE_BAL = :CODIGO
     INTO :SAIDA;
     if (:SAIDA IS NULL) then
      SAIDA = 0;
     SELECT SUM(AE_VALOR) FROM ACERTO_EST WHERE AE_TIPO = 'P' AND AE_BAL = :CODIGO
     INTO :PERDA;
     if (:PERDA IS NULL) then
      PERDA = 0;
     SELECT SUM(AE_VALOR) FROM ACERTO_EST WHERE AE_TIPO = 'G' AND AE_BAL = :CODIGO
     INTO :GARANTIA;
     if (:GARANTIA IS NULL) then
      GARANTIA = 0;
     FOR SELECT PRO_VALORV, PRO_QUANTIDADE FROM PRODUTOS
     INTO :VALORV, :QUANTIDADE DO
     BEGIN
          SOMA = SOMA + (VALORV*QUANTIDADE);
     END
END^


ALTER PROCEDURE FECHAMENTOCAIXA (
    COD_CAIXA INTEGER)
RETURNS (
    VENDAVISTA FLOAT,
    VENDAPRAZO FLOAT,
    RECEBIMENTOS FLOAT,
    TOTALENTRADAS FLOAT,
    COMPRAVISTA FLOAT,
    COMPRAPRAZO FLOAT,
    DESPESAVISTA FLOAT,
    DESPESAPRAZO FLOAT,
    TRIBUTACOESVISTA FLOAT,
    TRIBUTACOESPRAZO FLOAT,
    FRETEVISTA FLOAT,
    FRETEPRAZO FLOAT,
    PAGAMENTOS FLOAT,
    TOTALSAIDAS FLOAT,
    VENDAD FLOAT,
    VENDAC FLOAT,
    RECEBD FLOAT,
    RECEBC FLOAT,
    VENDA_CARTAO_CRED FLOAT,
    VENDA_CARTAO_DEBITO FLOAT,
    VENDA_PEDIDO FLOAT,
    DESCONTO_VENDA FLOAT,
    VENDA_BOLETO FLOAT)
AS
DECLARE VARIABLE VALORPG FLOAT;
DECLARE VARIABLE VALORPGD FLOAT;
DECLARE VARIABLE VALORPGC FLOAT;
BEGIN
     /*VENDAS A VISTA*/
     SELECT SUM(RP.RP_DINHEIRO), SUM(RP.RP_CHEQUE)
     FROM FATURAMENTOS F, RECEBIMENTOS R, REC_PGM RP
     WHERE F.FAT_TIPO = 1 AND R.REC_FAT = F.FAT_CODIGO AND RP.RP_REC = R.REC_CODIGO AND F.FAT_DATA = R.REC_VENCIMENTO AND
     R.REC_CAI = :COD_CAIXA
     INTO :VENDAD, :VENDAC;
     IF (:VENDAD IS NULL) THEN
       VENDAD = 0;
     IF (:VENDAC IS NULL) THEN
       VENDAC = 0;
     SELECT SUM(RP_DINHEIRO), SUM(RP_CHEQUE)
     FROM FATURAMENTOS, RECEBIMENTOS, REC_PGM
     WHERE FAT_TIPO = 1 AND REC_FAT = FAT_CODIGO AND RP_REC = REC_CODIGO AND FAT_DATA < REC_VENCIMENTO AND
     RP_DATAPGM = FAT_DATA AND REC_CAI = :COD_CAIXA
     INTO :VALORPGD, :VALORPGC;
     IF (:VALORPGD IS NULL) THEN
       VALORPGD = 0;
     IF (:VALORPGC IS NULL) THEN
       VALORPGC = 0;
     VENDAD = VENDAD+VALORPGD;
     VENDAC = VENDAC+VALORPGC;
     VENDAVISTA = VENDAD+VENDAC;
     /*VENDAS A PRAZO*/
     SELECT SUM(R.REC_VALOR+R.REC_JUROS-R.REC_DESCONTOS)
     FROM FATURAMENTOS F, RECEBIMENTOS R
     WHERE F.FAT_TIPO = 1 AND R.REC_FAT = F.FAT_CODIGO AND F.FAT_DATA < R.REC_VENCIMENTO AND  R.REC_CAI = :COD_CAIXA
     INTO :VENDAPRAZO;
     IF (:VENDAPRAZO IS NULL) THEN
       VENDAPRAZO = 0;
     VENDAPRAZO = VENDAPRAZO-(VALORPGD+VALORPGC);
     /*VENDA CARTAO CREDITO*/
     SELECT SUM(FAT_VALOR)
     FROM RECEBIMENTOS, TIPO_PGM, FATURAMENTOS
     WHERE REC_CON = TP_CODIGO AND REC_FAT = FAT_CODIGO
     AND (TP_NOME = 'CC') AND REC_CAI = :COD_CAIXA
     INTO :VENDA_CARTAO_CRED;
     IF (:VENDA_CARTAO_CRED IS NULL) THEN
       VENDA_CARTAO_CRED = 0;
     /*VENDA CARTAO DEBITO*/
     SELECT SUM(FAT_VALOR)
     FROM RECEBIMENTOS, TIPO_PGM, FATURAMENTOS
     WHERE REC_CON = TP_CODIGO AND REC_FAT = FAT_CODIGO
     AND (TP_NOME = 'CD') AND REC_CAI = :COD_CAIXA
     INTO :VENDA_CARTAO_DEBITO;
     IF (:VENDA_CARTAO_DEBITO IS NULL) THEN
       VENDA_CARTAO_DEBITO = 0;
      /*VENDA PEDIDO*/
     SELECT SUM(REC_VALOR)
     FROM RECEBIMENTOS, TIPO_PGM, FATURAMENTOS
     WHERE REC_CON = TP_CODIGO AND REC_FAT = FAT_CODIGO
     AND (TP_NOME = 'PE') AND REC_CAI = :COD_CAIXA
     INTO :VENDA_PEDIDO;
     IF (:VENDA_PEDIDO IS NULL) THEN
       VENDA_PEDIDO = 0;
     /*VENDA BOLETO*/
     SELECT SUM(REC_VALOR)
     FROM RECEBIMENTOS, TIPO_PGM, FATURAMENTOS
     WHERE REC_CON = TP_CODIGO AND REC_FAT = FAT_CODIGO
     AND (TP_NOME = 'BO') AND REC_CAI = :COD_CAIXA
     INTO :VENDA_BOLETO;
     IF (:VENDA_BOLETO IS NULL) THEN
       VENDA_BOLETO = 0;
     /*DESCONTO VENDA*/
     SELECT SUM(PF.PF_DESCONTO)
     FROM FATURAMENTOS F, RECEBIMENTOS R, PED_FAT PF
     WHERE F.FAT_TIPO = 1 AND R.REC_FAT = F.FAT_CODIGO AND F.FAT_CODIGO = PF.PF_FAT AND R.REC_CAI = :COD_CAIXA
     INTO :DESCONTO_VENDA;
     IF (:DESCONTO_VENDA IS NULL) THEN
       DESCONTO_VENDA = 0;
     /*RECEBIMENTOS*/
     SELECT SUM(RP_DINHEIRO), SUM(RP_CHEQUE)
     FROM RECEBIMENTOS, REC_PGM
     WHERE REC_CODIGO = RP_REC AND RP_CAI = :COD_CAIXA AND RP_CAI <> REC_CAI
     INTO :RECEBD, :RECEBC;
     IF (:RECEBD IS NULL) THEN
       RECEBD = 0;
     IF (:RECEBC IS NULL) THEN
       RECEBC = 0;
     RECEBIMENTOS = RECEBD+RECEBC;
     TOTALENTRADAS = :VENDAVISTA + :VENDAPRAZO + :RECEBIMENTOS;
     /*COMPRAS A VISTA*/
     SELECT SUM(PAG_VALOR+PAG_JUROS-PAG_DESCONTOS)
     FROM FATURAMENTO2, PAGAMENTOS
     WHERE FAT2_TIPO = 1 AND PAG_FAT2 = FAT2_CODIGO AND FAT2_DATA = PAG_VENCIMENTO AND PAG_CAI = :COD_CAIXA
     INTO :COMPRAVISTA;
     IF (:COMPRAVISTA IS NULL) THEN
       COMPRAVISTA = 0;
     SELECT SUM(PP_DINHEIRO+PP_CHEQUE)
     FROM FATURAMENTO2, PAGAMENTOS, PAG_PGM
     WHERE FAT2_TIPO = 1 AND PAG_FAT2 = FAT2_CODIGO AND PP_PAG = PAG_CODIGO AND FAT2_DATA < PAG_VENCIMENTO AND
     PP_DATAPGM = FAT2_DATA AND PAG_CAI = :COD_CAIXA
     INTO :VALORPG;
     IF (:VALORPG IS NULL) THEN
       VALORPG = 0;
     COMPRAVISTA = COMPRAVISTA+VALORPG;
     /*COMPRAS A PRAZO*/
     SELECT SUM(PAG_VALOR+PAG_JUROS-PAG_DESCONTOS)
     FROM FATURAMENTO2, PAGAMENTOS
     WHERE FAT2_TIPO = 1 AND PAG_FAT2 = FAT2_CODIGO AND FAT2_DATA < PAG_VENCIMENTO AND  PAG_CAI = :COD_CAIXA
     INTO :COMPRAPRAZO;
     IF (:COMPRAPRAZO IS NULL) THEN
       COMPRAPRAZO = 0;
     COMPRAPRAZO = COMPRAPRAZO-VALORPG;
     /*DESPESAS A VISTA*/
     SELECT SUM(PAG_VALOR+PAG_JUROS-PAG_DESCONTOS)
     FROM FATURAMENTO2, PAGAMENTOS
     WHERE FAT2_TIPO = 2 AND PAG_FAT2 = FAT2_CODIGO AND FAT2_DATA = PAG_VENCIMENTO AND  PAG_CAI = :COD_CAIXA
     INTO :DESPESAVISTA;
     IF (:DESPESAVISTA IS NULL) THEN
       DESPESAVISTA = 0;
     SELECT SUM(PP_DINHEIRO+PP_CHEQUE)
     FROM FATURAMENTO2, PAGAMENTOS, PAG_PGM
     WHERE FAT2_TIPO = 2 AND PAG_FAT2 = FAT2_CODIGO AND PP_PAG = PAG_CODIGO AND FAT2_DATA < PAG_VENCIMENTO AND
     PP_DATAPGM = FAT2_DATA AND PAG_CAI = :COD_CAIXA
     INTO :VALORPG;
     IF (:VALORPG IS NULL) THEN
       VALORPG = 0;
     DESPESAVISTA = DESPESAVISTA+VALORPG;
     /*DESPESAS A PRAZO*/
     SELECT SUM(PAG_VALOR+PAG_JUROS-PAG_DESCONTOS)
     FROM FATURAMENTO2, PAGAMENTOS
     WHERE FAT2_TIPO = 2 AND PAG_FAT2 = FAT2_CODIGO AND FAT2_DATA < PAG_VENCIMENTO AND  PAG_CAI = :COD_CAIXA
     INTO :DESPESAPRAZO;
     IF (:DESPESAPRAZO IS NULL) THEN
       DESPESAPRAZO = 0;
     DESPESAPRAZO = DESPESAPRAZO-VALORPG;
     /*TRIBUTACOES A VISTA*/
     SELECT SUM(PAG_VALOR+PAG_JUROS-PAG_DESCONTOS)
     FROM FATURAMENTO2, PAGAMENTOS
     WHERE FAT2_TIPO = 3 AND PAG_FAT2 = FAT2_CODIGO AND FAT2_DATA = PAG_VENCIMENTO AND  PAG_CAI = :COD_CAIXA
     INTO :TRIBUTACOESVISTA;
     IF (:TRIBUTACOESVISTA IS NULL) THEN
       TRIBUTACOESVISTA = 0;
     SELECT SUM(PP_DINHEIRO+PP_CHEQUE)
     FROM FATURAMENTO2, PAGAMENTOS, PAG_PGM
     WHERE FAT2_TIPO = 3 AND PAG_FAT2 = FAT2_CODIGO AND PP_PAG = PAG_CODIGO AND FAT2_DATA < PAG_VENCIMENTO AND
     PP_DATAPGM = FAT2_DATA AND PAG_CAI = :COD_CAIXA
     INTO :VALORPG;
     IF (:VALORPG IS NULL) THEN
       VALORPG = 0;
     TRIBUTACOESVISTA = TRIBUTACOESVISTA+VALORPG;
     /*TRIBUTACOES A PRAZO*/
     SELECT SUM(PAG_VALOR+PAG_JUROS-PAG_DESCONTOS)
     FROM FATURAMENTO2, PAGAMENTOS
     WHERE FAT2_TIPO = 3 AND PAG_FAT2 = FAT2_CODIGO AND FAT2_DATA < PAG_VENCIMENTO AND  PAG_CAI = :COD_CAIXA
     INTO :TRIBUTACOESPRAZO;
     IF (:TRIBUTACOESPRAZO IS NULL) THEN
       TRIBUTACOESPRAZO = 0;
     TRIBUTACOESPRAZO = TRIBUTACOESPRAZO-VALORPG;
     /*FRETES A VISTA*/
     SELECT SUM(PAG_VALOR+PAG_JUROS-PAG_DESCONTOS)
     FROM FATURAMENTO2, PAGAMENTOS
     WHERE FAT2_TIPO = 4 AND PAG_FAT2 = FAT2_CODIGO AND FAT2_DATA = PAG_VENCIMENTO AND  PAG_CAI = :COD_CAIXA
     INTO :FRETEVISTA;
     IF (:FRETEVISTA IS NULL) THEN
       FRETEVISTA = 0;
     SELECT SUM(PP_DINHEIRO+PP_CHEQUE)
     FROM FATURAMENTO2, PAGAMENTOS, PAG_PGM
     WHERE FAT2_TIPO = 4 AND PAG_FAT2 = FAT2_CODIGO AND PP_PAG = PAG_CODIGO AND FAT2_DATA < PAG_VENCIMENTO AND
     PP_DATAPGM = FAT2_DATA AND PAG_CAI = :COD_CAIXA
     INTO :VALORPG;
     IF (:VALORPG IS NULL) THEN
       VALORPG = 0;
     FRETEVISTA = FRETEVISTA+VALORPG;
     /*FRETES A PRAZO*/
     SELECT SUM(PAG_VALOR+PAG_JUROS-PAG_DESCONTOS)
     FROM FATURAMENTO2, PAGAMENTOS
     WHERE FAT2_TIPO = 4 AND PAG_FAT2 = FAT2_CODIGO AND FAT2_DATA < PAG_VENCIMENTO AND  PAG_CAI = :COD_CAIXA
     INTO :FRETEPRAZO;
     IF (:FRETEPRAZO IS NULL) THEN
       FRETEPRAZO = 0;
     FRETEPRAZO = FRETEPRAZO-VALORPG;
     /*PAGAMENTOS*/
     SELECT SUM(PP_DINHEIRO+PP_CHEQUE)
     FROM PAGAMENTOS, PAG_PGM
     WHERE PAG_CODIGO = PP_PAG AND PP_CAI = :COD_CAIXA AND PP_CAI <> PAG_CAI
     INTO :PAGAMENTOS;
     IF (:PAGAMENTOS IS NULL) THEN
       PAGAMENTOS = 0;
     TOTALSAIDAS = :COMPRAVISTA + :COMPRAPRAZO + :DESPESAVISTA + :DESPESAPRAZO + :TRIBUTACOESVISTA + :TRIBUTACOESPRAZO + :FRETEVISTA + 
:FRETEPRAZO + :PAGAMENTOS;
END^


ALTER PROCEDURE GERA_ACESSO
RETURNS (
    CODIGO INTEGER)
AS
BEGIN
     CODIGO = GEN_ID(GEN_ACE, 1);
END^


ALTER PROCEDURE GERA_VER_CODIGO
RETURNS (
    CODIGO INTEGER)
AS
begin
  /* Procedure Text */
    SELECT MIN(VER_CODIGO) FROM VERIFICA WHERE VER_ESTADO = 1 AND VER_CODIGO < 11
    INTO :CODIGO;
    if (:CODIGO IS NULL) then
    BEGIN
       CODIGO = 11;
    END
        
END^


ALTER PROCEDURE INCREMENTA (
    TABELA VARCHAR(20))
RETURNS (
    INC_CODIGO INTEGER)
AS
DECLARE VARIABLE X INTEGER;
DECLARE VARIABLE Y INTEGER;
BEGIN
     IF (TABELA = 'CLIENTES') THEN
     BEGIN
      SELECT COUNT(CLI_CODIGO), MAX(CLI_CODIGO) FROM CLIENTES
      INTO : X, : Y;
      IF (X = 0) THEN
       INC_CODIGO = 1;
      ELSE INC_CODIGO = Y + 1;
     END
     ELSE IF (TABELA = 'DEPENDENTES') THEN
     BEGIN
      SELECT COUNT(DEP_CODIGO), MAX(DEP_CODIGO) FROM DEPENDENTES
      INTO : X, : Y;
      IF (X = 0) THEN
       INC_CODIGO = 1;
      ELSE INC_CODIGO = Y + 1;
     END
     ELSE IF (TABELA = 'FORNECEDORES') THEN
     BEGIN
      SELECT COUNT(FOR_CODIGO), MAX(FOR_CODIGO) FROM FORNECEDORES
      INTO : X, : Y;
      IF (X = 0) THEN
       INC_CODIGO = 1;
      ELSE INC_CODIGO = Y + 1;
     END
     ELSE IF (TABELA = 'GRUPOS') THEN
     BEGIN
      SELECT COUNT(GRU_CODIGO), MAX(GRU_CODIGO) FROM GRUPOS
      INTO : X, : Y;
      IF (X = 0) THEN
       INC_CODIGO = 1;
      ELSE INC_CODIGO = Y + 1;
     END
     ELSE IF (TABELA = 'ESTOQUE') THEN
     BEGIN
      SELECT COUNT(EST_CODIGO), MAX(EST_CODIGO) FROM ESTOQUE
      INTO : X, : Y;
      IF (X = 0) THEN
       INC_CODIGO = 1;
      ELSE INC_CODIGO = Y + 1;
     END
     ELSE IF (TABELA = 'PRODUTOS') THEN
     BEGIN
      SELECT COUNT(PRO_CODIGO), MAX(PRO_CODIGO) FROM PRODUTOS
      INTO : X, : Y;
      IF (X = 0) THEN
       INC_CODIGO = 1;
      ELSE INC_CODIGO = Y + 1;
     END
     ELSE IF (TABELA = 'FUNCIONARIOS') THEN
     BEGIN
      SELECT COUNT(FUN_CODIGO), MAX(FUN_CODIGO) FROM FUNCIONARIOS
      INTO : X, : Y;
      IF (X = 0) THEN
       INC_CODIGO = 1;
      ELSE INC_CODIGO = Y + 1;
     END
     ELSE IF (TABELA = 'CONTAS') THEN
     BEGIN
      SELECT COUNT(CON_CODIGO), MAX(CON_CODIGO) FROM CONTAS
      INTO : X, : Y;
      IF (X = 0) THEN
       INC_CODIGO = 1;
      ELSE INC_CODIGO = Y + 1;
     END
     ELSE IF (TABELA = 'DESPESAS') THEN
