     END
     ELSE IF (TABELA = 'SUB_DES') THEN
     BEGIN
      SELECT COUNT(SUD_CODIGO), MAX(SUD_CODIGO) FROM SUB_DES
      INTO : X, : Y;
      IF (X = 0) THEN
       INC_CODIGO = 1;
      ELSE INC_CODIGO = Y + 1;
     END
     ELSE IF (TABELA = 'TRANSPORTADORAS') THEN
     BEGIN
      SELECT COUNT(TRA_CODIGO), MAX(TRA_CODIGO) FROM TRANSPORTADORAS
      INTO : X, : Y;
      IF (X = 0) THEN
        INC_CODIGO = 1;
      ELSE INC_CODIGO = Y + 1;
     END
     ELSE IF (TABELA = 'CONVERSOES') THEN
     BEGIN
      SELECT COUNT(CONV_CODIGO), MAX(CONV_CODIGO) FROM CONVERSOES
      INTO : X, : Y;
      IF (X = 0) THEN
        INC_CODIGO = 1;
      ELSE INC_CODIGO = Y + 1;
     END
     ELSE IF (TABELA = 'CONV_ALTERNATIVO') THEN
     BEGIN
      SELECT COUNT(CA_CODIGO), MAX(CA_CODIGO) FROM CONV_ALTERNATIVO
      INTO : X, : Y;
      IF (X = 0) THEN
