      ELSE INC_CODIGO = Y + 1;
     END
     ELSE IF (TABELA = 'AGENDA') THEN
     BEGIN
      SELECT COUNT(AGE_CODIGO), MAX(AGE_CODIGO) FROM AGENDA
      INTO : X, : Y;
      IF (X = 0) THEN
        INC_CODIGO = 1;
      ELSE INC_CODIGO = Y + 1;
     END
     ELSE IF (TABELA = 'USUARIOS') THEN
     BEGIN
      SELECT COUNT(USU_CODIGO), MAX(USU_CODIGO) FROM USUARIOS
      INTO : X, : Y;
      IF (X = 0) THEN
        INC_CODIGO = 1;
      ELSE INC_CODIGO = Y + 1;
     END
     ELSE IF (TABELA = 'TIPO') THEN
     BEGIN
      SELECT COUNT(TIP_CODIGO), MAX(TIP_CODIGO) FROM TIPO
      INTO : X, : Y;
      IF (X = 0) THEN
       INC_CODIGO = 1;
      ELSE INC_CODIGO = Y + 1;
     END
     ELSE IF (TABELA = 'MAQ_IMP') THEN
     BEGIN
      SELECT COUNT(MI_CODIGO), MAX(MI_CODIGO) FROM MAQ_IMP
      INTO : X, : Y;
      IF (X = 0) THEN
       INC_CODIGO = 1;
      ELSE INC_CODIGO = Y + 1;
     END
     ELSE IF (TABELA = 'CLI_MI') THEN
     BEGIN
      SELECT COUNT(CM_CODIGO), MAX(CM_CODIGO) FROM CLI_MI
      INTO : X, : Y;
      IF (X = 0) THEN
       INC_CODIGO = 1;
      ELSE INC_CODIGO = Y + 1;
     END
     ELSE IF (TABELA = 'BAL_PAT') THEN
     BEGIN
      SELECT COUNT(BP_CODIGO), MAX(BP_CODIGO) FROM BAL_PAT
      INTO : X, : Y;
      IF (X = 0) THEN
       INC_CODIGO = 1;
      ELSE INC_CODIGO = Y + 1;
     END
     ELSE IF (TABELA = 'FINANCIAMENTOS') THEN
     BEGIN
      SELECT COUNT(FIN_CODIGO), MAX(FIN_CODIGO) FROM FINANCIAMENTOS
      INTO : X, : Y;
      IF (X = 0) THEN
       INC_CODIGO = 1;
      ELSE INC_CODIGO = Y + 1;
     END
     ELSE IF (TABELA = 'TIPO_PGM') THEN
     BEGIN
      SELECT COUNT(TP_CODIGO), MAX(TP_CODIGO) FROM TIPO_PGM
      INTO : X, : Y;
      IF (X = 0) THEN
       INC_CODIGO = 1;
      ELSE INC_CODIGO = Y + 1;
     END
     ELSE IF (TABELA = 'RNO_DNO') THEN
     BEGIN
      SELECT COUNT(RD_CODIGO), MAX(RD_CODIGO) FROM RNO_DNO
      INTO : X, : Y;
      IF (X = 0) THEN
       INC_CODIGO = 1;
      ELSE INC_CODIGO = Y + 1;
     END
END^


ALTER PROCEDURE INCREMENTA_ESTOQUE (
    COD_COMPRA INTEGER,
    COD_CONF INTEGER,
    VALORNF FLOAT,
    FRETE FLOAT,
    ICMS FLOAT,
    DATA DATE,
    FORNECEDOR INTEGER,
    DARF FLOAT)
AS
DECLARE VARIABLE QUANTIDADE FLOAT;
DECLARE VARIABLE QUANTIDADE2 FLOAT;
DECLARE VARIABLE VALOR FLOAT;
DECLARE VARIABLE VALORCM FLOAT;
DECLARE VARIABLE NVALORCM FLOAT;
DECLARE VARIABLE CUSTOF FLOAT;
DECLARE VARIABLE FATURAMENTO FLOAT;
DECLARE VARIABLE PORCENTAGEM FLOAT;
DECLARE VARIABLE PORCENTAGEM2 FLOAT;
DECLARE VARIABLE PORCENTAGEM3 FLOAT;
DECLARE VARIABLE LUCROL FLOAT;
DECLARE VARIABLE PRODUTO INTEGER;
DECLARE VARIABLE COD_CE INTEGER;
DECLARE VARIABLE DEPRECIACAO FLOAT;
DECLARE VARIABLE INADIMPLENCIA FLOAT;
BEGIN
    SELECT CONF_CUSTOF, CONF_FATURAMENTO, CONF_LUCROL, CONF_DEPRECIACAO, CONF_INADIMPLENCIA FROM CONFIGURACOES WHERE CONF_CODIGO = :Cod_Conf
    INTO :CustoF, :Faturamento, :LucroL, :Depreciacao, :Inadimplencia;
    FOR SELECT CE_QUANTIDADE, CE_PRO, CE_VALOR, CE_CODIGO FROM COM_EST WHERE CE_COM = :COD_COMPRA
    INTO :Quantidade, :Produto, :Valor, :Cod_CE DO
    BEGIN
     Porcentagem = (((100 + (Frete/ValorNF)*100 + (ICMS/ValorNF)*100 + (DARF/ValorNF)*100)/(1 - (((:CustoF + :Depreciacao + :Inadimplencia)/:Faturamento) + 
(:LucroL/100))))/100)*1.27;
     Porcentagem2 = ((100 + (Frete/ValorNF)*100 + (ICMS/ValorNF)*100 + (DARF/ValorNF)*100)/(1 - (((:CustoF + :Depreciacao + :Inadimplencia)/:Faturamento))))/100;
     Porcentagem3 = (100 + (Frete/ValorNF)*100 + (ICMS/ValorNF)*100 + (DARF/ValorNF)*100)/100;
     SELECT PRO_QUANTIDADE, PRO_VALORCM FROM PRODUTOS WHERE PRO_CODIGO = :Produto
     INTO :Quantidade2, :VALORCM;
     IF (:Quantidade + :Quantidade2 = 0) THEN
     BEGIN
      UPDATE PRODUTOS SET PRO_FOR = :FORNECEDOR, PRO_DATAUA = :Data, PRO_DATAUC = :Data, PRO_VALORC = CAST((:Valor/:Quantidade) AS NUMERIC(9,4)), 
PRO_VALORCM = CAST(((PRO_VALORCM*0) + :Valor)/(:Quantidade) AS NUMERIC(9,4)),
      PRO_VALORL = CAST(((PRO_VALORL*0) + (((:Valor/:Quantidade)*:Porcentagem2)*:Quantidade))/(:Quantidade) AS NUMERIC(9,4)),
      PRO_VALORS = CAST(((((:Valor/:Quantidade)*:Porcentagem)*:Quantidade) + (PRO_VALORV*0))/(:Quantidade) AS NUMERIC(9,2)),
      PRO_VALORF = CAST(((PRO_VALORF*0) + (((:Valor/:Quantidade)*:Porcentagem3)*:Quantidade))/(:Quantidade) AS NUMERIC(9,4)),
      PRO_QUANTIDADE = PRO_QUANTIDADE + :Quantidade
      WHERE PRO_CODIGO = :Produto;
      NVALORCM = CAST(((VALORCM*0) + :Valor)/(:Quantidade) AS NUMERIC(9,4));
     END
     ELSE
     BEGIN
      UPDATE PRODUTOS SET PRO_FOR = :FORNECEDOR, PRO_DATAUA = :Data, PRO_DATAUC = :Data, PRO_VALORC = CAST((:Valor/:Quantidade) AS NUMERIC(9,4)), 
PRO_VALORCM = CAST(((PRO_VALORCM*PRO_QUANTIDADE) + :Valor)/(PRO_QUANTIDADE + :Quantidade) AS NUMERIC(9,4)),
      PRO_VALORS = CAST((((PRO_VALORL*PRO_QUANTIDADE) + (((:Valor/:Quantidade)*:Porcentagem2)*:Quantidade))/(PRO_QUANTIDADE + :Quantidade) + 
(((PRO_VALORL*PRO_QUANTIDADE) + (((:Valor/:Quantidade)*:Porcentagem2)*:Quantidade))/(PRO_QUANTIDADE + :Quantidade)*(:LUCROL/100)))*1.25 AS NUMERIC(9,2)),
      PRO_VALORL = CAST(((PRO_VALORL*PRO_QUANTIDADE) + (((:Valor/:Quantidade)*:Porcentagem2)*:Quantidade))/(PRO_QUANTIDADE + :Quantidade) AS NUMERIC(9,4)),
      PRO_VALORF = CAST(((PRO_VALORF*PRO_QUANTIDADE) + (((:Valor/:Quantidade)*:Porcentagem3)*:Quantidade))/(PRO_QUANTIDADE + :Quantidade) AS NUMERIC(9,4)),
      PRO_QUANTIDADE = PRO_QUANTIDADE + :Quantidade
      WHERE PRO_CODIGO = :Produto;
      NVALORCM = CAST(((VALORCM*Quantidade2) + :Valor)/(:Quantidade2 + :Quantidade) AS NUMERIC(9,4));
     END
     UPDATE COM_EST SET CE_NVALORCM = :NVALORCM WHERE CE_CODIGO = :Cod_CE;
    END
END^


