    FAT2 TYPE OF COLUMN ADIANTAMENTO_FOLHA.AF_FAT2,
    OBS TYPE OF COLUMN ADIANTAMENTO_FOLHA.AF_OBS)
AS
BEGIN
     INSERT INTO ADIANTAMENTO_FOLHA (AF_CODIGO, AF_DATA, AF_VALOR, AF_FOL, AF_FAT2, AF_DATAC, AF_OBS)
     VALUES(:CODIGO, :DATA, :VALOR, :FOL, :FAT2, '01/01/1900', :OBS);
END^


