     INSERT INTO CHEQUES (CHE_CODIGO, CHE_BANCO, CHE_AGENCIA, CHE_CONTA, CHE_NCHEQUE, CHE_VALOR, CHE_VENCIMENTO, CHE_ESTADO, CHE_DATA, 
     CHE_REC_PAG, CHE_CON)
     VALUES(:CODIGO, :BANCO, :AGENCIA, :CONTA, :NCHEQUE, :VALOR, :VENCIMENTO, :ESTADO, :DATA, :REC_PAG, :CON);
END^


ALTER PROCEDURE INSERE_COM_EST (
    CODIGO INTEGER,
    VALOR FLOAT,
    QUANTIDADE FLOAT,
    IPI FLOAT,
    PRO INTEGER,
    COM INTEGER,
    VALORC FLOAT,
    VALORCM FLOAT,
    VALORM FLOAT,
    VALOROP FLOAT,
    VALORV FLOAT,
    COD_GRADE INTEGER,
    QTD_ESTOQUE NUMERIC(9,2),
    QTD_DEVOLVIDA NUMERIC(9,2))
RETURNS (
    QUANTIDADEA NUMERIC(9,2))
AS
BEGIN
     IF (COD_GRADE IS NOT NULL) THEN
     BEGIN
        SELECT GRA_QUANTIDADE FROM GRADES WHERE GRA_CODIGO = :COD_GRADE
        INTO :QUANTIDADEA;
        IF (:QUANTIDADEA IS NULL) THEN
            QUANTIDADEA = 0;
     END ELSE
     BEGIN
         SELECT PRO_QUANTIDADE FROM PRODUTOS WHERE PRO_CODIGO = :PRO
         INTO :QUANTIDADEA;
         IF (:QUANTIDADEA IS NULL) THEN
            QUANTIDADEA = 0;
     END
     INSERT INTO COM_EST(CE_CODIGO, CE_VALOR, CE_QUANTIDADE, CE_IPI, CE_PRO, CE_COM,
     CE_VALORC, CE_VALORCM, CE_VALORM, CE_VALOROP, CE_VALORV, CE_GRADE, CE_NVALORCM, CE_DIFERENCA, CE_QTD_ESTOQUE, CE_QTD_DEVOLVIDA, 
CE_EDITADO)
     VALUES(:CODIGO, :VALOR, :QUANTIDADE, :IPI, :PRO, :COM, :VALORC, :VALORCM, :VALORM, :VALOROP, :VALORV, :COD_GRADE, 0, 0, :QTD_ESTOQUE, 
:QTD_DEVOLVIDA, 'N');
END^


