    CODIGO TYPE OF COLUMN FATURAMENTOS.FAT_CODIGO,
    CLI TYPE OF COLUMN FATURAMENTOS.FAT_CLI,
    VALOR TYPE OF COLUMN FATURAMENTOS.FAT_VALOR,
    PARCELAS TYPE OF COLUMN FATURAMENTOS.FAT_PARCELAS,
    JUROS TYPE OF COLUMN FATURAMENTOS.FAT_JUROS,
    TIPOPGM TYPE OF COLUMN FATURAMENTOS.FAT_TIPOPGM,
    TIPO TYPE OF COLUMN FATURAMENTOS.FAT_TIPO,
    DESCRICAO TYPE OF COLUMN FATURAMENTOS.FAT_DESCRICAO,
    DATA TYPE OF COLUMN FATURAMENTOS.FAT_DATA)
AS
BEGIN
     INSERT INTO FATURAMENTOS (FAT_CODIGO, FAT_CLI, FAT_VALOR, FAT_PARCELAS, FAT_JUROS, FAT_TIPOPGM, FAT_TIPO, FAT_DESCRICAO, FAT_DATA)
     VALUES(:CODIGO, :CLI, :VALOR, :PARCELAS, :JUROS, :TIPOPGM, :TIPO, :DESCRICAO, :DATA);
     if (:TIPO = 1) then
     begin
       UPDATE VENDAS SET VEN_FAT = :CODIGO WHERE VEN_CODIGO = :DESCRICAO;
     end
END^


ALTER PROCEDURE INSERE_FATURAMENTO2 (
    CODIGO TYPE OF COLUMN FATURAMENTO2.FAT2_CODIGO,
    TIPO TYPE OF COLUMN FATURAMENTO2.FAT2_TIPO,
    VALOR TYPE OF COLUMN FATURAMENTO2.FAT2_VALOR,
    DESCRICAO TYPE OF COLUMN FATURAMENTO2.FAT2_DESCRICAO,
    TIPOPGM TYPE OF COLUMN FATURAMENTO2.FAT2_TIPOPGM,
    PARCELAS TYPE OF COLUMN FATURAMENTO2.FAT2_PARCELAS,
    JUROS TYPE OF COLUMN FATURAMENTO2.FAT2_JUROS,
    DATA TYPE OF COLUMN FATURAMENTO2.FAT2_DATA,
    FDTF TYPE OF COLUMN FATURAMENTO2.FAT2_COD_FDTF)
AS
BEGIN
     INSERT INTO FATURAMENTO2 (FAT2_CODIGO, FAT2_TIPO, FAT2_VALOR, FAT2_DESCRICAO, FAT2_TIPOPGM, FAT2_PARCELAS, FAT2_JUROS, FAT2_DATA, FAT2_COD_FDTF)
     VALUES(:CODIGO, :TIPO, :VALOR, :DESCRICAO, :TIPOPGM, :PARCELAS, :JUROS, :DATA, :FDTF);
     if (:TIPO = 1) then
     begin
       UPDATE COMPRAS SET COM_FAT2 = :CODIGO WHERE COM_CODIGO = :DESCRICAO;
     end
     if (:TIPO = 2) then
     begin
       UPDATE CUSTOS SET CUST_FAT2 = :CODIGO WHERE CUST_CODIGO = :DESCRICAO;
     end
     if (:TIPO = 3) then
     begin
       UPDATE TRIBUTACOES SET TRI_FAT2 = :CODIGO WHERE TRI_CODIGO = :DESCRICAO;
     end
     if (:TIPO = 4) then
     begin
       UPDATE FRETES SET FRE_FAT2 = :CODIGO WHERE FRE_CODIGO = :DESCRICAO;
     end
END^


