ALTER PROCEDURE INSERE_HIS_PRO (
    CODIGO INTEGER,
    DATA DATE,
    PRO INTEGER,
    ORIGEM VARCHAR(30),
    DOC VARCHAR(15),
    QUANTIDADE NUMERIC(9,2),
    VALORC NUMERIC(9,2),
    VALORV NUMERIC(9,2),
    VALORCM NUMERIC(9,2),
    VALOROP NUMERIC(9,2),
    VALORM NUMERIC(9,2),
    TIPO1 VARCHAR(2),
    TIPO2 SMALLINT,
    QUANTIDADEA NUMERIC(9,2))
