ALTER PROCEDURE INSERE_MOVIMENTACAO (
    CODIGO TYPE OF COLUMN MOVIMENTACOES.MOV_CODIGO,
    CREDITO TYPE OF COLUMN MOVIMENTACOES.MOV_CREDITO,
    DEBITO TYPE OF COLUMN MOVIMENTACOES.MOV_DEBITO,
    DESCRICAO TYPE OF COLUMN MOVIMENTACOES.MOV_DESCRICAO,
    TIPO TYPE OF COLUMN MOVIMENTACOES.MOV_TIPO,
    DATA TYPE OF COLUMN MOVIMENTACOES.MOV_DATA,
    CON TYPE OF COLUMN MOVIMENTACOES.MOV_CON,
    DATAHORA TYPE OF COLUMN MOVIMENTACOES.MOV_DATAHORA,
    PLANO TYPE OF COLUMN MOVIMENTACOES.MOV_PLANO,
    NOME TYPE OF COLUMN MOVIMENTACOES.MOV_NOME,
    CAI TYPE OF COLUMN MOVIMENTACOES.MOV_CAI,
    TROCO TYPE OF COLUMN MOVIMENTACOES.MOV_TROCO,
    PDV INTEGER)
AS
declare variable SALDO_ANTERIOR numeric(12,4);
declare variable COD_CAIXA integer;
declare variable MAIOR_DATA_MOV timestamp;
BEGIN
    IF(:CON = 0) THEN
    BEGIN
      SELECT CAI_VALORD, CAI_CODIGO FROM CAIXA
      WHERE CAI_CODIGO = (SELECT MAX(CAI_CODIGO) FROM CAIXA WHERE CAI_PDV = :PDV)
      INTO :saldo_anterior, COD_CAIXA;
      UPDATE CAIXA SET CAI_VALORD = :SALDO_ANTERIOR + :CREDITO - :DEBITO
      WHERE CAI_CODIGO = :Cod_Caixa;  
      /*SE A DATA DA MOVIMENTACAO FOR MENOR QUE A DATA ATUAL*/
      IF(:DATA < CURRENT_DATE) THEN
      BEGIN
        /*BUSCO O MAIOR REGISTRO DA DATA ATUAL*/
        SELECT MAX(MOV_DATAHORA) FROM MOVIMENTACOES JOIN CAIXA ON MOV_CAI = CAI_CODIGO
        WHERE MOV_CON = 0 AND CAI_PDV = :PDV AND MOV_DATA = :DATA AND MOV_DATAHORA > :DATAHORA
        INTO :MAIOR_DATA_MOV;
        --SE HOUVER UM REGISTRO MAIOR NA MESMA DATA, O REGISTRO INSERIDO SERAH JOGADO
        --1 SEGUNDO DEPOIS DESSE MAIOR REGISTRO
        IF(:MAIOR_DATA_MOV IS NOT NULL) THEN
          DATAHORA = DATEADD(1 SECOND TO :MAIOR_DATA_MOV);
      END
    END ELSE
    BEGIN
      SELECT CON_SALDO FROM CONTAS WHERE CON_CODIGO = :CON
      INTO :SALDO_ANTERIOR;
      UPDATE CONTAS SET CON_SALDO = :SALDO_ANTERIOR + :CREDITO - :DEBITO
      WHERE CON_CODIGO = :CON;
      /*SE A DATA DA MOVIMENTACAO FOR MENOR QUE A DATA ATUAL*/
      IF(:DATA < CURRENT_DATE) THEN
      BEGIN
        /*BUSCO O MAIOR REGISTRO DA DATA ATUAL*/
        SELECT MAX(MOV_DATAHORA) FROM MOVIMENTACOES
        WHERE MOV_CON = :CON AND MOV_DATA = :DATA AND MOV_DATAHORA > :DATAHORA
        INTO :MAIOR_DATA_MOV;
        --SE HOUVER UM REGISTRO MAIOR NA MESMA DATA, O REGISTRO INSERIDO SERAH JOGADO
        --1 SEGUNDO DEPOIS DESSE MAIOR REGISTRO
        IF(:MAIOR_DATA_MOV IS NOT NULL) THEN
          DATAHORA = DATEADD(1 SECOND TO :MAIOR_DATA_MOV);
      END
    END
    INSERT INTO MOVIMENTACOES (MOV_CODIGO, MOV_CREDITO, MOV_DEBITO, MOV_DESCRICAO,
    MOV_TIPO, MOV_DATA, MOV_SALDOANT, MOV_CON, MOV_DATAHORA, MOV_ORDENA, MOV_PLANO,
    MOV_NOME, MOV_CAI, MOV_ESTADO, MOV_TROCO)
    VALUES(:CODIGO, :CREDITO, :DEBITO, :DESCRICAO, :TIPO, :DATA, :SALDO_ANTERIOR,
    :CON, :DATAHORA, GEN_ID(GEN_MOV2, 1), :PLANO, :NOME, :CAI, 'A', :TROCO);
END^


