ALTER PROCEDURE INSERE_NFC (
    CODIGO_SALVO INTEGER,
    CLIENTE INTEGER,
    NF INTEGER,
    C_F_O_P VARCHAR(8),
    DATA DATE,
    HORA TIME,
    DATA_SAIDA DATE,
    HORA_SAIDA TIME,
    BCICMS NUMERIC(12,4),
    VICMS NUMERIC(12,4),
    BCICMSSUB NUMERIC(9,2),
    VICMSSUB NUMERIC(9,2),
    VTPROD NUMERIC(12,4),
    VFRETE NUMERIC(9,2),
    VSEGURO NUMERIC(9,2),
    OUTRASDESP NUMERIC(9,2),
    VTIPI NUMERIC(9,2),
    VALOR NUMERIC(12,4),
    DESCONTO NUMERIC(9,2),
    TRANS_NOME VARCHAR(50),
    TRANS_FRETE CHAR(1),
    TRANS_PLACA VARCHAR(8),
    TRANS_UF_VEIC CHAR(2),
    TRANS_CPF_CNPJ VARCHAR(18),
    TRANS_ENDERECO VARCHAR(50),
    TRANS_MUNICIPIO VARCHAR(30),
    TRANS_UF CHAR(2),
    TRANS_INSCRICAO VARCHAR(20),
    TRANS_QUANTIDADE NUMERIC(9,2),
    TRANS_ESPECIE VARCHAR(30),
    TRANS_MARCA VARCHAR(30),
    TRANS_NUMERO VARCHAR(30),
    TRANS_PESOBRUTO NUMERIC(9,2),
    TRANS_PESOLIQ NUMERIC(9,2),
    FUN SMALLINT,
    MODELO VARCHAR(5),
    SERIE VARCHAR(5),
    CONDICAO_PGTO CHAR(1),
    OPER_CONSUM_FINAL CHAR(1),
    COMP_PRESENTE CHAR(1),
    NF_REFERENCIADAS VARCHAR(500),
    INF_COMP_FISCO BLOB SUB_TYPE 1 SEGMENT SIZE 80,
    INF_COMP_CONTRIBUINTE BLOB SUB_TYPE 1 SEGMENT SIZE 80,
    CPF_CLIENTE VARCHAR(18),
    NOME_CLIENTE VARCHAR(100))
RETURNS (
    NOVO_CODIGO INTEGER)
AS
BEGIN
    IF(:CODIGO_SALVO = 0) THEN
    BEGIN
      SELECT COALESCE(MAX(NFC_CODIGO), 0)+1 FROM NFC
      INTO :NOVO_CODIGO;
      INSERT INTO NFC(NFC_CODIGO, NFC_CLI, NFC_NF, NFC_CFOP, NFC_DATA, NFC_HORA, NFC_DATA_SAIDA,
      NFC_HORA_SAIDA, NFC_BCICMS, NFC_VICMS, NFC_BCICMSSUB, NFC_VICMSSUB, NFC_VTPROD,
      NFC_VFRETE, NFC_VSEGURO, NFC_OUTRASDESP, NFC_VTIPI, NFC_VALOR, NFC_DESCONTO,
      NFC_TRANS_NOME, NFC_TRANS_FRETE, NFC_TRANS_PLACA, NFC_TRANS_UF_VEIC, NFC_TRANS_CPF_CNPJ,
      NFC_TRANS_ENDERECO, NFC_TRANS_MUNICIPIO, NFC_TRANS_UF, NFC_TRANS_INSCRICAO,
      NFC_TRANS_QUANTIDADE, NFC_TRANS_ESPECIE, NFC_TRANS_MARCA, NFC_TRANS_NUMERO,
      NFC_TRANS_PESOBRUTO, NFC_TRANS_PESOLIQ, NFC_FUN, NFC_MODELO, NFC_SERIE, NFC_CONDICAO_PGTO,
      NFC_OPER_CONSUM_FINAL, NFC_COMP_PRESENTE, NFC_NF_REFERENCIADAS, NFC_INF_COMP_FISCO,
      NFC_INF_COMP_CONTRIBUINTE, NFC_CPF_CLIENTE, NFC_NOME_CLIENTE)
      VALUES(:NOVO_CODIGO, :CLIENTE, :NF, :C_F_O_P, :DATA, :HORA, :DATA_SAIDA, :HORA_SAIDA,
      :BCICMS, :VICMS, :BCICMSSUB, :VICMSSUB, :VTPROD, :VFRETE, :VSEGURO, :OUTRASDESP, 
      :VTIPI, :VALOR, :DESCONTO, :TRANS_NOME, :TRANS_FRETE, :TRANS_PLACA, :TRANS_UF_VEIC, 
      :TRANS_CPF_CNPJ, :TRANS_ENDERECO, :TRANS_MUNICIPIO, :TRANS_UF, :TRANS_INSCRICAO, 
      :TRANS_QUANTIDADE, :TRANS_ESPECIE, :TRANS_MARCA, :TRANS_NUMERO, :TRANS_PESOBRUTO, 
      :TRANS_PESOLIQ, :FUN, :MODELO, :SERIE, :CONDICAO_PGTO, :OPER_CONSUM_FINAL, 
      :COMP_PRESENTE, :NF_REFERENCIADAS, :INF_COMP_FISCO, :INF_COMP_CONTRIBUINTE,
      :CPF_CLIENTE, :NOME_CLIENTE);
    END ELSE
    BEGIN
      NOVO_CODIGO = :CODIGO_SALVO;
      UPDATE NFC SET NFC_CLI = :CLIENTE, NFC_NF = :NF, NFC_CFOP = :C_F_O_P, NFC_DATA = :DATA,
      NFC_HORA = :HORA,
      NFC_DATA_SAIDA = :DATA_SAIDA, NFC_HORA_SAIDA = :HORA_SAIDA, NFC_BCICMS = :BCICMS,
      NFC_VICMS = :VICMS, NFC_BCICMSSUB = :BCICMSSUB, NFC_VICMSSUB = :VICMSSUB,
      NFC_VTPROD = :VTPROD, NFC_VFRETE = :VFRETE, NFC_VSEGURO = :VSEGURO,
      NFC_OUTRASDESP = :OUTRASDESP, NFC_VTIPI = :VTIPI, NFC_VALOR = :VALOR,
      NFC_DESCONTO = :DESCONTO, NFC_TRANS_NOME = :TRANS_NOME, NFC_TRANS_FRETE = :TRANS_FRETE,
      NFC_TRANS_PLACA = :TRANS_PLACA, NFC_TRANS_UF_VEIC = :TRANS_UF_VEIC,
      NFC_TRANS_CPF_CNPJ = :TRANS_CPF_CNPJ, NFC_TRANS_ENDERECO = :TRANS_ENDERECO,
      NFC_TRANS_MUNICIPIO = :TRANS_MUNICIPIO, NFC_TRANS_UF = :TRANS_UF,
      NFC_TRANS_INSCRICAO = :TRANS_INSCRICAO, NFC_TRANS_QUANTIDADE = :TRANS_QUANTIDADE,
      NFC_TRANS_ESPECIE = :TRANS_ESPECIE, NFC_TRANS_MARCA = :TRANS_MARCA,
      NFC_TRANS_NUMERO = :TRANS_NUMERO, NFC_TRANS_PESOBRUTO = :TRANS_PESOBRUTO,
      NFC_TRANS_PESOLIQ = :TRANS_PESOLIQ, NFC_FUN = :FUN, NFC_MODELO = :MODELO,
      NFC_SERIE = :SERIE, NFC_CONDICAO_PGTO = :CONDICAO_PGTO,
      NFC_OPER_CONSUM_FINAL = :OPER_CONSUM_FINAL, NFC_COMP_PRESENTE = :COMP_PRESENTE,
      NFC_NF_REFERENCIADAS = :NF_REFERENCIADAS, NFC_INF_COMP_FISCO = :INF_COMP_FISCO,
      NFC_INF_COMP_CONTRIBUINTE = :INF_COMP_CONTRIBUINTE,
      NFC_CPF_CLIENTE = :CPF_CLIENTE, NFC_NOME_CLIENTE = :NOME_CLIENTE
      WHERE NFC_CODIGO = :CODIGO_SALVO;
    END
END^


