    TRANS_MARCA TYPE OF COLUMN NOTAS_FISCAIS.NOT_TRANS_MARCA,
    TRANS_NUMERO TYPE OF COLUMN NOTAS_FISCAIS.NOT_TRANS_NUMERO,
    TRANS_PESOB TYPE OF COLUMN NOTAS_FISCAIS.NOT_TRANS_PESOBRUTO,
    TRANS_PESOL TYPE OF COLUMN NOTAS_FISCAIS.NOT_TRANS_PESOLIQ,
    INF_COMP TYPE OF COLUMN NOTAS_FISCAIS.NOT_INF_COMP,
    IC TYPE OF COLUMN NOTAS_FISCAIS.NOT_IC,
    ONF TYPE OF COLUMN NOTAS_FISCAIS.NOT_ONF,
    OBS TYPE OF COLUMN NOTAS_FISCAIS.NOT_OBS,
    MODELO TYPE OF COLUMN NOTAS_FISCAIS.NOT_MODELO,
    CHAVE_NFE TYPE OF COLUMN NOTAS_FISCAIS.NOT_CHAVE_NFE,
    OPER_CONSUM_FINAL TYPE OF COLUMN NOTAS_FISCAIS.NOT_OPER_CONSUM_FINAL,
    COMP_PRESENTE TYPE OF COLUMN NOTAS_FISCAIS.NOT_COMP_PRESENTE,
    NF_REFERENCIADAS TYPE OF COLUMN NOTAS_FISCAIS.NOT_NF_REFERENCIADAS,
    FATURA TYPE OF COLUMN NOTAS_FISCAIS.NOT_FAT,
    INSCRICAO TYPE OF COLUMN NOTAS_FISCAIS.NOT_INS,
    CONDICAO_PGTO TYPE OF COLUMN NOTAS_FISCAIS.NOT_CONDICAO_PGTO,
    IND_EMISSAO TYPE OF COLUMN NOTAS_FISCAIS.NOT_IND_EMISSAO,
    SERIE TYPE OF COLUMN NOTAS_FISCAIS.NOT_SERIE)
RETURNS (
    CODIGO INTEGER)
AS
BEGIN
    SELECT COALESCE(MAX(NOT_CODIGO), 0)+1 FROM NOTAS_FISCAIS
    INTO :CODIGO;
    INSERT INTO NOTAS_FISCAIS(NOT_CODIGO, NOT_CF, NOT_NF, NOT_CFOP, NOT_DATA, NOT_DATA_ES,
    NOT_HORA, NOT_BCICMS, NOT_VICMS, NOT_BCICMSSUB, NOT_VICMSSUB, NOT_VTPROD, NOT_VFRETE,
    NOT_VSEGURO, NOT_OUTRASDESP, NOT_VTIPI, NOT_VALOR, NOT_DESCONTO, NOT_TRANS_NOME,
    NOT_TRANS_FRETE, NOT_TRANS_PLACA, NOT_TRANS_UF_VEIC, NOT_TRANS_CPF_CNPJ,
    NOT_TRANS_ENDERECO, NOT_TRANS_MUNICIPIO, NOT_TRANS_UF, NOT_TRANS_INSCRICAO,
    NOT_TRANS_QUANTIDADE, NOT_TRANS_ESPECIE, NOT_TRANS_MARCA, NOT_TRANS_NUMERO,
    NOT_TRANS_PESOBRUTO, NOT_TRANS_PESOLIQ, NOT_INF_COMP, NOT_FUN, NOT_IC, NOT_ONF,
    NOT_OBS, NOT_MODELO, NOT_CHAVE_NFE, NOT_OPER_CONSUM_FINAL, NOT_COMP_PRESENTE,
    NOT_NF_REFERENCIADAS, NOT_FAT, NOT_INS, NOT_CONDICAO_PGTO, NOT_IND_EMISSAO,
    NOT_SERIE)
    VALUES(:CODIGO, :CLI_FOR, :NF, :NCFOP, :DATAEMISSAO, :DATA_ES, :HORA, :BCICMS, :VICMS,
    :BCICMSSUB, :VICMSSUB, :VTPROD, :VFRETE, :VSEGURO, :OUTRASDESP, :VTIPI, :VALOR,
    :DESCONTO, :TRANS_NOME, :TRANS_FRETE, :TRANS_PLACA, :TRANS_UF_VEIC, :TRANS_CPF_CNPJ,
    :TRANS_ENDERECO, :TRANS_MUNICIPIO, :TRANS_UF, :TRANS_INSCRICAO, :TRANS_QUANTIDADE,
    :TRANS_ESPECIE, :TRANS_MARCA, :TRANS_NUMERO, :TRANS_PESOB, :TRANS_PESOL, :INF_COMP,
    :FUN, :IC, :ONF, :OBS, :MODELO, :CHAVE_NFE, :OPER_CONSUM_FINAL, :COMP_PRESENTE,
    :NF_REFERENCIADAS, :FATURA, :INSCRICAO, :CONDICAO_PGTO, :IND_EMISSAO, :SERIE);
END^


