ALTER PROCEDURE PORC_JUROS_DESC (
    CODIGO INTEGER)
RETURNS (
    PORCENTAGEM FLOAT)
AS
DECLARE VARIABLE VALOR FLOAT;
DECLARE VARIABLE JUROS FLOAT;
DECLARE VARIABLE DESCONTOS FLOAT;
DECLARE VARIABLE SOMA FLOAT;
DECLARE VARIABLE VALORV FLOAT;
BEGIN
     SELECT SUM(R.REC_VALOR), SUM(R.REC_JUROS), SUM(R.REC_DESCONTOS)
     FROM RECEBIMENTOS R, FATURAMENTOS F, VENDAS V, VEN_EST VE
     WHERE V.VEN_CODIGO = VE.VE_VEN AND F.FAT_TIPO = 1 AND F.FAT_DESCRICAO = V.VEN_CODIGO AND
     F.FAT_CODIGO = R.REC_FAT AND VE.VE_CODIGO = :CODIGO
     INTO :VALOR, :JUROS, :DESCONTOS;
     SOMA = :VALOR + :JUROS - :DESCONTOS;
     SELECT V.VEN_VALOR
     FROM VENDAS V, VEN_EST VE
     WHERE V.VEN_CODIGO = VE.VE_VEN AND VE.VE_CODIGO = :CODIGO
     INTO :VALORV;
     IF (:VALORV > :SOMA) THEN
     BEGIN
          PORCENTAGEM = (:VALORV - :DESCONTOS)/:VALORV;
     END
     ELSE IF (:VALORV < :SOMA) THEN
     BEGIN
          PORCENTAGEM = (:VALOR +:JUROS)/:VALORV;
     END
END^


ALTER PROCEDURE REAJUSTA_LUCRO (
    CODIGO INTEGER,
    JUROS FLOAT,
    DESCONTOS FLOAT)
AS
DECLARE VARIABLE VENDA INTEGER;
DECLARE VARIABLE LUCRO FLOAT;
DECLARE VARIABLE VALOR FLOAT;
DECLARE VARIABLE PORCENTAGEM FLOAT;
DECLARE VARIABLE DIFERENCA FLOAT;
begin
  /* Procedure Text */
  SELECT SUM(VE.VE_LUCRO), SUM(VE.VE_VALOR) FROM VEN_EST VE, VENDAS V, FATURAMENTOS F, RECEBIMENTOS R
  WHERE VE.VE_VEN = V.VEN_CODIGO AND V.VEN_FAT = F.FAT_CODIGO AND F.FAT_CODIGO = R.REC_FAT AND R.REC_CODIGO = :CODIGO
  INTO :LUCRO, :VALOR;
  if (LUCRO > 0) then
  BEGIN
       if (JUROS > DESCONTOS) then
       BEGIN
            PORCENTAGEM = 1 + ((JUROS - DESCONTOS)/LUCRO);
            DIFERENCA = ((JUROS - DESCONTOS)/VALOR);
       END
       if (DESCONTOS > JUROS) then
       BEGIN
            PORCENTAGEM = 1 - ((DESCONTOS - JUROS)/LUCRO);
            DIFERENCA = -((DESCONTOS - JUROS)/VALOR);
       END
       if (DESCONTOS = JUROS) then
       BEGIN
            PORCENTAGEM = 1;
            DIFERENCA = 0;
       END
  END
  ELSE if (LUCRO < 0) then
  BEGIN
       if (JUROS > DESCONTOS) then
       BEGIN
            PORCENTAGEM = 1 + ((JUROS - DESCONTOS)/LUCRO);
            DIFERENCA = ((JUROS - DESCONTOS)/VALOR);
       END
       if (DESCONTOS > JUROS) then
       BEGIN
            PORCENTAGEM = 1 - ((DESCONTOS - JUROS)/LUCRO);
            DIFERENCA = -((DESCONTOS - JUROS)/VALOR);
       END
       if (DESCONTOS = JUROS) then
       BEGIN
            PORCENTAGEM = 1;
            DIFERENCA = 0;
       END
  END
  FOR SELECT VE.VE_CODIGO FROM VENDAS V, VEN_EST VE, FATURAMENTOS F, RECEBIMENTOS R
  WHERE VE.VE_VEN = V.VEN_CODIGO AND V.VEN_FAT = F.FAT_CODIGO AND F.FAT_CODIGO = R.REC_FAT AND R.REC_CODIGO = :CODIGO
  INTO :VENDA DO
  BEGIN
       UPDATE VEN_EST SET VE_LUCRO = (VE_LUCRO*:PORCENTAGEM), VE_DIFERENCA = VE_DIFERENCA + (VE_VALOR*:DIFERENCA)
       WHERE VE_CODIGO = :VENDA;
  END
  suspend;
end^


