ALTER PROCEDURE REL_COMPRA_SINT_ANAL (
    DATA1 DATE,
    DATA2 DATE)
RETURNS (
    COMPRA FLOAT,
    DESCONTOS FLOAT)
AS
BEGIN
     SELECT SUM(CE.CE_VALOR) FROM COMPRAS C, COM_EST CE WHERE C.COM_CODIGO = CE.CE_COM AND  ((COM_NATUREZA = 1) OR (COM_NATUREZA = 2) OR 
(COM_NATUREZA = 4))
     AND C.COM_DATAC = '01/01/1900' AND C.COM_DATA BETWEEN :DATA1 AND :DATA2
     INTO :COMPRA;
     SELECT SUM(P.PAG_DESCONTOS) FROM PAGAMENTOS P, FATURAMENTO2 F, COMPRAS C
     WHERE C.COM_CODIGO = F.FAT2_DESCRICAO AND F.FAT2_TIPO = 1 AND P.PAG_FAT2 = F.FAT2_CODIGO AND C.COM_DATA BETWEEN :DATA1 AND :DATA2
     INTO :DESCONTOS;
     IF (:COMPRA IS NULL) THEN
      COMPRA = 0;
     IF (:DESCONTOS IS NULL) THEN
      DESCONTOS = 0;
END^


ALTER PROCEDURE REL_COMPRA_SINTETICO (
    DATA1 DATE,
    DATA2 DATE)
RETURNS (
    SOMA NUMERIC(9,2),
    VISTA NUMERIC(9,2))
AS
DECLARE VARIABLE DINHEIRO NUMERIC(9,2);
DECLARE VARIABLE CHEQUE NUMERIC(9,2);
BEGIN
     SELECT SUM(CE.CE_VALOR) FROM COM_EST CE, COMPRAS C WHERE C.COM_CODIGO = CE.CE_COM
     AND C.COM_DATA BETWEEN :DATA1 AND :DATA2
     INTO :SOMA;
     SELECT SUM(PP.PP_DINHEIRO), SUM(PP.PP_CHEQUE)
     FROM COMPRAS C, FATURAMENTO2 F, PAGAMENTOS P, PAG_PGM PP
     WHERE C.COM_CODIGO = F.FAT2_DESCRICAO AND F.FAT2_TIPO = 1 AND F.FAT2_CODIGO = P.PAG_FAT2
     AND PP.PP_PAG = P.PAG_CODIGO AND C.COM_DATA = PP.PP_DATAPGM AND C.COM_DATA BETWEEN :DATA1 AND :DATA2
     INTO :DINHEIRO, :CHEQUE;
     if (SOMA IS NULL) then
      SOMA = 0;
     if (DINHEIRO IS NULL) then
      DINHEIRO = 0;
     if (CHEQUE IS NULL) then
      CHEQUE = 0;
     VISTA = DINHEIRO + CHEQUE;
END^


ALTER PROCEDURE REL_CONTA_RECEBER_A (
    CLIENTE INTEGER,
    DATA1 DATE,
    DATA2 DATE)
RETURNS (
    VALORPAGAR FLOAT,
    VALORPG FLOAT)
AS
DECLARE VARIABLE VALOR FLOAT;
DECLARE VARIABLE JUROS FLOAT;
DECLARE VARIABLE DESCONTOS FLOAT;
DECLARE VARIABLE DINHEIRO FLOAT;
DECLARE VARIABLE CHEQUE FLOAT;
BEGIN
     SELECT SUM(R.REC_VALOR), SUM(R.REC_JUROS), SUM(R.REC_DESCONTOS), SUM(RP.RP_DINHEIRO), SUM(RP.RP_CHEQUE) FROM FATURAMENTOS F, CLIENTES C, RECEBIMENTOS R, REC_PGM RP
     WHERE F.FAT_CLI = C.CLI_CODIGO AND F.FAT_CODIGO = R.REC_FAT AND R.REC_CODIGO = RP.RP_REC AND R.REC_ESTADO <> 3 AND C.CLI_CODIGO = :CLIENTE
     INTO :VALOR, :JUROS, :DESCONTOS, :DINHEIRO, :CHEQUE;
     VALORPAGAR = VALOR + JUROS - DESCONTOS;
     VALORPG = DINHEIRO + CHEQUE;
END^


ALTER PROCEDURE REL_VENDA_SINT_ANAL (
    DATA1 DATE,
    DATA2 DATE)
RETURNS (
    VENDA FLOAT,
    VENDAC FLOAT)
AS
declare variable VENDA_CANCELADA float;
declare variable VENDAD float;
BEGIN
     SELECT SUM(VE.VE_VALOR) FROM VENDAS V, VEN_EST VE WHERE V.VEN_CODIGO = VE.VE_VEN
     AND V.VEN_DATAC = '01/01/1900' AND V.VEN_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VENDA;
     SELECT SUM(VE.VE_VALOR), SUM(VE.VE_DIFERENCA)
     FROM VENDAS V, VEN_EST VE
     WHERE VEN_DATAC <> '01/01/1900' AND VEN_DATA BETWEEN :DATA1 AND :DATA2 AND VE.VE_VEN = V.VEN_CODIGO
     INTO :VENDA_CANCELADA, :VENDAD;
     if (:VENDA_CANCELADA IS NULL) then
      VENDA_CANCELADA = 0;
     if (:VENDAD IS NULL) then
      VENDAD = 0;
     VENDAC = VENDA_CANCELADA + VENDAD;
END^


ALTER PROCEDURE REL_VENDA_SINTETICO (
    DATA1 DATE,
    DATA2 DATE)
RETURNS (
    SOMA FLOAT,
    VISTA FLOAT)
AS
declare variable DINHEIRO float;
declare variable CHEQUE float;
declare variable VENDA float;
declare variable VENDAC float;
declare variable VENDA_CANCELADA float;
declare variable VENDAD float;
BEGIN
     SELECT SUM(VE.VE_VALOR) FROM VEN_EST VE, VENDAS V WHERE V.VEN_CODIGO = VE.VE_VEN
     AND V.VEN_DATAC = '01/01/1900' AND V.VEN_DATA BETWEEN :DATA1 AND :DATA2
     INTO :VENDA;
     if (:VENDA IS NULL) then
      VENDA = 0;
     SELECT SUM(VE.VE_VALOR), SUM(VE.VE_DIFERENCA)
     FROM VENDAS V, VEN_EST VE
     WHERE VEN_DATAC <> '01/01/1900' AND VEN_DATA BETWEEN :DATA1 AND :DATA2 AND VE.VE_VEN = V.VEN_CODIGO
     INTO :VENDA_CANCELADA, :VENDAD;
     if (:VENDA_CANCELADA IS NULL) then
      VENDA_CANCELADA = 0;
     if (:VENDAD IS NULL) then
      VENDAD = 0;
     VENDAC = VENDA_CANCELADA + VENDAD;
     SOMA = VENDA - VENDAC;
     SELECT SUM(RP.RP_DINHEIRO), SUM(RP.RP_CHEQUE)
     FROM VENDAS V, FATURAMENTOS F, RECEBIMENTOS R, REC_PGM RP
     WHERE V.VEN_FAT = F.FAT_CODIGO AND F.FAT_CODIGO = R.REC_FAT
     AND RP.RP_REC = R.REC_CODIGO AND V.VEN_DATA = RP.RP_DATAPGM AND V.VEN_DATAC = '01/01/1900' AND V.VEN_DATA BETWEEN :DATA1 AND :DATA2
     INTO :DINHEIRO, :CHEQUE;
     if (DINHEIRO IS NULL) then
      DINHEIRO = 0;
     if (CHEQUE IS NULL) then
      CHEQUE = 0;
     VISTA = DINHEIRO + CHEQUE;
END^


ALTER PROCEDURE SAIDA (
    TABELA VARCHAR(20))
RETURNS (
    CODIGO INTEGER)
AS
BEGIN
     IF (TABELA = 'COMPRAS') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_COM, 1);
     END
     ELSE IF (TABELA = 'COM_EST') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_CE, 1);
     END
     ELSE IF (TABELA = 'FATURAMENTO2') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_FAT2, 1);
     END
     ELSE IF (TABELA = 'PAGAMENTOS') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_PAG, 1);
     END
     ELSE IF (TABELA = 'PAG_PGM') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_PP, 1);
     END
     ELSE IF (TABELA = 'MOVIMENTACOES') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_MOV, 1);
     END
     ELSE IF (TABELA = 'CHEQUES') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_CHE, 1);
     END
     ELSE IF (TABELA = 'CUSTOS') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_CUST, 1);
     END
     ELSE IF (TABELA = 'TRIBUTACOES') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_TRI, 1);
     END
     ELSE IF (TABELA = 'TRI_COM') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_TC, 1);
     END
     ELSE IF (TABELA = 'FOLHAS') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_FOL, 1);
     END
     ELSE IF (TABELA = 'CUSTODIAS') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_CUS, 1);
     END
     ELSE IF (TABELA = 'CUS_CHE') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_CC, 1);
     END
     ELSE IF (TABELA = 'DEPOSITOS') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_DEP, 1);
     END
     ELSE IF (TABELA = 'DEP_CHE') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_DC, 1);
     END
     ELSE IF (TABELA = 'FRETES') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_FRE, 1);
     END
     ELSE IF (TABELA = 'SAQUES') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_SAQ, 1);
     END
     ELSE IF (TABELA = 'RETIRADAS') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_RET, 1);
     END
     ELSE IF (TABELA = 'TRANSACOES') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_TRAN, 1);
     END
     ELSE IF (TABELA = 'DEVOLUCAOI') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_DEVI, 1);
     END
     ELSE IF (TABELA = 'DEVI_EST') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_DE, 1);
     END
     ELSE IF (TABELA = 'ENCARGO_FOLHA') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_EF, 1);
     END
     ELSE IF (TABELA = 'HEXTRA') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_HEX, 1);
     END
     ELSE IF (TABELA = 'FERIAS_13') THEN
     BEGIN
      CODIGO = GEN_ID(GEN_F13, 1);
     END
END^


ALTER PROCEDURE SOMA_CAIXA (
    DATA1 TIMESTAMP,
    DATA2 TIMESTAMP,
    TIPO CHAR(1))
RETURNS (
    CREDITO FLOAT,
    DEBITO FLOAT)
AS
declare variable VALOR_CREDITO float;
declare variable VALOR_DEBITO float;
BEGIN
     if (:TIPO = 'S') then
     BEGIN
      SELECT SUM(MOV_CREDITO), SUM(MOV_DEBITO) FROM MOVIMENTACOES
      WHERE MOV_CON = 0 AND MOV_DATA BETWEEN :DATA1 AND :DATA2
      INTO :VALOR_CREDITO, :VALOR_DEBITO;
     END ELSE
     BEGIN
      SELECT SUM(MOV_CREDITO), SUM(MOV_DEBITO) FROM MOVIMENTACOES
      WHERE MOV_CON = 0 AND MOV_DATA BETWEEN :DATA1 AND :DATA2 AND MOV_ESTADO = 'A'
      INTO :VALOR_CREDITO, :VALOR_DEBITO;
     END
     CREDITO = :VALOR_CREDITO;
     DEBITO = :VALOR_DEBITO;
END^


ALTER PROCEDURE SOMA_FLUXO (
    PLANO VARCHAR(10),
    DATA1 DATE)
RETURNS (
    RECEBER NUMERIC(9,2))
AS
declare variable valor numeric(9,2);
declare variable juros numeric(9,2);
declare variable descontos numeric(9,2);
declare variable valorpg numeric(9,2);
declare variable dia1 integer;
begin
     RECEBER = 0;
     if (PLANO = '1.2') then
     begin
       for SELECT REC_VALOR, REC_JUROS, REC_DESCONTOS, SUM(RP_DINHEIRO+RP_CHEQUE)
       FROM RECEBIMENTOS, REC_PGM, FATURAMENTOS
       WHERE REC_CODIGO = RP_REC AND FAT_TIPO = 1 AND REC_FAT = FAT_CODIGO AND (REC_SITUACAO >= 0 AND REC_SITUACAO < 3) AND REC_ESTADO < 3
       AND REC_VENCIMENTO = :DATA1
       GROUP BY REC_VALOR, REC_JUROS, REC_DESCONTOS
       into :VALOR, :JUROS, :DESCONTOS, :VALORPG do
       begin
         if (VALOR IS NULL) then
          VALOR = 0;
         if (VALOR IS NULL) then
          JUROS = 0;
         if (VALOR IS NULL) then
          DESCONTOS = 0;
         if (VALOR IS NULL) then
          VALORPG = 0;
         RECEBER = RECEBER + (VALOR+JUROS-DESCONTOS-VALORPG);
       end
     end
     if (PLANO = '2.1') then
     begin
       for SELECT PAG_VALOR, PAG_JUROS, PAG_DESCONTOS, SUM(PP_DINHEIRO+PP_CHEQUE)
       FROM PAGAMENTOS, PAG_PGM, FATURAMENTO2
       WHERE PAG_CODIGO = PP_PAG AND FAT2_TIPO = 1 AND PAG_FAT2 = FAT2_CODIGO AND (PAG_SITUACAO >= 0 AND PAG_SITUACAO < 3) AND PAG_ESTADO < 3
       AND PAG_VENCIMENTO = :DATA1
       GROUP BY PAG_VALOR, PAG_JUROS, PAG_DESCONTOS
       into :VALOR, :JUROS, :DESCONTOS, :VALORPG do
       begin
         if (VALOR IS NULL) then
          VALOR = 0;
         if (VALOR IS NULL) then
          JUROS = 0;
         if (VALOR IS NULL) then
          DESCONTOS = 0;
         if (VALOR IS NULL) then
          VALORPG = 0;
         RECEBER = RECEBER + (VALOR+JUROS-DESCONTOS-VALORPG);
       end
     end

     if (PLANO = '2.2') then
     begin
       for SELECT PAG_VALOR, PAG_JUROS, PAG_DESCONTOS, SUM(PP_DINHEIRO+PP_CHEQUE)
       FROM PAGAMENTOS, PAG_PGM, FATURAMENTO2
       WHERE PAG_CODIGO = PP_PAG AND FAT2_TIPO = 2 AND PAG_FAT2 = FAT2_CODIGO AND (PAG_SITUACAO >= 0 AND PAG_SITUACAO < 3) AND PAG_ESTADO < 3
       AND PAG_VENCIMENTO = :DATA1
       GROUP BY PAG_VALOR, PAG_JUROS, PAG_DESCONTOS
       into :VALOR, :JUROS, :DESCONTOS, :VALORPG do
       begin
         if (VALOR IS NULL) then
          VALOR = 0;
         if (VALOR IS NULL) then
          JUROS = 0;
         if (VALOR IS NULL) then
          DESCONTOS = 0;
         if (VALOR IS NULL) then
          VALORPG = 0;
         RECEBER = RECEBER + (VALOR+JUROS-DESCONTOS-VALORPG);
       end
     end
     if (PLANO = '2.3') then
     begin
       for SELECT PAG_VALOR, PAG_JUROS, PAG_DESCONTOS, SUM(PP_DINHEIRO+PP_CHEQUE)
       FROM PAGAMENTOS, PAG_PGM, FATURAMENTO2
       WHERE PAG_CODIGO = PP_PAG AND FAT2_TIPO = 3 AND PAG_FAT2 = FAT2_CODIGO AND (PAG_SITUACAO >= 0 AND PAG_SITUACAO < 3) AND PAG_ESTADO < 3
       AND PAG_VENCIMENTO = :DATA1
       GROUP BY PAG_VALOR, PAG_JUROS, PAG_DESCONTOS
       into :VALOR, :JUROS, :DESCONTOS, :VALORPG do
       begin
         if (VALOR IS NULL) then
          VALOR = 0;
         if (VALOR IS NULL) then
          JUROS = 0;
         if (VALOR IS NULL) then
          DESCONTOS = 0;
         if (VALOR IS NULL) then
          VALORPG = 0;
         RECEBER = RECEBER + (VALOR+JUROS-DESCONTOS-VALORPG);
       end
     end
     if (PLANO = '2.4') then
     begin
       for SELECT PAG_VALOR, PAG_JUROS, PAG_DESCONTOS, SUM(PP_DINHEIRO+PP_CHEQUE)
       FROM PAGAMENTOS, PAG_PGM, FATURAMENTO2
       WHERE PAG_CODIGO = PP_PAG AND FAT2_TIPO = 4 AND PAG_FAT2 = FAT2_CODIGO AND (PAG_SITUACAO >= 0 AND PAG_SITUACAO < 3) AND PAG_ESTADO < 3
       AND PAG_VENCIMENTO = :DATA1
       GROUP BY PAG_VALOR, PAG_JUROS, PAG_DESCONTOS
       into :VALOR, :JUROS, :DESCONTOS, :VALORPG do
       begin
         if (VALOR IS NULL) then
          VALOR = 0;
         if (VALOR IS NULL) then
          JUROS = 0;
         if (VALOR IS NULL) then
          DESCONTOS = 0;
         if (VALOR IS NULL) then
          VALORPG = 0;
         RECEBER = RECEBER + (VALOR+JUROS-DESCONTOS-VALORPG);
       end
     end
     if (PLANO = '2.5') then
     begin
       DIA1 = EXTRACT(DAY FROM :DATA1);
       SELECT SUM(FUN_SALARIO) FROM FUNCIONARIOS
       WHERE FUN_ESTADO = 'ATIVO' AND FUN_DATAPGM = :DIA1
       INTO :VALOR;
       if (VALOR IS NULL) then
        VALOR = 0;
       RECEBER = RECEBER + VALOR;
     end
     if (PLANO = '2.10') then
     begin
       for SELECT PAG_VALOR, PAG_JUROS, PAG_DESCONTOS, SUM(PP_DINHEIRO+PP_CHEQUE)
       FROM PAGAMENTOS, PAG_PGM, FATURAMENTO2
       WHERE PAG_CODIGO = PP_PAG AND FAT2_TIPO = 6 AND PAG_FAT2 = FAT2_CODIGO AND (PAG_SITUACAO >= 0 AND PAG_SITUACAO < 3) AND PAG_ESTADO < 3
       AND PAG_VENCIMENTO = :DATA1
       GROUP BY PAG_VALOR, PAG_JUROS, PAG_DESCONTOS
       into :VALOR, :JUROS, :DESCONTOS, :VALORPG do
       begin
         if (VALOR IS NULL) then
          VALOR = 0;
         if (VALOR IS NULL) then
          JUROS = 0;
         if (VALOR IS NULL) then
          DESCONTOS = 0;
         if (VALOR IS NULL) then
          VALORPG = 0;
         RECEBER = RECEBER + (VALOR+JUROS-DESCONTOS-VALORPG);
       end
     end
  /* Procedure Text */
  suspend;
end^


ALTER PROCEDURE SOMA_FOLHA (
    CODIGO INTEGER,
    DATA1 DATE,
    DATA2 DATE)
RETURNS (
    VALE FLOAT,
    INSS FLOAT,
    SAL_FAMILIA FLOAT,
    HORA_EXTRA FLOAT,
    HORA_FALTA FLOAT,
    VALORPG FLOAT)
AS
BEGIN
     SELECT SUM(AF_VALOR) FROM ADIANTAMENTO_FOLHA WHERE AF_FOL = :CODIGO AND AF_DATA BETWEEN :DATA1 AND :DATA2
     INTO VALE;
     SELECT SUM(F13_VALOR) FROM FERIAS_13 WHERE F13_TIPO = 2 AND F13_FOL = :CODIGO AND F13_DATAPGM BETWEEN :DATA1 AND :DATA2
     INTO SAL_FAMILIA;
     SELECT SUM(F13_VALOR) FROM FERIAS_13 WHERE F13_TIPO = 3 AND F13_FOL = :CODIGO AND F13_DATAPGM BETWEEN :DATA1 AND :DATA2
     INTO INSS;
     SELECT SUM(HEX_VALOR*HEX_HORAS) FROM HEXTRA WHERE HEX_FOL = :CODIGO AND HEX_VALOR > 0 AND HEX_DATA BETWEEN :DATA1 AND :DATA2
     INTO HORA_EXTRA;
     SELECT SUM(HEX_VALOR*HEX_HORAS) FROM HEXTRA WHERE HEX_FOL = :CODIGO AND HEX_VALOR < 0 AND HEX_DATA BETWEEN :DATA1 AND :DATA2
     INTO HORA_FALTA;
     SELECT (FOL_VALORL) FROM FOLHA_PAGAMENTOS WHERE FOL_CODIGO = :CODIGO AND FOL_DATAPGM BETWEEN :DATA1 AND :DATA2
     INTO VALORPG;

     if (VALE IS NULL) then
      VALE = 0;
     if (INSS IS NULL) then
      INSS = 0;
     if (SAL_FAMILIA IS NULL) then
      SAL_FAMILIA = 0;
     if (HORA_EXTRA IS NULL) then
      HORA_EXTRA = 0;
     if (VALORPG IS NULL) then
      VALORPG = 0;
END^


