    CODIGO INTEGER)
RETURNS (
    VALE FLOAT,
    INSS FLOAT,
    SAL_FAMILIA FLOAT,
    HORA_EXTRA FLOAT,
    HORA_FALTA FLOAT,
    VALORPG FLOAT)
AS
BEGIN
     SELECT SUM(AF_VALOR) FROM ADIANTAMENTO_FOLHA WHERE AF_FOL = :CODIGO
     INTO VALE;
     SELECT SUM(F13_VALOR) FROM FERIAS_13 WHERE F13_TIPO = 2 AND F13_FOL = :CODIGO
     INTO SAL_FAMILIA;
     SELECT SUM(F13_VALOR) FROM FERIAS_13 WHERE F13_TIPO = 3 AND F13_FOL = :CODIGO
     INTO INSS;
     SELECT SUM(HEX_VALOR*HEX_HORAS) FROM HEXTRA WHERE HEX_FOL = :CODIGO AND HEX_VALOR > 0
     INTO HORA_EXTRA;
     SELECT SUM(HEX_VALOR*HEX_HORAS) FROM HEXTRA WHERE HEX_FOL = :CODIGO AND HEX_VALOR < 0
     INTO HORA_FALTA;
     SELECT (FOL_VALORL) FROM FOLHA_PAGAMENTOS WHERE FOL_CODIGO = :CODIGO
     INTO VALORPG;
     if (VALE IS NULL) then
      VALE = 0;
     if (INSS IS NULL) then
      INSS = 0;
     if (SAL_FAMILIA IS NULL) then
      SAL_FAMILIA = 0;
     if (HORA_EXTRA IS NULL) then
      HORA_EXTRA = 0;
     if (VALORPG IS NULL) then
      VALORPG = 0;
END^


ALTER PROCEDURE SOMA_PAG (
    CODIGO INTEGER,
    TIPO VARCHAR(15))
RETURNS (
    SOMA_VALOR FLOAT,
    SOMA_JUROS FLOAT,
    SOMA_DESC FLOAT,
    SOMA_DINHEIRO FLOAT,
    SOMA_CHEQUE FLOAT)
AS
BEGIN
     IF (TIPO = 'Compra') THEN
     BEGIN
      SELECT SUM(P.PAG_VALOR), SUM(P.PAG_JUROS), SUM(P.PAG_DESCONTOS)
      FROM FORNECEDORES FO, FATURAMENTO2 F, PAGAMENTOS P, COMPRAS C
      WHERE C.COM_FOR = FO.FOR_CODIGO AND F.FAT2_TIPO = 1 AND F.FAT2_DESCRICAO = C.COM_CODIGO AND F.FAT2_CODIGO = P.PAG_FAT2 AND P.PAG_ESTADO <> 3 AND FO.FOR_CODIGO = :CODIGO
      INTO :Soma_Valor, :Soma_Juros, :Soma_Desc;
      SELECT SUM(PP.PP_DINHEIRO), SUM(PP.PP_CHEQUE)
      FROM FORNECEDORES FO, FATURAMENTO2 F, PAGAMENTOS P, COMPRAS C, PAG_PGM PP
      WHERE C.COM_FOR = FO.FOR_CODIGO AND F.FAT2_TIPO = 1 AND F.FAT2_DESCRICAO = C.COM_CODIGO AND PP.PP_PAG = P.PAG_CODIGO AND P.PAG_FAT2 = F.FAT2_CODIGO AND P.PAG_ESTADO = 2 AND FO.FOR_CODIGO = :CODIGO
      INTO :Soma_Dinheiro, :Soma_Cheque;
     END
     ELSE IF (TIPO = 'Despesa') THEN
     BEGIN
      SELECT SUM(P.PAG_VALOR), SUM(P.PAG_JUROS), SUM(P.PAG_DESCONTOS)
      FROM SUB_DES SD, FATURAMENTO2 F, PAGAMENTOS P, CUSTOS C
      WHERE C.CUST_SUD = SD.SUD_CODIGO AND F.FAT2_TIPO = 2 AND F.FAT2_DESCRICAO = C.CUST_CODIGO AND F.FAT2_CODIGO = P.PAG_FAT2 AND P.PAG_ESTADO <> 3 AND SD.SUD_CODIGO = :CODIGO
      INTO :Soma_Valor, :Soma_Juros, :Soma_Desc;
      SELECT SUM(PP.PP_DINHEIRO), SUM(PP.PP_CHEQUE)
      FROM SUB_DES SD, FATURAMENTO2 F, PAGAMENTOS P, CUSTOS C, PAG_PGM PP
      WHERE C.CUST_SUD = SD.SUD_CODIGO AND F.FAT2_TIPO = 2 AND F.FAT2_DESCRICAO = C.CUST_CODIGO AND PP.PP_PAG = P.PAG_CODIGO AND P.PAG_FAT2 = F.FAT2_CODIGO AND P.PAG_ESTADO = 2 AND SD.SUD_CODIGO = :CODIGO
      INTO :Soma_Dinheiro, :Soma_Cheque;
     END
     ELSE IF (TIPO = 'Imposto') THEN
     BEGIN
      SELECT SUM(P.PAG_VALOR), SUM(P.PAG_JUROS), SUM(P.PAG_DESCONTOS)
      FROM IMPOSTOS I, FATURAMENTO2 F, PAGAMENTOS P, TRIBUTACOES T
      WHERE T.TRI_IMP = I.IMP_CODIGO AND F.FAT2_TIPO = 3 AND F.FAT2_DESCRICAO = T.TRI_CODIGO AND F.FAT2_CODIGO = P.PAG_FAT2 AND P.PAG_ESTADO <> 3 AND I.IMP_CODIGO = :CODIGO
      INTO :Soma_Valor, :Soma_Juros, :Soma_Desc;
      SELECT SUM(PP.PP_DINHEIRO), SUM(PP.PP_CHEQUE)
      FROM IMPOSTOS I, FATURAMENTO2 F, PAGAMENTOS P, TRIBUTACOES T, PAG_PGM PP
      WHERE T.TRI_IMP = I.IMP_CODIGO AND F.FAT2_TIPO = 3 AND F.FAT2_DESCRICAO = T.TRI_CODIGO AND PP.PP_PAG = P.PAG_CODIGO AND P.PAG_FAT2 = F.FAT2_CODIGO AND P.PAG_ESTADO = 2 AND I.IMP_CODIGO = :CODIGO
      INTO :Soma_Dinheiro, :Soma_Cheque;
     END
     ELSE IF (TIPO = 'Frete') THEN
     BEGIN
      SELECT SUM(P.PAG_VALOR), SUM(P.PAG_JUROS), SUM(P.PAG_DESCONTOS)
      FROM TRANSPORTADORAS T, FATURAMENTO2 F, PAGAMENTOS P, FRETES FR
      WHERE FR.FRE_TRA = T.TRA_CODIGO AND F.FAT2_TIPO = 4 AND F.FAT2_DESCRICAO = FR.FRE_CODIGO AND F.FAT2_CODIGO = P.PAG_FAT2 AND P.PAG_ESTADO <> 3 AND T.TRA_CODIGO = :CODIGO
      INTO :Soma_Valor, :Soma_Juros, :Soma_Desc;
      SELECT SUM(PP.PP_DINHEIRO), SUM(PP.PP_CHEQUE)
      FROM TRANSPORTADORAS T, FATURAMENTO2 F, PAGAMENTOS P, FRETES FR, PAG_PGM PP
      WHERE FR.FRE_TRA = T.TRA_CODIGO AND F.FAT2_TIPO = 4 AND F.FAT2_DESCRICAO = FR.FRE_CODIGO AND PP.PP_PAG = P.PAG_CODIGO AND P.PAG_FAT2 = F.FAT2_CODIGO AND P.PAG_ESTADO = 2 AND T.TRA_CODIGO = :CODIGO
      INTO :Soma_Dinheiro, :Soma_Cheque;
     END
END^


ALTER PROCEDURE SOMA_PAGAD_A (
    DATA1 DATE,
    DATA2 DATE,
    CODIGO INTEGER)
RETURNS (
    TOTAL FLOAT)
AS
BEGIN
     SELECT SUM(PP.PP_DINHEIRO+PP.PP_CHEQUE)
     FROM PAGAMENTOS P, PAG_PGM PP, FATURAMENTO2 F, CUSTOS C, SUB_DES S, DESPESAS D
     WHERE D.DES_CODIGO = S.SUD_DES AND S.SUD_CODIGO = C.CUST_SUD AND P.PAG_CODIGO = PP.PP_PAG AND F.FAT2_CODIGO = P.PAG_FAT2
     AND F.FAT2_TIPO = 2 AND F.FAT2_DESCRICAO = C.CUST_CODIGO AND P.PAG_ESTADO <> 1 AND PP.PP_DATAPGM IS NOT NULL AND D.DES_CODIGO = :CODIGO
     AND PP.PP_DATAPGM BETWEEN :DATA1 AND :DATA2
     INTO :TOTAL;
END^


ALTER PROCEDURE SOMA_REC (
    COD_CLIENTE INTEGER)
RETURNS (
    SOMA_VALOR FLOAT,
    SOMA_JUROS FLOAT,
    SOMA_DESC FLOAT,
    SOMA_DINHEIRO FLOAT,
    SOMA_CHEQUE FLOAT)
AS
BEGIN
     SELECT SUM(R.REC_VALOR), SUM(R.REC_JUROS), SUM(R.REC_DESCONTOS)
     FROM CLIENTES C, FATURAMENTOS F, RECEBIMENTOS R
     WHERE F.FAT_CLI = C.CLI_CODIGO AND F.FAT_CODIGO = R.REC_FAT AND R.REC_ESTADO <> 3 AND C.CLI_CODIGO = :Cod_Cliente
     INTO :Soma_Valor, :Soma_Juros, :Soma_Desc;
     SELECT SUM(RP.RP_DINHEIRO), SUM(RP.RP_CHEQUE)
     FROM CLIENTES C, FATURAMENTOS F, RECEBIMENTOS R, REC_PGM RP
     WHERE F.FAT_CLI = C.CLI_CODIGO AND F.FAT_CODIGO = R.REC_FAT AND RP.RP_REC = R.REC_CODIGO AND R.REC_ESTADO = 2 AND C.CLI_CODIGO = :Cod_Cliente
     INTO :Soma_Dinheiro, :Soma_Cheque;
END^


ALTER PROCEDURE SOMA_REC_DEV (
    CODIGO INTEGER)
RETURNS (
    VALOR_REC FLOAT,
    VALORPG_REC FLOAT)
AS
DECLARE VARIABLE VALOR FLOAT;
DECLARE VARIABLE JUROS FLOAT;
DECLARE VARIABLE DESCONTOS FLOAT;
DECLARE VARIABLE DINHEIRO FLOAT;
DECLARE VARIABLE CHEQUE FLOAT;
BEGIN
     SELECT SUM(R.REC_VALOR), SUM(R.REC_JUROS), SUM(R.REC_DESCONTOS)
     FROM RECEBIMENTOS R, FATURAMENTOS F, VENDAS V, VEN_EST VE
     WHERE V.VEN_CODIGO = VE.VE_VEN AND F.FAT_TIPO = 1 AND F.FAT_DESCRICAO = V.VEN_CODIGO AND
     F.FAT_CODIGO = R.REC_FAT AND VE.VE_CODIGO = :CODIGO
     INTO :VALOR, :JUROS, :DESCONTOS;
     VALOR_REC = :VALOR + :JUROS - :DESCONTOS;
     SELECT SUM(RP.RP_DINHEIRO), SUM(RP.RP_CHEQUE)
     FROM REC_PGM RP, RECEBIMENTOS R, FATURAMENTOS F, VENDAS V, VEN_EST VE
     WHERE V.VEN_CODIGO = VE.VE_VEN AND F.FAT_TIPO = 1 AND F.FAT_DESCRICAO = V.VEN_CODIGO AND
     F.FAT_CODIGO = R.REC_FAT AND R.REC_CODIGO = RP.RP_REC AND VE.VE_CODIGO = :CODIGO
     INTO :DINHEIRO, :CHEQUE;
     VALORPG_REC = :DINHEIRO + :CHEQUE;
END^


ALTER PROCEDURE SOMA_VALORPG (
    CODIGO INTEGER,
    TIPO VARCHAR(20))
RETURNS (
    VALOR_PG FLOAT)
AS
DECLARE VARIABLE Dinheiro FLOAT;
DECLARE VARIABLE Cheque FLOAT;
BEGIN
     IF (:Tipo = 'Recebimento') THEN
     BEGIN
      SELECT SUM(RP.RP_DINHEIRO), SUM(RP.RP_CHEQUE)
      FROM REC_PGM RP, RECEBIMENTOS R
      WHERE R.REC_CODIGO = RP.RP_REC AND R.REC_CODIGO = :Codigo
      INTO :Dinheiro, :Cheque;
     END
     ELSE IF (:Tipo = 'Pagamento') THEN
     BEGIN
      SELECT SUM(PP.PP_DINHEIRO), SUM(PP.PP_CHEQUE)
      FROM PAG_PGM PP, PAGAMENTOS P
      WHERE P.PAG_CODIGO = PP.PP_PAG AND P.PAG_CODIGO = :Codigo
      INTO :Dinheiro, :Cheque;
     END
     Valor_pg = Dinheiro + Cheque;
END^


ALTER PROCEDURE TRANSFERE_MOVIMENTACAO_CONTAS (
    DESTINO INTEGER,
    COD_MOV_TRANSF INTEGER)
AS
declare variable ORIGEM integer;
declare variable CREDITO float;
declare variable DEBITO float;
declare variable DATA_MOV TIMESTAMP;
DECLARE VARIABLE MOV_COD INTEGER;
BEGIN
  --RECUPERO ALGUNS DADOS DA MOVIMENTACAO
  SELECT MOV_DATAHORA, MOV_CON, MOV_CREDITO, MOV_DEBITO FROM MOVIMENTACOES
  WHERE MOV_CODIGO = :COD_MOV_TRANSF
  INTO :DATA_MOV, :ORIGEM, :CREDITO, :DEBITO;
  /*<<<Conta Destino>>>*/
  --Atualiza a movimentacao com o codigo da conta Destino
  UPDATE MOVIMENTACOES SET MOV_CON = :DESTINO WHERE MOV_CODIGO = :COD_MOV_TRANSF;
  --Conserta o saldo da conta Destino, ja que foi "inserido" um registro
  EXECUTE PROCEDURE AJUSTA_SALDO_ANT(:COD_MOV_TRANSF);
  --Atualiza o saldo da conta Destino
  UPDATE CONTAS SET CON_SALDO = CON_SALDO + :CREDITO - :DEBITO
  WHERE CON_CODIGO = :DESTINO;
  /*<<<Conta Origem>>>*/
  /*ATUALIZO O SALDO ANTERIOR EM TODOS OS REGISTROS COM DATA MAIOR DO QUE O REGISTRO "DELETADO"*/
  FOR SELECT MOV_CODIGO FROM MOVIMENTACOES
  WHERE MOV_CON = :ORIGEM AND MOV_DATAHORA > :DATA_MOV
  ORDER BY MOV_DATAHORA, MOV_CODIGO
  INTO :MOV_COD DO
  BEGIN
    --Como o registro foi tirado da Conta, os valores de Credito e Debito estao invertidos
    UPDATE MOVIMENTACOES SET MOV_SALDOANT = MOV_SALDOANT - :CREDITO + :DEBITO
    WHERE MOV_CODIGO = :MOV_COD;
  END
  --Atualiza o saldo da conta Origem (Invertendo Credito e Debito)
  UPDATE CONTAS SET CON_SALDO = CON_SALDO - :CREDITO + :DEBITO
  WHERE CON_CODIGO = :ORIGEM;
END^


ALTER PROCEDURE ULTIMA_VENDA_CLI (
    CODIGO INTEGER,
    DATA DATE)
AS
BEGIN
     UPDATE CLIENTES SET CLI_DATAU = :DATA WHERE CLI_CODIGO = :CODIGO;
END^


